private void datiEnteMarketingEnrich(AlpacaJsonOptionsStructure optionsStr, EnteDto enteDto,
                                     JsonObject alpacaJsonData) {
    List<String> datiEnteDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr, datiEnteMarketing);
