                            JsonObject alpacaJsonData) {
    List<String> sediEnteDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr, sediEnteTypes);
    if (Validator.isNotNull(sediEnteDataContainer) && !sediEnteDataContainer.isEmpty()) {
        for (String field : sediEnteDataContainer) {
            JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(field);
            if (Validator.isNotNull(fieldDataContainer)) {
                fieldDataContainer.addProperty("partitaIva", partitaIvaCodiceFiscale);
                alpacaJsonData.add(field, fieldDataContainer);
