private void configurazioneAccreditamentoEnrich(AlpacaJsonOptionsStructure optionsStr, EnteDto enteDto,
                                                JsonObject alpacaJsonData, User profiloUtenteCittadino) {
    List<String> configurazioneAccreditamentoDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr,
            configurazioneAccreditamentoTypes);
    if (Validator.isNotNull(configurazioneAccreditamentoDataContainer)
            && !configurazioneAccreditamentoDataContainer.isEmpty()) {
        for (String field : configurazioneAccreditamentoDataContainer) {
            JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(field);
            if (Validator.isNotNull(fieldDataContainer)) {
                if (Validator.isNotNull(enteDto)) {
                    if (Validator.isNotNull(enteDto.getPersone()) && !enteDto.getPersone().isEmpty()) {
                        List<SoggettoEnteRuoloDto> persone = enteDto.getPersone();
                        for (SoggettoEnteRuoloDto persona : persone) {
                            if (Validator.isNotNull(persona.getRuolo())) {
                                RuoloDto ruoloDto = persona.getRuolo();
                                if (ruoloDto.getCodice().equalsIgnoreCase("DELEGATO")) {
                                    if (Validator.isNotNull(persona.getSoggetto())) {
                                        SoggettoDto soggettoDto = persona.getSoggetto();
                                        if (soggettoDto.getCodiceFiscale()
                                                .equalsIgnoreCase(profiloUtenteCittadino.getScreenName())) {
                                            fieldDataContainer.addProperty("isDelegato", true);
                                            alpacaJsonData.add(field, fieldDataContainer);
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

