package it.servizidigitali.presentatoreforms.bandi.frontend.portlet.resource;

import com.google.gson.JsonObject;
import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.portlet.bridges.mvc.BaseMVCResourceCommand;
import com.liferay.portal.kernel.portlet.bridges.mvc.MVCResourceCommand;
import com.liferay.portal.kernel.util.PortalUtil;
import com.liferay.portal.kernel.util.Validator;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;

import javax.portlet.ResourceRequest;
import javax.portlet.ResourceResponse;
import javax.servlet.http.HttpServletRequest;

import org.osgi.service.component.annotations.Component;

import it.servizidigitali.gestionebandi.common.util.ImportoUtils;
import it.servizidigitali.presentatoreforms.bandi.frontend.constants.PresentatoreFormsPortletKeys;

/**
 * Resource Command per il calcolo dei valori derivati del custom field
 * Alpaca InformazioniDiProgetto (bando CER JTF Regione Puglia).
 *
 * Invocato via AJAX dal bottone "Calcola" del custom field.
 *
 * Formule applicate:
 *   percEcond            = (econd / eprod) * 100
 *   efficaciaOperazione  = costoTotale / ((eaa[kWh] / 1000) * FA), FA = 14,09
 *   massimaleSpesa       = p1*1500 + p2*1200 + p3*1100 + p4*1050 + acc*900
 *   risorseAggiuntive    = costoTotale - finanziamentoPubblico
 *   percCofinanziamento  = (risorseAggiuntive / costoTotale) * 100
 */
@Component(
		immediate = true,
		property = {
				"javax.portlet.name=" + PresentatoreFormsPortletKeys.PRESENTATOREFORMS,
				"mvc.command.name=" + PresentatoreFormsPortletKeys.CALCOLA_INFORMAZIONI_DI_PROGETTO
		},
		service = MVCResourceCommand.class
)
public class CalcolaInformazioniDiProgettoResourceCommand extends BaseMVCResourceCommand {

	private static final Log _log = LogFactoryUtil.getLog(CalcolaInformazioniDiProgettoResourceCommand.class);

	private static final String STATUS_OK = "OK";
	private static final String STATUS_KO = "KO";

	private static final BigDecimal FATTORE_ANNUALITA = new BigDecimal("14.09");
	private static final BigDecimal MILLE = new BigDecimal("1000");
	private static final BigDecimal CENTO = new BigDecimal("100");

	private static final BigDecimal COEFF_P1 = new BigDecimal("1500");
	private static final BigDecimal COEFF_P2 = new BigDecimal("1200");
	private static final BigDecimal COEFF_P3 = new BigDecimal("1100");
	private static final BigDecimal COEFF_P4 = new BigDecimal("1050");
	private static final BigDecimal COEFF_ACC = new BigDecimal("900");

	private static final int SCALE_INTERMEDIO = 10;
	private static final int SCALE_OUTPUT = 2;

	@Override
	protected void doServeResource(ResourceRequest resourceRequest, ResourceResponse resourceResponse)
			throws Exception {

		HttpServletRequest httpReq = PortalUtil.getHttpServletRequest(resourceRequest);
		HttpServletRequest httpOrigReq = PortalUtil.getOriginalServletRequest(httpReq);

		BigDecimal p1 = ImportoUtils.parseImporto(httpOrigReq.getParameter("P1"));
		BigDecimal p2 = ImportoUtils.parseImporto(httpOrigReq.getParameter("P2"));
		BigDecimal p3 = ImportoUtils.parseImporto(httpOrigReq.getParameter("P3"));
		BigDecimal p4 = ImportoUtils.parseImporto(httpOrigReq.getParameter("P4"));
		BigDecimal acc = ImportoUtils.parseImporto(httpOrigReq.getParameter("acc"));
		BigDecimal econd = ImportoUtils.parseImporto(httpOrigReq.getParameter("econd"));
		BigDecimal eprod = ImportoUtils.parseImporto(httpOrigReq.getParameter("eprod"));
		BigDecimal eaa = ImportoUtils.parseImporto(httpOrigReq.getParameter("eaa"));
		BigDecimal costoTotale = ImportoUtils.parseImporto(httpOrigReq.getParameter("costoTotale"));
		BigDecimal finanziamentoPubblico = ImportoUtils.parseImporto(httpOrigReq.getParameter("finanziamentoPubblico"));

		JsonObject payload = new JsonObject();

		try {
			if (Validator.isNotNull(finanziamentoPubblico) && Validator.isNotNull(costoTotale)
					&& finanziamentoPubblico.compareTo(costoTotale) > 0) {
				payload.addProperty("status", STATUS_KO);
				payload.addProperty("errorMessage", "Il finanziamento pubblico richiesto deve essere minore o uguale al costo totale dell'operazione");

				String jsonKo = payload.toString();
				resourceResponse.setContentType("application/json");
				resourceResponse.setCharacterEncoding("UTF-8");
				resourceResponse.getPortletOutputStream().write(jsonKo.getBytes(StandardCharsets.UTF_8));
				return;
			}

			BigDecimal percEcond = _safeDivide(econd, eprod).multiply(CENTO).setScale(SCALE_OUTPUT, RoundingMode.HALF_UP);

			// EAa è in kWh: portarlo in MWh prima di moltiplicare per FA
			BigDecimal eaaMWh = eaa.divide(MILLE, SCALE_INTERMEDIO, RoundingMode.HALF_UP);
			BigDecimal divisoreEfficacia = eaaMWh.multiply(FATTORE_ANNUALITA);
			BigDecimal efficaciaOperazione = _safeDivide(costoTotale, divisoreEfficacia).setScale(SCALE_OUTPUT, RoundingMode.HALF_UP);

			BigDecimal massimaleSpesa = p1.multiply(COEFF_P1)
					.add(p2.multiply(COEFF_P2))
					.add(p3.multiply(COEFF_P3))
					.add(p4.multiply(COEFF_P4))
					.add(acc.multiply(COEFF_ACC))
					.setScale(SCALE_OUTPUT, RoundingMode.HALF_UP);

			BigDecimal risorseAggiuntive = costoTotale.subtract(finanziamentoPubblico).setScale(SCALE_OUTPUT, RoundingMode.HALF_UP);

			BigDecimal percCofinanziamento = _safeDivide(risorseAggiuntive, costoTotale).multiply(CENTO).setScale(SCALE_OUTPUT, RoundingMode.HALF_UP);

			payload.addProperty("status", STATUS_OK);
			payload.addProperty("percEcond", ImportoUtils.formattaImportoItaliano(percEcond));
			payload.addProperty("efficaciaOperazione", ImportoUtils.formattaImportoItaliano(efficaciaOperazione));
			payload.addProperty("massimaleSpesa", ImportoUtils.formattaImportoItaliano(massimaleSpesa));
			payload.addProperty("risorseAggiuntive", ImportoUtils.formattaImportoItaliano(risorseAggiuntive));
			payload.addProperty("percCofinanziamento", ImportoUtils.formattaImportoItaliano(percCofinanziamento));
		}
		catch (Exception e) {
			_log.error("Errore nel calcolo InformazioniDiProgetto: " + e.getMessage(), e);
			payload.addProperty("status", STATUS_KO);
			payload.addProperty("errorMessage", "Errore nel calcolo dei dati di progetto");
		}

		String json = payload.toString();

		resourceResponse.setContentType("application/json");
		resourceResponse.setCharacterEncoding("UTF-8");
		resourceResponse.getPortletOutputStream().write(json.getBytes(StandardCharsets.UTF_8));
	}

	private BigDecimal _safeDivide(BigDecimal dividend, BigDecimal divisor) {
		if (Validator.isNull(divisor) || divisor.compareTo(BigDecimal.ZERO) == 0) {
			return BigDecimal.ZERO;
		}
		return dividend.divide(divisor, SCALE_INTERMEDIO, RoundingMode.HALF_UP);
	}

}

