    private boolean checkAbilitaVisualizzazione(DomandaBando domandaBando) {
        boolean check = true;

        String statoDomanda = null;
        if (Validator.isNotNull(domandaBando.getStatoId())) {
//			statoDomanda = statoDomandaLocalService.fetchStatoDomanda(domandaBando.getStatoId()).getDescrizione();
            statoDomanda = statoDomandaBandoLocalService
                    .getStatoDomandaBandoByBandoIdAndStatoId(domandaBando.getBandoId(), domandaBando.getStatoId())
                    .getDescrizione();
        } else {
            statoDomanda = domandaBando.getStato();
        }

        /*
         * Non più necessario avendo spostato il flag su statoDomandaBando
         * List<StatoDomanda> statiDomanda =
         * statoDomandaBandoLocalService.getStatoDomandaBandoByBandoId(domandaBando.
         * getBandoId()) .stream() .map(statoDomandaBando ->
         * statoDomandaBando.getStatoId()) .map(statoDomandaId ->
         * statoDomandaLocalService.fetchStatoDomanda(statoDomandaId)) .filter(stato ->
