         */

        List<StatoDomandaBando> statiDomandaBando = statoDomandaBandoLocalService
                .getStatoDomandaBandoByBandoId(domandaBando.getBandoId());
        for (StatoDomandaBando s : statiDomandaBando) {
            if (s.getDescrizione().replaceAll("_", "").equalsIgnoreCase(statoDomanda.toUpperCase()))
