    public DomandaBando createOrUpdateDomandaBando(User user, long bandoId, String dataForm, String stato,
                                                   long groupId) {
        DomandaBando domandaBando = null;
        IstanzaDomandaBando istanzaDomandaBando = null;
        Bando bando = null;
        Form form = null;
        BandoForm bandoForm = null;
        Gson gson = new Gson();
        AlpacaJsonStructure alpacaStructure = gson.fromJson(dataForm, AlpacaJsonStructure.class);

        try {
            if (Validator.isNotNull(alpacaStructure)) {
                FormData formData = new FormData();
                formData.setAlpaca(alpacaStructure);
                String jsonToSave = gson.toJson(formData);

                // recupero richiesta se esiste altrimenti ne creo una nuova
                domandaBando = getDomandaBandoBozza(user.getScreenName(), bandoId);
                form = getFormBando(bandoId);
                bandoForm = getBandoForm(bandoId);
                bando = bandoLocalService.getBando(bandoId);
                if (Validator.isNotNull(form)) {

                    if (Validator.isNotNull(StatoDomandaBandoEnum.valueOf(stato))) {
                        // recupero richiesta esistente
                        if (Validator.isNotNull(domandaBando)) {
                            log.debug("Recuperata domanda bando in stato BOZZA con id: " + domandaBando.getBandoId());

                            if (Validator.isNotNull(bandoForm)) {
                                istanzaDomandaBando = getIstanzaDomandaBando(domandaBando.getDomandaBandoId(),
                                        form.getFormId());
                            }

                        } else {
                            // creazione nuova richiesta
                            domandaBando = domandaBandoLocalService.createDomandaBando(counterLocalService.increment());
                            domandaBando.setCodiceFiscale(user.getScreenName().toUpperCase());
                            domandaBando.setUserId(user.getUserId());
                            domandaBando.setUserName(user.getFullName());
                            domandaBando.setBandoId(bandoId);
                            domandaBando.setOggetto(bando.getNome());
                            domandaBando.setStato(StatoDomandaBandoEnum.BOZZA.name());
                            domandaBando.setGroupId(groupId);
                            domandaBando = domandaBandoLocalService.updateDomandaBando(domandaBando);

                            istanzaDomandaBando = istanzaDomandaBandoLocalService
                                    .createIstanzaDomandaBando(counterLocalService.increment());
                            istanzaDomandaBando.setGroupId(groupId);
                            istanzaDomandaBando.setUserId(user.getUserId());
                            istanzaDomandaBando.setUserName(user.getFullName());
                            istanzaDomandaBando.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        }
                        // aggiorno stato richiesta
                        domandaBando.setStato(stato);
                        domandaBandoLocalService.updateDomandaBando(domandaBando);
                        // aggiorno json in istanza form
                        istanzaDomandaBando.setJson(jsonToSave);
                        istanzaDomandaBando.setVersioneForm(form.getVersione());
                        istanzaDomandaBando.setFormId(form.getFormId());
                        istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA.name());
                        istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);
                    } else {
                        log.error("Valore non valido per lo stato della richiesta: " + stato);
                    }
                } else {
                    log.error("Nessun form principale associato alla procedura con id: " + 0);
                }
            }
        } catch (Exception e) {
            log.error(e.getMessage());
        }

        return domandaBando;

    }

    private void estraiPartiteIva(JsonNode fieldValues, String nomeCampo, List<String> listaPartiteIva) {
        if (fieldValues != null) {
            JsonNode soggettiAti = fieldValues.get(0);

            if (soggettiAti != null) {
                JsonNode campoGenerico = soggettiAti.get(nomeCampo);

                if (campoGenerico != null && campoGenerico.size() > 0) {
                    for (JsonNode elemento : campoGenerico) {
                        String partitaIva = "";

                        if (elemento.has("partitaIva") && !elemento.get("partitaIva").isNull()) {
                            partitaIva = elemento.get("partitaIva").asText();

                            if (Validator.isNotNull(partitaIva)) {
                                listaPartiteIva.add(partitaIva);
                            }
                        }
                    }
                }
            }
        }
    }

    private List<String> getPartiteIva(IstanzaDomandaBando istanzaDomandaBando, String portalURL, long bandoId)
            throws PortalException {
        List<String> listaPartiteIva = new ArrayList<String>();
        String jsonForm = istanzaDomandaBando.getJson();

        if (Validator.isNotNull(jsonForm)) {
            Set<Option> jsonPathOptions = new HashSet<Option>();
            jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
            jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

            Configuration jsonPathConfiguration = Configuration.builder()
                    .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
                    .options(jsonPathOptions).build();

            JsonNode fieldValues = null;
            JsonNode soggettiAti = null;

            List<String> listaCampiRegistroImpresa = getNomeCampoByType(jsonForm, portalURL, typesRegistroImpresa,
                    istanzaDomandaBando.getFormId());

            if (ListUtil.isNotNull(listaCampiRegistroImpresa) && ListUtil.isNotEmpty(listaCampiRegistroImpresa)) {
                for (String campo : listaCampiRegistroImpresa) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                if (fieldValues != null) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = null;

                        if (nodeInfo.has("tipoSoggetto")) {
                            String tipoSoggetto = nodeInfo.get("tipoSoggetto").asText();

                            if (Validator.isNotNull(tipoSoggetto)) {

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.LR.name())) {
                                    nodeInterno = nodeInfo.get("privato");
                                }

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.SD.name())) {
                                    nodeInterno = nodeInfo.get("privatoDelegato");
                                }
                            }
                        }

                        if (nodeInterno != null) {

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                String pIva = nodeInterno.get("pIva").asText();

                                if (Validator.isNotNull(pIva)) {
                                    listaPartiteIva.add(pIva);
                                }
                            }

                        }
                    }
                }
            } else {
                List<String> listaCampiRegistroImpresaConfigurabile = getNomeCampoByType(jsonForm, portalURL, typesCustomRegistroImpreseConfigurabile,
                        istanzaDomandaBando.getFormId());

                if (ListUtil.isNotNull(listaCampiRegistroImpresaConfigurabile) && ListUtil.isNotEmpty(listaCampiRegistroImpresaConfigurabile)) {
                    for (String campo : listaCampiRegistroImpresaConfigurabile) {
                        String pathCampo = "['" + campo + "']";
                        JsonNode fieldValuesOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + pathCampo);

                        if (Validator.isNotNull(fieldValuesOptions) && !fieldValuesOptions.isEmpty()) {
                            JsonNode options = fieldValuesOptions.get(0);
                            if (options.has("fieldClass")) {
                                String fieldClass = options.get("fieldClass").asText();
                                if (Validator.isNotNull(fieldClass) && fieldClass.contains("soggettoDelegante")) {
                                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                                    break;
                                }
                            }
                        }

                    }

                    if (Validator.isNotNull(fieldValues)) {
                        JsonNode nodeInfo = fieldValues.get(0);

                        if (nodeInfo != null && !nodeInfo.isEmpty()) {

                            JsonNode nodeInterno = nodeInfo.get("privato");

                            if (Validator.isNotNull(nodeInterno)) {

                                if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                    String pIva = nodeInterno.get("pIva").asText();

                                    if (Validator.isNotNull(pIva)) {
                                        listaPartiteIva.add(pIva);
                                    }
                                }

                            }
                        }
                    }
                }
                Bando bando = bandoLocalService.getBando(bandoId);
                if (bando.isObbligoAccreditamentoEnte()) {
                    List<String> listaCampiAccreditamento = getNomeCampoByType(jsonForm, portalURL,
                            datiEnteRecuperoTypes, istanzaDomandaBando.getFormId());

                    if (Validator.isNotNull(listaCampiAccreditamento) && !listaCampiAccreditamento.isEmpty()) {
                        for (String campo : listaCampiAccreditamento) {
                            String pathCampo = "['" + campo + "']";
                            fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                        }

                        if (Validator.isNotNull(fieldValues)) {
                            JsonNode nodeInfo = fieldValues.get(0);

                            if (nodeInfo != null && !nodeInfo.isEmpty()) {

                                JsonNode nodeInterno = nodeInfo.get("privato");

                                if (Validator.isNotNull(nodeInterno)) {

                                    if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                        String pIva = nodeInterno.get("pIva").asText();

                                        if (Validator.isNotNull(pIva)) {
                                            listaPartiteIva.add(pIva);
                                        }
                                    }

                                }
                            }
                        }
                    }
                }

                List<String> listaCampiSoggettiATIATS = getNomeCampoByType(jsonForm, portalURL, typesSoggettiATIATS,
                        istanzaDomandaBando.getFormId());

                for (String campo : listaCampiSoggettiATIATS) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                estraiPartiteIva(fieldValues,"partner", listaPartiteIva);

            }

            List<String> listaCampiCustomMandanti = getNomeCampoByType(jsonForm, portalURL, typesCustomMandanti,
                    istanzaDomandaBando.getFormId());

            for (String campo : listaCampiCustomMandanti) {
                String pathCampo = "['" + campo + "']";
                fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                        .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
            }
            estraiPartiteIva(fieldValues, "mandanti", listaPartiteIva);

            List<String> listaCampiPartnerAgricoltura = getNomeCampoByType(jsonForm, portalURL, typesPartnerAgricoltura,
                    istanzaDomandaBando.getFormId());

            if (listaCampiPartnerAgricoltura != null && !listaCampiPartnerAgricoltura.isEmpty()) {
                for (String campo : listaCampiPartnerAgricoltura) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                if (fieldValues != null) {
                    JsonNode root = fieldValues.get(0);
                    if (root != null) {
                        JsonNode partnerArray = root.get("partner");
                        if (partnerArray != null && partnerArray.size() > 0) {
                            for (JsonNode elemPartner : partnerArray) {
                                if (Validator.isNotNull(elemPartner) && Validator.isNotNull(elemPartner.get("datiPartner"))) {
                                    JsonNode datiPartner = elemPartner.get("datiPartner");
                                    if (datiPartner.has("codiceFiscale") && !datiPartner.get("codiceFiscale").isNull()) {
                                        String codiceFiscale = datiPartner.get("codiceFiscale").asText();
                                        if (Validator.isNotNull(codiceFiscale)) {
                                            listaPartiteIva.add(codiceFiscale);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            Form form = getFormBando(bandoId);
            List<FormField> listaField = new ArrayList<FormField>();

            if (Validator.isNotNull(form)) {
                for (String type : typesCustomSoggettiATIATS) {
                    JsonPathUtil.processPropertiesCustomFields(listaField, form.getJson(), "", "", type);

                    if (Validator.isNotNull(listaField) && !listaField.isEmpty()) {
                        JsonNode partner = null;

                        if (Validator.isNotNull(listaField.get(0))
                                && Validator.isNotNull(listaField.get(0).getPath())) {
                            String field = listaField.get(0).getPath()
                                    .substring(listaField.get(0).getPath().indexOf(".") + 1);

                            String arrayField = field.substring(field.indexOf("["), field.indexOf("]") + 1);

                            if (Validator.isNotNull(arrayField)) {
                                String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + arrayField;
                                partner = JsonPath.using(jsonPathConfiguration).parse(jsonForm).read(jsonPathInterno);

                                if (Validator.isNotNull(partner) && Validator.isNotNull(partner.get(0))) {

                                    JsonNode arrayPartner = partner.get(0);

                                    for (JsonNode elemPartner : arrayPartner) {
                                        if (Validator.isNotNull(elemPartner)) {

                                            if (Validator.isNotNull(elemPartner.get("datiPartner"))) {
                                                JsonNode datiPartner = elemPartner.get("datiPartner");

                                                if (Validator.isNotNull(datiPartner.get("partitaIva"))) {
                                                    String partitaIva = datiPartner.get("partitaIva").asText();

                                                    if (Validator.isNotNull(partitaIva)) {
                                                        listaPartiteIva.add(partitaIva);
                                                    }
                                                } else if (Validator.isNotNull(datiPartner.get("codiceFiscale"))
                                                        && Validator.isNull(datiPartner.get("partitaIva"))) {
                                                    String codiceFiscale = datiPartner.get("codiceFiscale").asText();

                                                    if (Validator.isNotNull(codiceFiscale)) {
                                                        listaPartiteIva.add(codiceFiscale);
                                                    }
                                                }

                                            }
                                        }
                                    }

                                }
                            }
                        }

                    }
                }

            }

        }

        return listaPartiteIva;
    }

    public List<ErroreValidazionePartitaIvaDTO> validaPartiteIvaDomanda(Bando bando,
                                                                        IstanzaDomandaBando istanzaDomandaBando, Locale locale, String portalURL) throws PortalException {
        List<ErroreValidazionePartitaIvaDTO> listaErrori = new ArrayList<ErroreValidazionePartitaIvaDTO>();
        List<String> listaPartiteIva = getPartiteIva(istanzaDomandaBando, portalURL, bando.getBandoId());
        ResourceBundleLoader resourceBundleLoader = ResourceBundleLoaderUtil
                .getResourceBundleLoaderByBundleSymbolicName(PresentatoreFormsPortletKeys.BUNDLE_SYMBOLIC_NAME);

        if (listaPartiteIva != null && !listaPartiteIva.isEmpty()) {
            for (String partitaIva : listaPartiteIva) {
                if (!bando.getDomandaMultiplaIndividuale()) {
                    long countByPartitaIvaAndBandoId = domandaBandoLocalService
                            .countAziendeNonAssociateByPartitaIvaAndBandoId(partitaIva, bando.getBandoId());

                    if (countByPartitaIvaAndBandoId > 0) {

                        ErroreValidazionePartitaIvaDTO erroreDto = new ErroreValidazionePartitaIvaDTO();

                        String messaggioErrore = resourceBundleLoader.loadResourceBundle(locale)
                                .getString("errore-domanda-multipla-individuale");

                        if (Validator.isNotNull(messaggioErrore)) {
                            erroreDto.setErrore(messaggioErrore);
                        }

                        erroreDto.setPartitaIva(partitaIva);
                        listaErrori.add(erroreDto);
                    }

                }

                if (!bando.getDomandaMultiplaRti()) {
                    long countAziendeAssociateByPartitaIvaAndBandoId = domandaBandoLocalService
                            .countAziendeAssociateByPartitaIvaAndBandoId(partitaIva, bando.getBandoId());

                    if (countAziendeAssociateByPartitaIvaAndBandoId > 0) {

                        ErroreValidazionePartitaIvaDTO erroreDto = new ErroreValidazionePartitaIvaDTO();

                        String messaggioErrore = resourceBundleLoader.loadResourceBundle(locale)
                                .getString("errore-domanda-multipla-rti");

                        if (Validator.isNotNull(messaggioErrore)) {
                            erroreDto.setErrore(messaggioErrore);
                        }

                        erroreDto.setPartitaIva(partitaIva);
                        listaErrori.add(erroreDto);
                    }

                }
            }
        }

        return listaErrori;
    }

    public void addExtraFieldsDomandaBando(IstanzaDomandaBando istanzaDomandaBando, String portalURL) {
        String jsonForm = istanzaDomandaBando.getJson();
        String ragioneSociale = "";
        String pIva = "";
        String titoloProgetto = "";
        BigDecimal importoRichiesto = null;
        BigDecimal costiAmmissibili = null;
        String cfLegaleRappresentante = "";
        String cfEnte = "";
        String pecRichiedente = "";

        String cap = "";

        if (Validator.isNotNull(jsonForm)) {
            Set<Option> jsonPathOptions = new HashSet<Option>();
            jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
            jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

            Configuration jsonPathConfiguration = Configuration.builder()
                    .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
                    .options(jsonPathOptions).build();

            JsonNode fieldValues = null;

            List<String> listaCampiRegistroImpresa = getNomeCampoByType(jsonForm, portalURL, typesRegistroImpresa,
                    istanzaDomandaBando.getFormId());

            List<String> listaCampiSedeLegale = new ArrayList<String>();
            List<String> listaCampiRegistroImpresaConfigurabile = new ArrayList<String>();
            List<String> listaDatiEnte = new ArrayList<String>();
            List<String> listaCampiImpresaEstero = new ArrayList<String>();
            if (Validator.isNotNull(listaCampiRegistroImpresa) && !listaCampiRegistroImpresa.isEmpty()) {
                for (String campo : listaCampiRegistroImpresa) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }
            } else {
                listaCampiSedeLegale = getNomeCampoByType(jsonForm, portalURL, typesSedeLegale,
                        istanzaDomandaBando.getFormId());

                if (Validator.isNotNull(listaCampiSedeLegale) && !listaCampiSedeLegale.isEmpty()) {
                    for (String campo : listaCampiSedeLegale) {
                        String pathCampo = "['" + campo + "']";
                        fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                    }
                }
            }

            if (Validator.isNull(fieldValues)) {
                listaCampiRegistroImpresaConfigurabile = getNomeCampoByType(jsonForm, portalURL,
                        typesCustomRegistroImpreseConfigurabile, istanzaDomandaBando.getFormId());

                if (Validator.isNotNull(listaCampiRegistroImpresaConfigurabile)
                        && !listaCampiRegistroImpresaConfigurabile.isEmpty()) {
                    for (String campo : listaCampiRegistroImpresaConfigurabile) {
                        String pathCampo = "['" + campo + "']";
                        JsonNode fieldValuesOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + pathCampo);

                        if (Validator.isNotNull(fieldValuesOptions) && !fieldValuesOptions.isEmpty()) {
                            JsonNode options = fieldValuesOptions.get(0);
                            if (options.has("fieldClass")) {
                                String fieldClass = options.get("fieldClass").asText();
                                if (Validator.isNotNull(fieldClass) && fieldClass.contains("soggettoDelegante")) {
                                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                                    break;
                                }
                            }
                        }

                    }
                }
            }

            if (Validator.isNull(fieldValues)) {
                listaDatiEnte = getNomeCampoByType(jsonForm, portalURL, datiEnteRecuperoTypes,
                        istanzaDomandaBando.getFormId());
                if (Validator.isNotNull(listaDatiEnte) && !listaDatiEnte.isEmpty()) {
                    for (String campo : listaDatiEnte) {
                        String pathCampo = "['" + campo + "']";
                        fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                    }
                }
            }

            if (Validator.isNull(fieldValues)) {
                listaCampiImpresaEstero = getNomeCampoByType(jsonForm, portalURL, typesDatiImpresaEstero,
                        istanzaDomandaBando.getFormId());
                if (ListUtil.isNotNull(listaCampiImpresaEstero) && ListUtil.isNotEmpty(listaCampiImpresaEstero)) {
                    for (String campo : listaCampiImpresaEstero) {
                        String pathCampo = "['" + campo + "']";
                        fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                        break;
                    }

                }
            }

            if (Validator.isNotNull(fieldValues)) {

                if (Validator.isNotNull(listaCampiRegistroImpresa) && !listaCampiRegistroImpresa.isEmpty()) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = null;

                        if (nodeInfo.has("tipoSoggetto")) {
                            String tipoSoggetto = nodeInfo.get("tipoSoggetto").asText();

                            if (Validator.isNotNull(tipoSoggetto)) {

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.LR.name())) {
                                    nodeInterno = nodeInfo.get("privato");
                                }

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.SD.name())) {
                                    nodeInterno = nodeInfo.get("privatoDelegato");
                                }
                            }
                        }

                        if (nodeInterno != null) {

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                    && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                pIva = nodeInterno.get("pIva").asText();
                            }

                        }
                    }
                } else if (Validator.isNotNull(listaCampiRegistroImpresaConfigurabile)
                        && !listaCampiRegistroImpresaConfigurabile.isEmpty()) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = nodeInfo.get("privato");

                        if (Validator.isNotNull(nodeInterno)) {

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                    && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                pIva = nodeInterno.get("pIva").asText();
                            }

                            if (nodeInterno.has("cap") && !nodeInterno.get("cap").isNull()) {
                                cap = nodeInterno.get("cap").asText();
                            }

                            if (Validator.isNotNull(cap)) {
                                List<String> listaCampiSedeOperativa = new ArrayList<String>();
                                listaCampiSedeOperativa = getNomeCampoByType(jsonForm, portalURL,
                                        typesCustomSedeOperativa, istanzaDomandaBando.getFormId());
                                JsonNode fieldValuesSedeOperativa = null;
                                if (Validator.isNotNull(listaCampiSedeOperativa)
                                        && !listaCampiSedeOperativa.isEmpty()) {
                                    for (String campo : listaCampiSedeOperativa) {
                                        String pathCampo = "['" + campo + "']";
                                        fieldValuesSedeOperativa = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                                    }
                                }

                                if (Validator.isNotNull(fieldValuesSedeOperativa)
                                        && !fieldValuesSedeOperativa.isEmpty()) {
                                    JsonNode nodeInfoSO = fieldValuesSedeOperativa.get(0);
                                    if (Validator.isNotNull(nodeInfoSO) && !nodeInfoSO.isEmpty()) {
                                        if (nodeInfoSO.has("capOperativa")
                                                && !nodeInfoSO.get("capOperativa").isNull()) {
                                            cap = nodeInfoSO.get("capOperativa").asText();
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else if (Validator.isNotNull(listaDatiEnte) && !listaDatiEnte.isEmpty()) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = nodeInfo.get("privato");

                        if (Validator.isNotNull(nodeInterno)) {

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                pIva = nodeInterno.get("pIva").asText();
                            } else if (nodeInterno.has("cfAzienda") && !nodeInterno.get("cfAzienda").isNull()) {
                                pIva = nodeInterno.get("cfAzienda").asText();
                            }

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore") && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }

                        }
                    }
                } else if (ListUtil.isNotNull(listaCampiImpresaEstero)
                        && ListUtil.isNotEmpty(listaCampiImpresaEstero)) {

                    if (ListUtil.isNotNull(listaCampiImpresaEstero) && ListUtil.isNotEmpty(listaCampiImpresaEstero)) {
                        for (String campo : listaCampiImpresaEstero) {
                            String pathCampo = "['" + campo + "']";
                            fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                            break;
                        }

                        if (Validator.isNotNull(fieldValues)) {
                            JsonNode nodeInfo = fieldValues.get(0);
                            JsonNode nodeInterno = null;

                            if (nodeInfo != null && !nodeInfo.isEmpty()) {

                                if (nodeInfo.has("residenzaFiscale")) {
                                    String residenzaFiscale = nodeInfo.get("residenzaFiscale").asText();
                                    if (residenzaFiscale.equalsIgnoreCase("Italia")) {
                                        nodeInterno = nodeInfo.get("nazionale");
                                    } else if (residenzaFiscale.equalsIgnoreCase("Estero")) {
                                        nodeInterno = nodeInfo.get("estero");
                                    }
                                }
                            }

                            if (Validator.isNotNull(nodeInterno)) {

                                if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                        && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                    ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                                }

                                if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                    pIva = nodeInterno.get("pIva").asText();
                                }
                            }
                        }
                    }
                } else if (ListUtil.isNotNull(listaCampiImpresaEstero)
                        && ListUtil.isNotEmpty(listaCampiImpresaEstero)) {
                    JsonNode nodeInfo = fieldValues.get(0);
                    JsonNode nodeInterno = null;

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        if (nodeInfo.has("residenzaFiscale")) {
                            String residenzaFiscale = nodeInfo.get("residenzaFiscale").asText();
                            if (residenzaFiscale.equalsIgnoreCase("Italia")) {
                                nodeInterno = nodeInfo.get("nazionale");
                            } else if (residenzaFiscale.equalsIgnoreCase("Estero")) {
                                nodeInterno = nodeInfo.get("estero");
                            }
                        }

                        if (Validator.isNotNull(nodeInterno)) {

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                pIva = nodeInterno.get("pIva").asText();
                            }

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                    && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }
                        }
                    }
                } else {
                    if (Validator.isNotNull(listaCampiSedeLegale) && !listaCampiSedeLegale.isEmpty()) {
                        JsonNode nodeInfo = fieldValues.get(0);

                        if (nodeInfo.has("ragioneSociale")) {
                            if (Validator.isNotNull(nodeInfo.get("ragioneSociale").asText())) {
                                ragioneSociale = nodeInfo.get("ragioneSociale").asText();
                            }
                        } else {
                            JsonNode fieldValuesNome = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + "['NomeEnte']");
                            if (Validator.isNotNull(fieldValuesNome) && !fieldValuesNome.isEmpty()) {
                                if (Validator.isNotNull(fieldValuesNome.get(0).asText())) {
                                    ragioneSociale = fieldValuesNome.get(0).asText();
                                }
