                JsonNode fieldValuesPIva = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                        .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + "['datiEnte']");

                if (Validator.isNotNull(fieldValuesNome) && !fieldValuesNome.isEmpty()
                        && Validator.isNotNull(fieldValuesPIva) && !fieldValuesPIva.isEmpty()) {
                    JsonNode nodeInfo = fieldValuesPIva.get(0);

                    if (nodeInfo.has("codFiscalePiva")) {
                        if (Validator.isNotNull(nodeInfo.get("codFiscalePiva").asText())) {
                            pIva = nodeInfo.get("codFiscalePiva").asText();
                        }
                    }

                    if (Validator.isNotNull(fieldValuesNome.get(0).asText())) {
                        ragioneSociale = fieldValuesNome.get(0).asText();
                    }
                }
            }

            List<String> listaCampiInterventoRegionale = getNomeCampoByType(jsonForm, portalURL,
                    typesInterventoRegionale, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesInterventoRegionale = null;

            for (String campo : listaCampiInterventoRegionale) {
                String pathCampo = "['" + campo + "']";
                fieldValuesInterventoRegionale = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                        .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
            }

            if (fieldValuesInterventoRegionale != null) {
                JsonNode nodeInfoInterventoRegionale = fieldValuesInterventoRegionale.get(0);

                if (nodeInfoInterventoRegionale != null && !nodeInfoInterventoRegionale.isEmpty()) {
                    String importoRichiestoForm = nodeInfoInterventoRegionale.get(FormFieldsPath.NAME_IMPORTO_RICHIESTO)
                            .asText();

                    if (Validator.isNotNull(importoRichiestoForm)) {
                        importoRichiesto = new BigDecimal(importoRichiestoForm.replaceAll(",", "."));
                    }

                    String costoAmmissibileForm = nodeInfoInterventoRegionale.get(FormFieldsPath.NAME_COSTI_AMMISSIBILI)
                            .asText();

                    if (Validator.isNotNull(costoAmmissibileForm)) {
                        costiAmmissibili = new BigDecimal(costoAmmissibileForm.replaceAll(",", "."));
                    }
                }
            } else {
                List<FormField> listaFieldsCampiImporto = new ArrayList<>();
                List<FormField> listaFieldsCampiImportoCalcolato = new ArrayList<>();

                DomandaBando domandaBando = null;
                try {
                    domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
                } catch (PortalException e) {
                    log.error(e);
                }
                Form form = null;
                if (Validator.isNotNull(domandaBando)) {
                    form = getFormBando(domandaBando.getBandoId());
                }

                if (Validator.isNotNull(form)) {
                    for (String typeImporto: typesImporto) {
                        JsonPathUtil.processPropertiesCustomFields(listaFieldsCampiImporto, form.getJson(), "", "",
                                typeImporto);

                        for (FormField campo : listaFieldsCampiImporto) {
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + field;
                            JsonNode fieldValuesImporto = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathInterno);

                            JsonNode nodeImporto = fieldValuesImporto.get(0);
                            if (Validator.isNotNull(nodeImporto)) {
                                importoRichiesto = new BigDecimal(nodeImporto.asText());
                            }

                        }
                    }

                    if (ListUtil.isNull(listaFieldsCampiImporto) || ListUtil.isEmpty(listaFieldsCampiImporto)) {
                        JsonPathUtil.processPropertiesCustomFields(listaFieldsCampiImportoCalcolato, form.getJson(), "",
                                "", typeImportoCalcolato);

                        for (FormField campo : listaFieldsCampiImportoCalcolato) {
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + field;
                            String optionsField = field.replaceAll("\\]\\['", "]['fields']['");
                            String jsonPathOptionsFields = ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD
                                    + ALPACA_FIELDS_FIELD + optionsField;
                            JsonNode fieldValuesImporto = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathInterno);
                            JsonNode fieldValuesImportoOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathOptionsFields);

                            JsonNode nodeImporto = fieldValuesImporto.get(0);
                            JsonNode nodeImportoOptions = fieldValuesImportoOptions.get(0);
                            if (Validator.isNotNull(nodeImporto)) {
                                if (Validator.isNotNull(nodeImportoOptions)) {
                                    if (nodeImportoOptions.has("importoRichiesto")) {
                                        JsonNode importoRichiestoField = nodeImportoOptions.get("importoRichiesto");
                                        if (importoRichiestoField.booleanValue()) {
                                            importoRichiesto = new BigDecimal(nodeImporto.asText());
                                        }
                                    }
                                }
                            }

                        }
                    }
                }

                if (importoRichiesto == null && Validator.isNotNull(form)) {
                    List<FormField> listaFieldsCostiDiretti = new ArrayList<>();
                    JsonPathUtil.processPropertiesCustomFields(listaFieldsCostiDiretti, form.getJson(), "", "",
                            typeCostiDiretti);

                    for (FormField campo : listaFieldsCostiDiretti) {
                        if (campo.getPath().contains("costiDirettiApBContrTotale")) {
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + field;
                            JsonNode fieldValuesCostiDiretti = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathInterno);

                            JsonNode nodeCostiDiretti = fieldValuesCostiDiretti.get(0);
                            if (Validator.isNotNull(nodeCostiDiretti)) {
                                importoRichiesto = new BigDecimal(nodeCostiDiretti.asText());
                            }
                        }
                    }
                }

                if (importoRichiesto == null && Validator.isNotNull(form)) {
                    List<FormField> listaFieldsPostiLettoFinanziamento = new ArrayList<>();
                    JsonPathUtil.processPropertiesCustomFields(listaFieldsPostiLettoFinanziamento, form.getJson(), "", "",
                            typePostiLettoFinanziamento);

                    for (FormField campo : listaFieldsPostiLettoFinanziamento) {
                        if (campo.getPath().contains("importo")) {
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + field;
                            JsonNode fieldValuesPostiLetto = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathInterno);

                            JsonNode nodeImportoPostiLetto = fieldValuesPostiLetto.get(0);
                            if (Validator.isNotNull(nodeImportoPostiLetto)) {
                                importoRichiesto = ImportoUtils.parseImporto(nodeImportoPostiLetto.asText());
                            }
                        }
                    }
                }

                if (importoRichiesto == null && Validator.isNotNull(form)) {
                    List<FormField> listaFieldsInformazioniProgetto = new ArrayList<>();
                    JsonPathUtil.processPropertiesCustomFields(listaFieldsInformazioniProgetto, form.getJson(), "", "",
                            typeInformazioniDiProgetto);

                    for (FormField campo : listaFieldsInformazioniProgetto) {
                        if (campo.getPath().contains("finanziamentoPubblico")) {
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + field;
                            JsonNode fieldValuesFinanziamentoPubblico = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                    .read(jsonPathInterno);

                            JsonNode nodeFinanziamentoPubblico = fieldValuesFinanziamentoPubblico.get(0);
                            if (Validator.isNotNull(nodeFinanziamentoPubblico)) {
                                importoRichiesto = ImportoUtils.parseImporto(nodeFinanziamentoPubblico.asText());
                            }
                        }
                    }
                }
            }

            fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                    .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + FormFieldsPath.PATH_TITOLO_PROGETTO);

            if (fieldValues != null && !fieldValues.isEmpty()) {

                if (Validator.isNotNull(fieldValues.get(0).asText())) {
                    titoloProgetto = fieldValues.get(0).asText();
                }

            } else {
                List<String> listaTitolo = getNomeCampoByType(jsonForm, portalURL, typesTitolo,
                        istanzaDomandaBando.getFormId());

                JsonNode fieldValuesTitolo = null;

                for (String campo : listaTitolo) {
                    String pathCampo = "['" + campo + "']";
                    fieldValuesTitolo = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                if (Validator.isNotNull(fieldValuesTitolo)) {
                    JsonNode nodeTitolo = fieldValuesTitolo.get(0);

                    if (Validator.isNotNull(nodeTitolo) && !nodeTitolo.isEmpty()) {
                        String titoloRichiestoForm = nodeTitolo.get(FormFieldsPath.TITOLO_PROGETTO).asText();

                        if (Validator.isNotNull(titoloRichiestoForm)) {
                            titoloProgetto = titoloRichiestoForm;
                        }
                    }
                }
            }

            List<String> listaCampiLegaleRappresentante = getNomeCampoByType(jsonForm, portalURL,
                    typesCustomGestioneLegaleRappresentante, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesLR = null;
            if (Validator.isNotNull(listaCampiLegaleRappresentante) && !listaCampiLegaleRappresentante.isEmpty()) {
                for (String campo : listaCampiLegaleRappresentante) {
                    String pathCampo = "['" + campo + "']";
                    fieldValuesLR = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }
            }

            if (Validator.isNotNull(fieldValuesLR)) {
                JsonNode nodeInfo = fieldValuesLR.get(0);

                String tipologiaSoggetto = "";
                if (nodeInfo.has("tipologiaSoggetto")) {
                    if (Validator.isNotNull(nodeInfo.get("tipologiaSoggetto").asText())) {
                        tipologiaSoggetto = nodeInfo.get("tipologiaSoggetto").asText();
                    }
                }

                if (Validator.isNotNull(tipologiaSoggetto)) {
                    if (tipologiaSoggetto.equalsIgnoreCase("soggetto_delegato")) {
                        if (nodeInfo.has("codiceFiscale")) {
                            if (Validator.isNotNull(nodeInfo.get("codiceFiscale").asText())) {
                                cfLegaleRappresentante = nodeInfo.get("codiceFiscale").asText();
                            }
                        }
                    }
                }
            }

            List<String> listaDatiAnagraficiConfigurabile = getNomeCampoByType(jsonForm, portalURL,
                    datiAnagraficiConfigurabiliTypes, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesDatiAnagrafici = null;
            if (Validator.isNotNull(listaDatiAnagraficiConfigurabile) && !listaDatiAnagraficiConfigurabile.isEmpty()) {
                for (String campo : listaDatiAnagraficiConfigurabile) {
                    String pathCampo = "['" + campo + "']";
                    JsonNode fieldValuesOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + pathCampo);

                    if (Validator.isNotNull(fieldValuesOptions) && !fieldValuesOptions.isEmpty()) {
                        JsonNode options = fieldValuesOptions.get(0);
                        if (options.has("fields")) {
                            JsonNode fields = options.get("fields");
                            if (fields.has("configurazione")) {
                                JsonNode configurazione = fields.get("configurazione");
                                if (Validator.isNotNull(configurazione) && configurazione.has("datiReadOnly")) {
                                    boolean datiReadOnly = configurazione.get("datiReadOnly").asBoolean();
                                    if (datiReadOnly) {
                                        fieldValuesDatiAnagrafici = JsonPath.using(jsonPathConfiguration)
                                                .parse(jsonForm)
                                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                                    }
                                }
                            }
                        }
                    }

                }
            }

            if (Validator.isNotNull(fieldValuesDatiAnagrafici)) {
                JsonNode nodeInfo = fieldValuesDatiAnagrafici.get(0);

                if (nodeInfo.has("pec")) {
                    if (Validator.isNotNull(nodeInfo.get("pec").asText())) {
                        pecRichiedente = nodeInfo.get("pec").asText();
                    }
                }
            }

            List<String> listaDatiAnagraficaUnica = getNomeCampoByType(jsonForm, portalURL,
                    customRegistroImpreseAnagraficaUnicaRecuperoPec, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesAnagraficaUnica = null;

            if (Validator.isNotNull(listaDatiAnagraficaUnica) && !listaDatiAnagraficaUnica.isEmpty()) {
                for (String campo : listaDatiAnagraficaUnica) {
                    String pathCampo = "['" + campo + "']";
                    fieldValuesAnagraficaUnica = JsonPath.using(jsonPathConfiguration)
                            .parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }
            }

            if (Validator.isNotNull(fieldValuesAnagraficaUnica)) {
                JsonNode nodeInfo = fieldValuesAnagraficaUnica.get(0);
                JsonNode privato = nodeInfo.get("privato");
                if (privato.has("pec")) {
                    if (Validator.isNotNull(privato.get("pec").asText())) {
                        pecRichiedente = privato.get("pec").asText();
                    }
                }
            }
            if (istanzaDomandaBando.getDomandaBandoId() > 0) {
                User user = userLocalService.fetchUser(istanzaDomandaBando.getUserId());

                try {
                    DomandaBando domandaBando = domandaBandoLocalService
                            .getDomandaBando(istanzaDomandaBando.getDomandaBandoId());

                    if (Validator.isNotNull(user)) {
                        String emailAggiuntiva = user.getExpandoBridge()
                                .getAttribute(UserCustomAttributes.EMAIL_AGGIUNTIVA.getNomeAttributo()).toString();

                        if (Validator.isNotNull(emailAggiuntiva)) {
                            domandaBando.setEmail(emailAggiuntiva);
                        } else {
                            domandaBando.setEmail(user.getEmailAddress());
                        }

                    }

                    if (Validator.isNotNull(pIva)) {
                        domandaBando.setPartitaIva(pIva);
                    }

                    if (Validator.isNotNull(ragioneSociale)) {
                        domandaBando.setRagioneSociale(ragioneSociale);
                    }

                    if (Validator.isNotNull(costiAmmissibili)) {
                        domandaBando.setCostiAmmissibili(costiAmmissibili);
                    }

                    if (Validator.isNotNull(importoRichiesto)) {
                        domandaBando.setImportoRichiesto(importoRichiesto);
                    }

                    if (Validator.isNotNull(titoloProgetto)) {
                        domandaBando.setTitoloProgetto(titoloProgetto);
                    }

                    if (Validator.isNotNull(cap)) {
                        domandaBando.setCap(cap);
                    }

                    if (Validator.isNotNull(cfEnte)) {
                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                        domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.CF_ENTE.name());
                        domandaBandoDatoAggiuntivo.setValore(cfEnte);
                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        domandaBandoDatoAggiuntivo.setCompanyId(domandaBando.getCompanyId());
                        domandaBandoDatoAggiuntivo.setUserId(domandaBando.getUserId());
                        domandaBandoDatoAggiuntivo.setUserName(domandaBando.getUserName());
                        domandaBandoDatoAggiuntivo.setGroupId(domandaBando.getGroupId());
                        domandaBandoDatoAggiuntivoLocalService
                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                    }

                    if (Validator.isNotNull(pecRichiedente)) {
                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                        domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.PEC_RICHIEDENTE.name());
                        domandaBandoDatoAggiuntivo.setValore(pecRichiedente);
                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        domandaBandoDatoAggiuntivo.setCompanyId(domandaBando.getCompanyId());
                        domandaBandoDatoAggiuntivo.setUserId(domandaBando.getUserId());
                        domandaBandoDatoAggiuntivo.setUserName(domandaBando.getUserName());
                        domandaBandoDatoAggiuntivo.setGroupId(domandaBando.getGroupId());
                        domandaBandoDatoAggiuntivoLocalService
                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                    }
                    // Salvo i dati del legale rappresentante solo nel caso in cui la custom
                    // dedicata sia presente nel bando
                    if (Validator.isNotNull(fieldValuesLR)) {
                        if (Validator.isNotNull(cfLegaleRappresentante)) {
                            domandaBando.setCfLegaleRappresentante(cfLegaleRappresentante);
                        } else {
                            if (Validator.isNotNull(domandaBando.getCodiceFiscale())) {
                                domandaBando.setCfLegaleRappresentante(domandaBando.getCodiceFiscale());
                            }
                        }
                    }

                    domandaBandoLocalService.updateDomandaBando(domandaBando);

                } catch (Exception e) {
                    log.error(e.getMessage());
                }

            }

            List<String> listaInfoTipologiaEnte = getNomeCampoByType(jsonForm, portalURL,
                    tipologiaEnte, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesTipologiaEnte = null;

            if (Validator.isNotNull(listaInfoTipologiaEnte) && !listaInfoTipologiaEnte.isEmpty()) {
                for (String campo : listaInfoTipologiaEnte) {
                    String pathCampo = "['" + campo + "']";
                    fieldValuesTipologiaEnte = JsonPath.using(jsonPathConfiguration)
                            .parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }
            }

            if (Validator.isNotNull(fieldValuesTipologiaEnte)) {
                String tipologiaEnte = "";
                JsonNode nodeInfo = fieldValuesTipologiaEnte.get(0);
                if (nodeInfo.has("tipologia")) {
                    if (Validator.isNotNull(nodeInfo.get("tipologia").asText())) {
                        tipologiaEnte = nodeInfo.get("tipologia").asText();
                        DomandaBando domandaBando = domandaBandoLocalService
                                .fetchDomandaBando(istanzaDomandaBando.getDomandaBandoId());
                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                        domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.TIPOLOGIA_ENTE.name());
                        domandaBandoDatoAggiuntivo.setValore(tipologiaEnte);
                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                        domandaBandoDatoAggiuntivo.setCompanyId(domandaBando.getCompanyId());
                        domandaBandoDatoAggiuntivo.setUserId(domandaBando.getUserId());
                        domandaBandoDatoAggiuntivo.setUserName(domandaBando.getUserName());
                        domandaBandoDatoAggiuntivo.setGroupId(domandaBando.getGroupId());
                        domandaBandoDatoAggiuntivoLocalService
                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                    }
                }
            }

            List<String> listaCampiCriteriAutovalutazione = getNomeCampoByType(jsonForm, portalURL,
                    typesCustomCriteriAutovalutazione, istanzaDomandaBando.getFormId());

            JsonNode fieldValuesCriteriAutovalutazione = null;
            String pathCampo = null;
            String pathTotalePunti = null;

            if (Validator.isNotNull(listaCampiCriteriAutovalutazione) && !listaCampiCriteriAutovalutazione.isEmpty()) {
                for (String campo : listaCampiCriteriAutovalutazione) {
                    pathCampo = "['" + campo + "']";
                    fieldValuesCriteriAutovalutazione = JsonPath.using(jsonPathConfiguration)
                            .parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);

                    JsonNode optionsCriteriAutovalutazione = JsonPath.using(jsonPathConfiguration)
                            .parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + pathCampo + ALPACA_FIELDS_FIELD);

                    if (optionsCriteriAutovalutazione != null) {
                        JsonNode optionsCriteriAutovalutaioneObj = optionsCriteriAutovalutazione.get(0);
                        for (Iterator<Map.Entry<String, JsonNode>> it = optionsCriteriAutovalutaioneObj.fields(); it.hasNext(); ) {
                            Map.Entry<String, JsonNode> entry = it.next();
                            JsonNode optionField = entry.getValue();
                            if (optionField.isObject() && optionField.has("requisitoChiusuraAutomatica")
                                    && optionField.get("requisitoChiusuraAutomatica").asBoolean(false)) {
                                pathTotalePunti = "$." + pathCampo + "['" + entry.getKey() + "']";
                                break;
                            }
                        }
                    }
                }
            }

            if (Validator.isNotNull(fieldValuesCriteriAutovalutazione)) {
                JsonNode nodeInfoAutovalutazione = fieldValuesCriteriAutovalutazione.get(0);

                if (nodeInfoAutovalutazione != null && !nodeInfoAutovalutazione.isEmpty()) {
                    DomandaBando domandaBandoAutovalutazione = domandaBandoLocalService
                            .fetchDomandaBando(istanzaDomandaBando.getDomandaBandoId());

                    String[] campiTotale = {
                        "dimensioneInternazionalePunti", "numeroDipendentiPunti", "articolazioneProgettoPunti",
                        "sitoWebPunti", "impresaFemminilePunti", "impresaGiovanilePunti",
                        "impresaSostenibilePunti", "coerenzaPunti"
                    };

                    for (String campoTotale : campiTotale) {
                        if (nodeInfoAutovalutazione.has(campoTotale) && !nodeInfoAutovalutazione.get(campoTotale).isNull()) {
                            String valore = nodeInfoAutovalutazione.get(campoTotale).asText();
                            if (Validator.isNotNull(valore)) {
                                DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                        .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                dato.setChiave(DatoAggiuntivoChiave.PUNTEGGIO_AUTOVALUTAZIONE.name());
                                dato.setValore(valore);
                                dato.setDomandaBandoId(domandaBandoAutovalutazione.getDomandaBandoId());
                                dato.setCompanyId(domandaBandoAutovalutazione.getCompanyId());
                                dato.setUserId(domandaBandoAutovalutazione.getUserId());
                                dato.setUserName(domandaBandoAutovalutazione.getUserName());
                                dato.setGroupId(domandaBandoAutovalutazione.getGroupId());
                                domandaBandoDatoAggiuntivoLocalService.addDomandaBandoDatoAggiuntivo(dato);

                            }
                        }
                    }

                    if(Validator.isNotNull(pathTotalePunti)){
                        RequisitoDomandaBando requisitoDomandaBando = requisitoDomandaBandoLocalService.getRequisitoDomandaBandoByBandoIdAndCodice(domandaBandoAutovalutazione.getBandoId(), pathTotalePunti);
                        if(Validator.isNotNull(requisitoDomandaBando)){
                            List<RequisitoDomandaBando> requisitoDomandaBandos = new ArrayList<>();
                            requisitoDomandaBandos.add(requisitoDomandaBando);
                            List<ErroreValidazioneDTO> erroreValidazioneDTOList = validaDomandaBandoService.validaForm(jsonForm, domandaBandoAutovalutazione.getBandoId(), Locale.ITALIAN, requisitoDomandaBandos);

                            if(ListUtil.isNotNull(erroreValidazioneDTOList) && ListUtil.isNotEmpty(erroreValidazioneDTOList)){
                                DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                        .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                dato.setChiave(DatoAggiuntivoChiave.CHIUSURA_NEGATIVA_AUTOMATICA.name());
                                dato.setValore(Boolean.TRUE.toString());
                                dato.setDomandaBandoId(domandaBandoAutovalutazione.getDomandaBandoId());
                                dato.setCompanyId(domandaBandoAutovalutazione.getCompanyId());
                                dato.setUserId(domandaBandoAutovalutazione.getUserId());
                                dato.setUserName(domandaBandoAutovalutazione.getUserName());
                                dato.setGroupId(domandaBandoAutovalutazione.getGroupId());
                                domandaBandoDatoAggiuntivoLocalService.addDomandaBandoDatoAggiuntivo(dato);

                                Bando bandoChiusura = null;
                                try {
                                    bandoChiusura = bandoLocalService.getBando(domandaBandoAutovalutazione.getBandoId());
                                } catch (PortalException e) {
                                    throw new RuntimeException(e);
                                }
                                String codiceBando = bandoChiusura.getCodice();
                                String chiaveNote = "chiusura-negativa-automatica-note-" + codiceBando;
                                ResourceBundleLoader resourceBundleLoaderNote = ResourceBundleLoaderUtil
                                        .getResourceBundleLoaderByBundleSymbolicName(PresentatoreFormsPortletKeys.BUNDLE_SYMBOLIC_NAME);
                                ResourceBundle resourceBundleNote = resourceBundleLoaderNote.loadResourceBundle(LocaleUtil.getDefault());
                                String noteChiusura = ResourceBundleUtil.getString(resourceBundleNote, chiaveNote);

                                if (Validator.isNotNull(noteChiusura) && !noteChiusura.equals(chiaveNote)) {
                                    DomandaBandoDatoAggiuntivo datoNote = domandaBandoDatoAggiuntivoLocalService
                                            .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                    datoNote.setChiave(DatoAggiuntivoChiave.NOTE_CHIUSURA_NEGATIVA.name());
                                    datoNote.setValore(noteChiusura);
                                    datoNote.setDomandaBandoId(domandaBandoAutovalutazione.getDomandaBandoId());
                                    datoNote.setCompanyId(domandaBandoAutovalutazione.getCompanyId());
                                    datoNote.setUserId(domandaBandoAutovalutazione.getUserId());
                                    datoNote.setUserName(domandaBandoAutovalutazione.getUserName());
                                    datoNote.setGroupId(domandaBandoAutovalutazione.getGroupId());
                                    domandaBandoDatoAggiuntivoLocalService.addDomandaBandoDatoAggiuntivo(datoNote);
                                }
                            }
                        }
                    }
                }
            }

        }

    }

