    private void datiIdentificativiEnteAccreditamentoEnrich(AlpacaJsonOptionsStructure optionsStr, EnteDto enteDto,
                                                            JsonObject alpacaJsonData) {
        List<String> datiEnteDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr,
                datiIdentificativiEnteAccreditamento);
        if (Validator.isNotNull(datiEnteDataContainer)) {
            for (String field : datiEnteDataContainer) {
                JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(field);
                JsonObject fieldDataContainerPrivato = fieldDataContainer.getAsJsonObject("privato");
                if (Validator.isNotNull(fieldDataContainerPrivato)) {
                    if (Validator.isNotNull(enteDto)) {
                        fieldDataContainerPrivato.addProperty("pIva", enteDto.getPartitaIva());
                        fieldDataContainerPrivato.addProperty("cfAzienda", enteDto.getPartitaIva());
                        fieldDataContainerPrivato.addProperty("denominazioneSoggettoOrganizzatore",
                                enteDto.getRagioneSociale());
                        RagioneSocialeDto ragioneSocialeDto = enteDto.getRagioneSocialeTipo();
                        if (Validator.isNotNull(ragioneSocialeDto)) {
                            fieldDataContainerPrivato.addProperty("naturaGiuridica",
                                    ragioneSocialeDto.getDescrizione());
                        }
                        List<SedeEnteDto> sedi = enteDto.getSedeEnte();
                        Optional<SedeEnteDto> sedeLegale = Optional.empty();
                        if (Validator.isNotNull(sedi) && !sedi.isEmpty()) {
                            sedeLegale = sedi.stream().filter(sede -> "SEDE_LEGALE".equals(sede.getTipoSede())
                                    || "SEDE_IMPRESA".equals(sede.getTipoSede())).findFirst();
                            if (sedeLegale.isPresent()) {
                                fieldDataContainerPrivato.addProperty("comune", sedeLegale.get().getComune());
                                fieldDataContainerPrivato.addProperty("cap", sedeLegale.get().getCap());
                                fieldDataContainerPrivato.addProperty("viaSedeLegale", sedeLegale.get().getIndirizzo());
                                fieldDataContainerPrivato.addProperty("provincia", sedeLegale.get().getProvincia());
                            }
                        }
                        fieldDataContainerPrivato.addProperty("pec", enteDto.getPec());
                        List<DatoAggiuntivoDto> listaDatiAggiuntivi = enteDto.getListaDatiAggiuntivi();
                        DatoAggiuntivoDto numeroRea = null;
                        if (Validator.isNotNull(listaDatiAggiuntivi) && !listaDatiAggiuntivi.isEmpty()) {
                            Optional<DatoAggiuntivoDto> numeroReaOptional = listaDatiAggiuntivi.stream().filter(
                                            datoAggiuntivoDto -> "NUMERO_REA".equalsIgnoreCase(datoAggiuntivoDto.getChiave()))
                                    .findFirst();
                            if (numeroReaOptional.isPresent()) {
                                numeroRea = numeroReaOptional.get();
                            }

                        }
                        if (Validator.isNotNull(numeroRea)) {
                            fieldDataContainerPrivato.addProperty("numeroRea", numeroRea.getValore());
                        }

                        CodiceAtecoDto codiceAteco = enteDto.getCodiceAteco();
                        if (Validator.isNotNull(codiceAteco)) {
                            fieldDataContainerPrivato.addProperty("codiceAteco", codiceAteco.getCodice());
                        }
                        fieldDataContainerPrivato.addProperty("telefono", enteDto.getTelefono());
                        fieldDataContainerPrivato.addProperty("url",
                                enteDto.getSitoWeb() != null ? enteDto.getSitoWeb() : "");
                        fieldDataContainerPrivato.addProperty("email", enteDto.getEmail());

                        fieldDataContainer.add("privato", fieldDataContainerPrivato);
                        alpacaJsonData.add(field, fieldDataContainer);
                    }
                }
            }
        }
    }

