    private void companyProfileEnrich(AlpacaJsonOptionsStructure optionsStr, EnteDto enteDto,
                                      JsonObject alpacaJsonData) {
        List<String> companyProfileDataContainer = AlpacaUtil.getAllFieldNameDataContainer(optionsStr,
                companyProfileTypes);
        if (Validator.isNotNull(companyProfileDataContainer) && !companyProfileDataContainer.isEmpty()) {
            for (String field : companyProfileDataContainer) {
                JsonObject fieldDataContainer = alpacaJsonData.getAsJsonObject(field);
                if (Validator.isNotNull(fieldDataContainer)) {
                    if (Validator.isNotNull(enteDto)) {
                        fieldDataContainer.addProperty("specializzazioneProduttiva",
                                enteDto.getSpecializzazioneProduttiva().getCodice());
                        fieldDataContainer.addProperty("altraSpecializzazioneProduttiva",
                                enteDto.getAltraSpecializzazioneProduttiva() != null
                                        ? enteDto.getAltraSpecializzazioneProduttiva().getCodice()
                                        : null);
                        fieldDataContainer.addProperty("settoreEconomico", enteDto.getSettoreEconomico().getCodice());
                        fieldDataContainer.addProperty("numDipendenti", enteDto.getNumeroDipendenti().getCodice());
                        fieldDataContainer.addProperty("fatturatoAnnuo", enteDto.getFatturatoAnnuo().getCodice());

                        List<DatoAggiuntivoDto> listaDatiAggiuntivi = enteDto.getListaDatiAggiuntivi();
                        Optional<DatoAggiuntivoDto> annoFondazione = null;
                        Optional<DatoAggiuntivoDto> totaleBilancio = null;
                        Optional<DatoAggiuntivoDto> fatturatoExport = null;
                        Optional<DatoAggiuntivoDto> lingueStraniere = null;
                        Optional<DatoAggiuntivoDto> lingueStraniereAltro = null;
                        if (Validator.isNotNull(listaDatiAggiuntivi) && !listaDatiAggiuntivi.isEmpty()) {
                            annoFondazione = listaDatiAggiuntivi.stream().filter(datoAggiuntivoDto -> "ANNO_FONDAZIONE"
                                    .equalsIgnoreCase(datoAggiuntivoDto.getChiave())).findFirst();
                            totaleBilancio = listaDatiAggiuntivi.stream()
                                    .filter(datoAggiuntivoDto -> "TOTALE_IN_BILANCIO"
                                            .equalsIgnoreCase(datoAggiuntivoDto.getChiave()))
                                    .findFirst();
                            fatturatoExport = listaDatiAggiuntivi.stream()
                                    .filter(datoAggiuntivoDto -> "FATTURATO_EXPORT"
                                            .equalsIgnoreCase(datoAggiuntivoDto.getChiave()))
                                    .findFirst();
                            lingueStraniere = listaDatiAggiuntivi.stream().filter(datoAggiuntivoDto -> "LINGUE_PARLATE"
                                    .equalsIgnoreCase(datoAggiuntivoDto.getChiave())).findFirst();
                            lingueStraniereAltro = listaDatiAggiuntivi.stream()
                                    .filter(datoAggiuntivoDto -> "LINGUA_PARLATA_ALTRO"
                                            .equalsIgnoreCase(datoAggiuntivoDto.getChiave()))
                                    .findFirst();

                            fieldDataContainer.addProperty("annoFondazione",
                                    annoFondazione.isPresent() ? annoFondazione.get().getValore() : "");
                            fieldDataContainer.addProperty("fatturato",
                                    totaleBilancio.isPresent() ? totaleBilancio.get().getValore() : "");
                            fieldDataContainer.addProperty("quotaFatturatoEsportazioni",
                                    fatturatoExport.isPresent() ? fatturatoExport.get().getValore() : "");
                            if (lingueStraniere.isPresent()) {
                                String lingueParlate = lingueStraniere.get().getValore();
                                if (lingueStraniereAltro.isPresent()) {
                                    lingueParlate = lingueParlate.concat(": " + lingueStraniereAltro.get().getValore());
                                }
                                fieldDataContainer.addProperty("lingueStraniere", lingueParlate);

                            }
                        }

                        fieldDataContainer.addProperty("dimensioniImpresa", enteDto.getDimensioneEnte().getCodice());
                        alpacaJsonData.add(field, fieldDataContainer);
                    }
                }
            }
        }
    }

