    public String componiIndietroQuestionarioUrl(DomandaBando domandaBando) throws PortalException {
        Layout layout = layoutLocalService.getLayoutByFriendlyURL(domandaBando.getGroupId(), false,
                SCRIVANIA_CITTADINO_FRIENDLY_URL);
        String paginaServizio = layout.getFriendlyURL(Locale.ROOT);
        LayoutTypePortlet layoutTypePortlet = (LayoutTypePortlet) layout.getLayoutType();
        List<Portlet> allPortlets = layoutTypePortlet.getAllPortlets();
        String instancePortleId = null;
        if (allPortlets != null) {
            for (Portlet portlet : allPortlets) {
                if (portlet.getPortletName().equals(SCRIVANIA_CITTADINO_PORTLET_ID)) {
                    instancePortleId = portlet.getPortletId();
                    break;
                }
            }
        }

        paginaServizio += "?p_p_id=" + instancePortleId;
        paginaServizio += "&_" + instancePortleId + "_mvcRenderCommandName="
                + DETTAGLIO_DOMANDA_BANDO_SCRIVANIA_MVC_RENDER_COMMAND;
        paginaServizio += "&_" + instancePortleId + "_domandaBandoId=" + domandaBando.getDomandaBandoId();

        return paginaServizio;
    }

    public boolean checkIsQuestionario(IstanzaDomandaBando istanzaDomandaBando, Bando bando) {
        boolean isQuestionario = false;
        List<BandoForm> bandoFormList = bandoFormLocalService.getListaBandoFormBandoAndType(bando.getBandoId(),
                TipoFormEnum.QUESTIONARIO.name());

        if (ListUtil.isNotNull(bandoFormList) && ListUtil.isNotEmpty(bandoFormList) && bandoFormList.size() == 1) {
