    public Map<String, String> calcolaPunteggioAutovalutazione(Map<String, String> dati) {
        BigDecimal puntiDimensioneInternazionale = _calcolaPuntiDimensioneInternazionale(dati);
        BigDecimal puntiNumeroDipendenti = _calcolaPuntiNumeroDipendenti(dati);
        BigDecimal puntiArticolazioneProgetto = _calcolaPuntiArticolazioneProgetto(dati);
        BigDecimal puntiSitoWeb = _calcolaPuntiSitoWeb(dati);
        BigDecimal puntiImpresaFemminile = _calcolaPuntiImpresaFemminile(dati);
        BigDecimal puntiImpresaGiovanile = _calcolaPuntiImpresaGiovanile(dati);
        BigDecimal puntiImpresaSostenibile = _calcolaPuntiImpresaSostenibile(dati);
        BigDecimal puntiCoerenza = _calcolaPuntiCoerenza(dati);

        BigDecimal totale = puntiDimensioneInternazionale.add(puntiNumeroDipendenti)
                .add(puntiArticolazioneProgetto).add(puntiSitoWeb)
                .add(puntiImpresaFemminile).add(puntiImpresaGiovanile)
                .add(puntiImpresaSostenibile).add(puntiCoerenza);

        Map<String, String> punteggi = new HashMap<>();
        punteggi.put("dimensioneInternazionale", _formattaPunteggio(puntiDimensioneInternazionale));
        punteggi.put("numeroDipendenti", _formattaPunteggio(puntiNumeroDipendenti));
        punteggi.put("articolazioneProgetto", _formattaPunteggio(puntiArticolazioneProgetto));
        punteggi.put("sitoWeb", _formattaPunteggio(puntiSitoWeb));
        punteggi.put("impresaFemminile", _formattaPunteggio(puntiImpresaFemminile));
        punteggi.put("impresaGiovanile", _formattaPunteggio(puntiImpresaGiovanile));
        punteggi.put("impresaSostenibile", _formattaPunteggio(puntiImpresaSostenibile));
        punteggi.put("coerenza", _formattaPunteggio(puntiCoerenza));
        punteggi.put("totale", _formattaPunteggio(totale));

        return punteggi;
    }

    /**
     * Calcola il punteggio per Dimensione Internazionalizzazione (max 35).
     *
     * Rapporto percentuale = (VE30 + VE34) / VE50 * 100
     *
     * Interpolazione lineare a tratti:
     *   - percentuale 0%   -> 30 punti
     *   - percentuale 10%  -> 35 punti (massimo)
     *   - percentuale 100% ->  0 punti
     *
     * Segmento 0%-10%:   punti = 30 + (percentuale / 10) * 5
     * Segmento 10%-100%: punti = 35 - ((percentuale - 10) / 90) * 35
     */
    private BigDecimal _calcolaPuntiDimensioneInternazionale(Map<String, String> dati) {
        BigDecimal ve30 = _parseImporto(dati.get("valoreCampoVE30Importo"));
        BigDecimal ve34 = _parseImporto(dati.get("valoreCampoVE34Importo"));
        BigDecimal ve50 = _parseImporto(dati.get("valoreCampoVE50Importo"));

        if (ve50.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.valueOf(30);
        }

        BigDecimal sommaExport = ve30.add(ve34);
        BigDecimal percentuale = sommaExport
                .multiply(BigDecimal.valueOf(100))
                .divide(ve50, 4, RoundingMode.HALF_UP);

        if (percentuale.compareTo(BigDecimal.ZERO) < 0) {
            percentuale = BigDecimal.ZERO;
        }

        if (percentuale.compareTo(BigDecimal.valueOf(100)) > 0) {
            percentuale = BigDecimal.valueOf(100);
        }

        BigDecimal punti;

        if (percentuale.compareTo(BigDecimal.TEN) <= 0) {
            punti = BigDecimal.valueOf(30).add(
                    percentuale.divide(BigDecimal.TEN, 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(5))
            );
        }
        else {
            punti = BigDecimal.valueOf(35).subtract(
                    percentuale.subtract(BigDecimal.TEN)
                            .divide(BigDecimal.valueOf(90), 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(35))
            );
        }

        punti = punti.setScale(2, RoundingMode.HALF_UP);

        return punti.compareTo(BigDecimal.ZERO) < 0 ? BigDecimal.ZERO
                : punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_DIMENSIONE_INTERNAZIONALE)) > 0
                        ? BigDecimal.valueOf(MAX_PUNTI_DIMENSIONE_INTERNAZIONALE) : punti;
    }

    /**
     * Calcola il punteggio per Numero Dipendenti (max 25).
     *
     * Start up innovativa: 25 punti indipendentemente dal numero di dipendenti.
     *
     * Altrimenti interpolazione lineare a tratti:
     *   - 0 dipendenti  ->  0 punti
     *   - 10 dipendenti -> 25 punti (inizio plateau)
     *   - 25 dipendenti -> 25 punti (fine plateau)
     *   - >= 50 dipendenti ->  0 punti
     *
     * Segmento 0-10:  punti = (n / 10) * 25
     * Segmento 10-25: punti = 25
     * Segmento 25-50: punti = 25 - ((n - 25) / 25) * 25
     */
    private BigDecimal _calcolaPuntiNumeroDipendenti(Map<String, String> dati) {
        String startUp = dati.get("startUpInput");

        if (SI.equalsIgnoreCase(startUp)) {
            return BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI);
        }

        String numDipStr = dati.get("numeroDipendentiInput");
        int numDipendenti = _parseIntero(numDipStr);

        if (numDipendenti <= 0) {
            return BigDecimal.ZERO;
        }

        if (numDipendenti >= 50) {
            return BigDecimal.ZERO;
        }

        BigDecimal punti;

        if (numDipendenti <= 10) {
            punti = BigDecimal.valueOf(numDipendenti)
                    .divide(BigDecimal.TEN, 4, RoundingMode.HALF_UP)
                    .multiply(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI));
        }
        else if (numDipendenti <= 25) {
            punti = BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI);
        }
        else {
            punti = BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI).subtract(
                    BigDecimal.valueOf(numDipendenti - 25)
                            .divide(BigDecimal.valueOf(25), 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI))
            );
        }

        punti = punti.setScale(2, RoundingMode.HALF_UP);

        return punti.compareTo(BigDecimal.ZERO) < 0 ? BigDecimal.ZERO
                : punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI)) > 0
                        ? BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI) : punti;
    }

    /**
     * Calcola il punteggio per Articolazione Progetto (max 15).
     *
     * Basato sul numero di fiere internazionali all'estero:
     *   - 0 fiere internazionali (solo nazionali) ->  0 punti
     *   - 1 fiera internazionale all'estero       ->  5 punti
     *   - 2 fiere internazionali all'estero       -> 10 punti
     *   - 3 fiere internazionali all'estero       -> 15 punti (10 + 5 aggiuntivi)
     */
    private BigDecimal _calcolaPuntiArticolazioneProgetto(Map<String, String> dati) {
        String partecipazioneFiere = dati.get("articolazioneProgettoInput");

        if (!SI.equalsIgnoreCase(partecipazioneFiere)) {
            return BigDecimal.ZERO;
        }

        int numeroFiereInternazionali = _parseIntero(dati.get("numeroFiereInternazionali"));

        if (numeroFiereInternazionali <= 0) {
            return BigDecimal.ZERO;
        }

        BigDecimal punti;

        if (numeroFiereInternazionali == 1) {
            punti = BigDecimal.valueOf(5);
        }
        else if (numeroFiereInternazionali == 2) {
            punti = BigDecimal.valueOf(10);
        }
        else {
            punti = BigDecimal.valueOf(15);
        }

        return punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_ARTICOLAZIONE_PROGETTO)) > 0
                ? BigDecimal.valueOf(MAX_PUNTI_ARTICOLAZIONE_PROGETTO) : punti;
    }

    /**
     * Calcola il punteggio per Sito Web (max 10).
     * 2,5 punti per ogni lingua straniera, max 4 lingue rilevanti.
     * Oltre 4 lingue il punteggio resta 10.
     */
    private BigDecimal _calcolaPuntiSitoWeb(Map<String, String> dati) {
        String numLingueStr = dati.get("sitoWebNumLingueInput");
        int numLingue = _parseIntero(numLingueStr);

        if (numLingue <= 0) {
            return BigDecimal.ZERO;
        }

        int lingueRilevanti = Math.min(numLingue, 4);

        BigDecimal punti = BigDecimal.valueOf(lingueRilevanti)
                .multiply(new BigDecimal("2.5"));

        return punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_SITO_WEB)) > 0
                ? BigDecimal.valueOf(MAX_PUNTI_SITO_WEB) : punti;
    }

    /**
     * Calcola il punteggio per Impresa Femminile (max 5).
     * Certificazione parità di genere: SI = 5, NO = 0.
     */
    private BigDecimal _calcolaPuntiImpresaFemminile(Map<String, String> dati) {
        String certificazione = dati.get("impresaFemminileInput");

        if (SI.equalsIgnoreCase(certificazione)) {
            return BigDecimal.valueOf(MAX_PUNTI_IMPRESA_FEMMINILE);
        }

        return BigDecimal.ZERO;
    }

    /**
     * Calcola il punteggio per Impresa Giovanile (max 5).
     * SI = 5, NO = 0.
     */
    private BigDecimal _calcolaPuntiImpresaGiovanile(Map<String, String> dati) {
        String impresaGiovanile = dati.get("impresaGiovanileInput");

        if (SI.equalsIgnoreCase(impresaGiovanile)) {
            return BigDecimal.valueOf(MAX_PUNTI_IMPRESA_GIOVANILE);
        }

        return BigDecimal.ZERO;
    }

    /**
     * Calcola il punteggio per Impresa Sostenibile (max 5).
     * Certificazione sostenibilità: SI = 5, NO = 0.
     */
    private BigDecimal _calcolaPuntiImpresaSostenibile(Map<String, String> dati) {
        String certificazione = dati.get("impresaSostenibileInput");

        if (SI.equalsIgnoreCase(certificazione)) {
            return BigDecimal.valueOf(MAX_PUNTI_IMPRESA_SOSTENIBILE);
        }

        return BigDecimal.ZERO;
    }

    /**
     * Calcola il punteggio per Coerenza (max 5).
     * Coerenza fiere con attività imprenditoriale: SI = 5, NO = 0.
     */
    private BigDecimal _calcolaPuntiCoerenza(Map<String, String> dati) {
        String coerenza = dati.get("coerenzaInput");

        if (SI.equalsIgnoreCase(coerenza)) {
            return BigDecimal.valueOf(MAX_PUNTI_COERENZA);
        }

        return BigDecimal.ZERO;
    }

    /**
     * Formatta un punteggio BigDecimal come stringa.
     * Se il valore è intero restituisce senza decimali (es. "25"),
     * altrimenti con i decimali significativi (es. "2.5", "7.5").
     */
    private String _formattaPunteggio(BigDecimal punteggio) {
        if (punteggio.stripTrailingZeros().scale() <= 0) {
            return punteggio.setScale(0, RoundingMode.HALF_UP).toPlainString();
        }

        return punteggio.stripTrailingZeros().toPlainString();
    }

    /**
     * Converte una stringa importo (formato italiano 1.234,56) in BigDecimal.
     */
    private BigDecimal _parseImporto(String importo) {
        if (Validator.isNull(importo)) {
            return BigDecimal.ZERO;
        }

        String normalizzato = importo.trim()
                .replace("€", "")
                .replace(" ", "")
                .trim();

        if (Validator.isNull(normalizzato)) {
            return BigDecimal.ZERO;
        }

        if (normalizzato.contains(",")) {
            normalizzato = normalizzato.replace(".", "").replace(",", ".");
        }

        try {
            return new BigDecimal(normalizzato);
        }
        catch (NumberFormatException e) {
            log.warn("Importo non valido: " + importo);
            return BigDecimal.ZERO;
        }
    }

    /**
     * Converte una stringa in intero, ritorna 0 se non valida.
     */
    private int _parseIntero(String valore) {
        if (Validator.isNull(valore)) {
            return 0;
        }

        try {
            return Integer.parseInt(valore.trim());
        }
        catch (NumberFormatException e) {
            log.warn("Valore intero non valido: " + valore);
            return 0;
        }
    }

    public List<ErroreValidazioneDTO> validaImportoPostiLetto(String dataForm, String jsonPathCampo) {
        List<ErroreValidazioneDTO> errori = new ArrayList<>();

        if (Validator.isNull(dataForm) || Validator.isNull(jsonPathCampo)) {
            return errori;
        }

        JsonObject formJson = new JsonParser().parse(dataForm).getAsJsonObject();
        JsonObject alpacaData = formJson.getAsJsonObject("alpaca").getAsJsonObject("data");

        // Naviga al parent object usando il jsonPathCampo
        List<String> keys = _parseJsonPathKeys(jsonPathCampo);

        JsonObject parent = alpacaData;
        for (int i = 0; i < keys.size() - 1; i++) {
            if (parent == null || !parent.has(keys.get(i))) {
                return errori;
            }
            parent = parent.getAsJsonObject(keys.get(i));
        }

        String valoreNumericoStr = parent.has("valoreNumerico") && !parent.get("valoreNumerico").isJsonNull()
                ? parent.get("valoreNumerico").getAsString() : null;
        String importoStr = parent.has("importo") && !parent.get("importo").isJsonNull()
                ? parent.get("importo").getAsString() : null;

        if (Validator.isNull(valoreNumericoStr) || Validator.isNull(importoStr)) {
            return errori;
        }

        int postiLetto = _parseIntero(valoreNumericoStr);
        BigDecimal importo = ImportoUtils.parseImporto(importoStr);

        BigDecimal importoMinimo40 = new BigDecimal("250000");
        BigDecimal importoMassimo40 = new BigDecimal("1500000");
        BigDecimal importoMassimoOltre40 = new BigDecimal("3000000");
        int sogliaPostiLetto = 40;

        if (postiLetto == sogliaPostiLetto) {
            if (importo.compareTo(importoMinimo40) < 0) {
                ErroreValidazioneDTO errore = new ErroreValidazioneDTO();
                errore.setDescrizione("Per " + sogliaPostiLetto + " posti letto, l'importo minimo deve essere di \u20AC 250.000,00");
                errore.setObbligatorio(true);
                errori.add(errore);
            }

            if (importo.compareTo(importoMassimo40) > 0) {
                ErroreValidazioneDTO errore = new ErroreValidazioneDTO();
                errore.setDescrizione("Per " + sogliaPostiLetto + " posti letto, l'importo massimo non deve superare \u20AC 1.500.000,00");
                errore.setObbligatorio(true);
                errori.add(errore);
            }
        }
        else if (postiLetto > sogliaPostiLetto) {
            if (importo.compareTo(importoMinimo40) < 0) {
                ErroreValidazioneDTO errore = new ErroreValidazioneDTO();
                errore.setDescrizione("Per un numero di posti letto superiore a " + sogliaPostiLetto + ", l'importo minimo deve essere di \u20AC 250.000,00");
                errore.setObbligatorio(true);
                errori.add(errore);
            }

            if (importo.compareTo(importoMassimoOltre40) > 0) {
                ErroreValidazioneDTO errore = new ErroreValidazioneDTO();
                errore.setDescrizione("Per un numero di posti letto superiore a " + sogliaPostiLetto + ", l'importo massimo non deve superare \u20AC 3.000.000,00");
                errore.setObbligatorio(true);
                errori.add(errore);
            }
        }

        return errori;
    }

    /**
     * Estrae le chiavi dal jsonPath nel formato $.['key1']['key2']['key3']
     */
    private List<String> _parseJsonPathKeys(String jsonPath) {
        List<String> keys = new ArrayList<>();
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\['([^']+)'\\]");
        java.util.regex.Matcher matcher = pattern.matcher(jsonPath);

        while (matcher.find()) {
            keys.add(matcher.group(1));
        }

        return keys;
    }

    public JsonObject calcolaGiorniAttivita(String dataForm, String jsonPathCampo) {
        JsonObject result = new JsonObject();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");

        try {
            if (Validator.isNull(dataForm) || Validator.isNull(jsonPathCampo)) {
                return _buildErroreCalcoloGiorni(result, "Compilare entrambe le date", true);
            }

            JsonObject formJson = new JsonParser().parse(dataForm).getAsJsonObject();
            JsonObject alpacaData = formJson.getAsJsonObject("alpaca").getAsJsonObject("data");

            List<String> keys = _parseJsonPathKeys(jsonPathCampo);

            JsonObject parent = alpacaData;
            for (int i = 0; i < keys.size() - 1; i++) {
                if (parent == null || !parent.has(keys.get(i))) {
                    return _buildErroreCalcoloGiorni(result, "Compilare entrambe le date", true);
                }
                parent = parent.getAsJsonObject(keys.get(i));
            }

            String dataInizioStr = parent.has("dataInizio") && !parent.get("dataInizio").isJsonNull()
                    ? parent.get("dataInizio").getAsString() : null;
            String dataFineStr = parent.has("dataFine") && !parent.get("dataFine").isJsonNull()
                    ? parent.get("dataFine").getAsString() : null;

            if (Validator.isNull(dataInizioStr) || Validator.isNull(dataFineStr)) {
                return _buildErroreCalcoloGiorni(result, "Compilare entrambe le date", true);
            }

            LocalDate dataInizio = LocalDate.parse(dataInizioStr, formatter);
            LocalDate dataFine = LocalDate.parse(dataFineStr, formatter);

            if (dataFine.isBefore(dataInizio)) {
                return _buildErroreCalcoloGiorni(result, "La data fine attività deve essere successiva o uguale alla data inizio attività", true);
            }

            long giorni = ChronoUnit.DAYS.between(dataInizio, dataFine) + 1;

            result.addProperty("status", "OK");
            result.addProperty("risultato", giorni);
        }
        catch (DateTimeParseException e) {
            _log.error("Errore nel parsing delle date: " + e.getMessage(), e);
            _buildErroreCalcoloGiorni(result, "Formato data non valido, utilizzare dd/MM/yyyy", true);
        }
        catch (Exception e) {
            _log.error("Errore nel calcolo giorni attività: " + e.getMessage(), e);
            _buildErroreCalcoloGiorni(result, "Errore durante il calcolo dei giorni", true);
        }

        return result;
    }

    private JsonObject _buildErroreCalcoloGiorni(JsonObject result, String messaggio, boolean obbligatorio) {
        JsonObject errore = new JsonObject();
        errore.addProperty("messaggio", messaggio);
        errore.addProperty("obbligatorio", obbligatorio);
        JsonArray errori = new JsonArray();
        errori.add(errore);
        result.addProperty("status", "KO");
        result.add("errori", errori);
        return result;
    }

    public JsonObject calcolaPercentuale(String dataForm, String jsonPathIniziale, String jsonPathRiferimento) {
        JsonObject result = new JsonObject();

        try {
            if (Validator.isNull(dataForm) || Validator.isNull(jsonPathIniziale) || Validator.isNull(jsonPathRiferimento)) {
                result.addProperty("status", "KO");
                return result;
            }

            JsonObject formJson = new JsonParser().parse(dataForm).getAsJsonObject();

            String valoreInizialeStr = _risolviValoreDaJsonPath(formJson, jsonPathIniziale);
            String valoreRiferimentoStr = _risolviValoreDaJsonPath(formJson, jsonPathRiferimento);

            if (Validator.isNull(valoreInizialeStr) || Validator.isNull(valoreRiferimentoStr)) {
                result.addProperty("status", "KO");
                return result;
            }

            BigDecimal valoreIniziale = _parseImporto(valoreInizialeStr);
            BigDecimal valoreRiferimento = _parseImporto(valoreRiferimentoStr);
            BigDecimal risultato = BigDecimal.ZERO;
            if (valoreRiferimento.compareTo(BigDecimal.ZERO) == 0) {
                result.addProperty("status", "KO");
                result.addProperty("messaggio", "Il campo '${valoreRiferimento}' non può essere pari a zero");
                return result;
            }

            if (valoreRiferimento.compareTo(valoreIniziale) < 0) {
                result.addProperty("status", "KO");
                result.addProperty("messaggio", "Il campo '${valoreRiferimento}' deve essere maggiore o uguale al campo '${valoreIniziale}'");
                return result;
            }

            risultato = valoreRiferimento.subtract(valoreIniziale);

            BigDecimal percentuale = risultato.multiply(new BigDecimal(100)).divide(valoreRiferimento, 2, RoundingMode.HALF_UP);

            result.addProperty("status", "OK");
            result.addProperty("percentuale", percentuale.toPlainString());
            result.addProperty("importo", risultato.toPlainString());
        }
        catch (Exception e) {
            log.error("Errore nel calcolo percentuale: " + e.getMessage(), e);
            result.addProperty("status", "KO");
        }

        return result;
    }

    private String _risolviValoreDaJsonPath(JsonObject formData, String jsonPath) {
        List<String> keys = _parseJsonPathKeys(jsonPath);
        if (keys.isEmpty()) {
            return null;
        }

        JsonElement current = formData;
        for (String key : keys) {
            if (current == null || !current.isJsonObject() || !current.getAsJsonObject().has(key)) {
                return null;
            }
            current = current.getAsJsonObject().get(key);
        }

        if (current == null || current.isJsonNull() || !current.isJsonPrimitive()) {
            return null;
        }

        return current.getAsString();
    }
