        Layout layout = layoutLocalService.getLayoutByFriendlyURL(domandaBando.getGroupId(), false, ScrivaniaOperatoreBandiPortletKeys.MONITORAGGIO_BANDO_FRIENDLY_URL);

        paginaServizio = layout.getFriendlyURL(Locale.ROOT);

