    private void estraiECreaAziendeAssociate(JsonNode fieldValues, String nomeCampo, long domandaBandoId,
                                             long groupId, long userId, String userName) {
        if (fieldValues != null) {
            JsonNode soggettiAti = fieldValues.get(0);

            if (soggettiAti != null) {
                JsonNode campoGenerico = soggettiAti.get(nomeCampo);

                if (campoGenerico != null && campoGenerico.size() > 0) {

                    for (JsonNode elementoAzienda : campoGenerico) {

                        AziendaAssociata azienda = aziendaAssociataLocalService
                                .createAziendaAssociata(counterLocalService.increment());

                        String ragioneSociale = "";
                        String partitaIva = "";
                        String codiceFiscale = "";

                        if (elementoAzienda.has("nomePartner") && !elementoAzienda.get("nomePartner").isNull()) {
                            ragioneSociale = elementoAzienda.get("nomePartner").asText();

                            if (Validator.isNotNull(ragioneSociale)) {
                                azienda.setRagioneSociale(ragioneSociale);
                            }
                        }

                        if (elementoAzienda.has("partitaIva") && !elementoAzienda.get("partitaIva").isNull()) {
                            partitaIva = elementoAzienda.get("partitaIva").asText();

                            if (Validator.isNotNull(partitaIva)) {
                                azienda.setPartitaIva(partitaIva);
                            }
                        }

                        if (elementoAzienda.has("codiceFiscale")
                                && !elementoAzienda.get("codiceFiscale").isNull()) {
                            codiceFiscale = elementoAzienda.get("codiceFiscale").asText();

                            if (Validator.isNotNull(codiceFiscale)) {
                                azienda.setCodiceFiscale(codiceFiscale);
                            }
                        }

                        azienda.setDomandaBandoId(domandaBandoId);
                        azienda.setGroupId(groupId);
                        azienda.setUserId(userId);
                        azienda.setUserName(userName);
                        aziendaAssociataLocalService.updateAziendaAssociata(azienda);
                    }

                }
            }
        }
    }

    public void addAziendeRaggruppamento(IstanzaDomandaBando istanzaDomandaBando, String portalURL, long groupId,
                                         long userId, String userName, long bandoId) {
        String jsonForm = istanzaDomandaBando.getJson();

        if (Validator.isNotNull(jsonForm)) {
            Set<Option> jsonPathOptions = new HashSet<Option>();
            jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
            jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

            Configuration jsonPathConfiguration = Configuration.builder()
                    .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
                    .options(jsonPathOptions).build();

            JsonNode fieldValues = null;

            List<String> listaCampiAziendaRaggruppamento = getNomeCampoByType(jsonForm, portalURL, typesSoggettiATIATS,
                    istanzaDomandaBando.getFormId());

            if (listaCampiAziendaRaggruppamento != null && !listaCampiAziendaRaggruppamento.isEmpty()) {
                for (String campo : listaCampiAziendaRaggruppamento) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                estraiECreaAziendeAssociate(fieldValues, "partner", istanzaDomandaBando.getDomandaBandoId(),
                        groupId, userId, userName);

            }

            List<String> listaCampiMandanti = getNomeCampoByType(jsonForm, portalURL, typesCustomMandanti,
                    istanzaDomandaBando.getFormId());

            if (listaCampiMandanti != null && !listaCampiMandanti.isEmpty()) {
                for (String campo : listaCampiMandanti) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                estraiECreaAziendeAssociate(fieldValues, "mandanti", istanzaDomandaBando.getDomandaBandoId(),
                        groupId, userId, userName);

            }

            List<String> listaCampiPartnerAgricoltura = getNomeCampoByType(jsonForm, portalURL, typesPartnerAgricoltura,
                    istanzaDomandaBando.getFormId());

            if (listaCampiPartnerAgricoltura != null && !listaCampiPartnerAgricoltura.isEmpty()) {
                for (String campo : listaCampiPartnerAgricoltura) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                if (fieldValues != null) {
                    JsonNode root = fieldValues.get(0);
                    if (root != null) {
                        JsonNode partnerArray = root.get("partner");
                        if (partnerArray != null && partnerArray.size() > 0) {
                            for (JsonNode elemPartner : partnerArray) {
                                if (Validator.isNotNull(elemPartner) && Validator.isNotNull(elemPartner.get("datiPartner"))) {
                                    JsonNode datiPartner = elemPartner.get("datiPartner");

                                    AziendaAssociata azienda = aziendaAssociataLocalService
                                            .createAziendaAssociata(counterLocalService.increment());

                                    if (datiPartner.has("nomePartner") && !datiPartner.get("nomePartner").isNull()) {
                                        String ragioneSociale = datiPartner.get("nomePartner").asText();
                                        if (Validator.isNotNull(ragioneSociale)) {
                                            azienda.setRagioneSociale(ragioneSociale);
                                        }
                                    }

                                    if (datiPartner.has("codiceFiscale") && !datiPartner.get("codiceFiscale").isNull()) {
                                        String codiceFiscale = datiPartner.get("codiceFiscale").asText();
                                        if (Validator.isNotNull(codiceFiscale)) {
                                            azienda.setCodiceFiscale(codiceFiscale);
                                        }
                                    }

                                    azienda.setDomandaBandoId(istanzaDomandaBando.getDomandaBandoId());
                                    azienda.setGroupId(groupId);
                                    azienda.setUserId(userId);
                                    azienda.setUserName(userName);
                                    aziendaAssociataLocalService.updateAziendaAssociata(azienda);
                                }
                            }
                        }
                    }
                }
            }

            Form form = getFormBando(bandoId);
            List<FormField> listaField = new ArrayList<FormField>();

            if (Validator.isNotNull(form)) {
                for (String type : typesCustomSoggettiATIATS) {
                    JsonPathUtil.processPropertiesCustomFields(listaField, form.getJson(), "", "", type);

                    if (Validator.isNotNull(listaField) && !listaField.isEmpty()) {
                        JsonNode partner = null;
                        FormField campo = null;

                        if (Validator.isNotNull(listaField.get(0))
                                && Validator.isNotNull(listaField.get(0).getPath())) {
                            campo = listaField.get(0);
                            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
                            String arrayField = field.substring(field.indexOf("["), field.indexOf("]") + 1);

                            if (Validator.isNotNull(arrayField)) {
                                String jsonPathInterno = ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + arrayField;
                                partner = JsonPath.using(jsonPathConfiguration).parse(jsonForm).read(jsonPathInterno);

                                if (Validator.isNotNull(partner) && Validator.isNotNull(partner.get(0))) {

                                    JsonNode arrayPartner = partner.get(0);

                                    for (JsonNode elemPartner : arrayPartner) {

                                        AziendaAssociata azienda = aziendaAssociataLocalService
                                                .createAziendaAssociata(counterLocalService.increment());

                                        String ragioneSociale = "";
                                        String partitaIva = "";
                                        String codiceFiscale = "";

                                        if (Validator.isNotNull(elemPartner)) {

                                            if (Validator.isNotNull(elemPartner.get("datiPartner"))) {
                                                JsonNode datiPartner = elemPartner.get("datiPartner");

                                                if (Validator.isNotNull(datiPartner.get("partitaIva"))) {
                                                    partitaIva = datiPartner.get("partitaIva").asText();

                                                    if (Validator.isNotNull(partitaIva)) {
                                                        azienda.setPartitaIva(partitaIva);
                                                    }
                                                }

                                                if (Validator.isNotNull(datiPartner.get("nomePartner"))) {
                                                    ragioneSociale = datiPartner.get("nomePartner").asText();

                                                    if (Validator.isNotNull(ragioneSociale)) {
                                                        azienda.setRagioneSociale(ragioneSociale);
                                                    }
                                                }

                                                if (Validator.isNotNull(datiPartner.get("codiceFiscale"))
                                                        && Validator.isNull(datiPartner.get("partitaIva"))) {
                                                    codiceFiscale = datiPartner.get("codiceFiscale").asText();

                                                    if (Validator.isNotNull(codiceFiscale)) {
                                                        azienda.setPartitaIva(codiceFiscale);
                                                    }
                                                }

                                            }

                                            if (Validator.isNotNull(elemPartner.get("datiMandanti"))) {
                                                JsonNode datiPartner = elemPartner.get("datiMandanti");

                                                if (Validator.isNotNull(datiPartner.get("nomePartner"))) {
                                                    ragioneSociale = datiPartner.get("nomePartner").asText();

                                                    if (Validator.isNotNull(ragioneSociale)) {
                                                        azienda.setRagioneSociale(ragioneSociale);
                                                    }
                                                }

                                                if (Validator.isNotNull(datiPartner.get("codiceFiscale"))
                                                        && Validator.isNull(datiPartner.get("partitaIva"))) {
                                                    codiceFiscale = datiPartner.get("codiceFiscale").asText();

                                                    if (Validator.isNotNull(codiceFiscale)) {
                                                        azienda.setPartitaIva(codiceFiscale);
                                                    }
                                                }

                                            }

                                            azienda.setDomandaBandoId(istanzaDomandaBando.getDomandaBandoId());
                                            azienda.setGroupId(groupId);
                                            azienda.setUserId(userId);
                                            azienda.setUserName(userName);
                                            aziendaAssociataLocalService.updateAziendaAssociata(azienda);
                                        }
                                    }

                                }
                            }
                        }

                    }
                }
            }

        }
    }

    public List<IstanzaDomandaBando> getFormEsecuzione(List<IstanzaDomandaBando> formIntegrativi, long bandoId) {
        List<BandoForm> bandoForms = bandoFormLocalService.getListaBandoFormBando(bandoId);

        List<Long> listaBandoFormId = new ArrayList<>();

        for (BandoForm bando : bandoForms) {
            if (bando.getTipoForm().equals(TipoFormEnum.ESECUZIONE.name())
                    || bando.getTipoForm().equals(TipoFormEnum.ESECUZIONE_CRONOPROGRAMMA.name())) {
                listaBandoFormId.add(bando.getFormId());
            }
        }

        List<IstanzaDomandaBando> formsEsecuzione = new ArrayList<>();

        for (IstanzaDomandaBando istanzaDomandaBando : formIntegrativi) {
            if (listaBandoFormId.contains(istanzaDomandaBando.getFormId())) {
                formsEsecuzione.add(istanzaDomandaBando);
            }
        }

        return formsEsecuzione;
    }

    public void sendNotificaInvioIntegrazione(long domandaBandoId) throws NoSuchValutazioneException {
