                        log.warn("Response Anagrafica Unica non valida per tipo soggetto ::" + bandoTipologiaEnte.getCodiceTipologiaEnte()
                                + " codFiscPiva=" + codFiscPiva
                                + " status=" + (response != null ? response.getStatus() : "null")
                                + " data=" + (response != null && response.getData() != null ? "present" : "null"));
                    }
                } catch (Exception e) {
                    log.warn("Non é stato possibile recuperare i dati da anagrafica unica per tipo soggetto ::" + bandoTipologiaEnte.getCodiceTipologiaEnte() + " codFiscPiva=" + codFiscPiva, e);
                }
            }
            if (restResponse == null) {
                throw new AnagraficaUnicaException();
            }
        }
        datiSoggettoDto.setRestResponse(restResponse);
        datiSoggettoDto.setTipologie(tipologie);
        return datiSoggettoDto;
    }

    public DettaglioImpresa getDatiAnagraficaUnicaImpresa(String codFiscPiva, long bandoId, long groupId) throws Exception {
        Bando bando = bandoLocalService.getBando(bandoId);
        Contesto contesto = Contesto.valueOf(bando.getContesto());

        RestResponse restResponse = anagraficaUnicaStakeholderClient.getAnagrafica(
                groupId, contesto, "IMPRESA", codFiscPiva);

        if (Validator.isNotNull(restResponse) && Validator.isNotNull(restResponse.getData())
                && Validator.isNotNull(restResponse.getStatus()) && restResponse.getStatus().equalsIgnoreCase("200")) {
            Gson gson = new Gson();
            JsonObject data = gson.toJsonTree(restResponse.getData()).getAsJsonObject();
            DettaglioImpresa dettaglio = toDettaglioImpresaAnagraficaUnica(data);
            filtraCodiciAtecoDettaglioImpresa(dettaglio, bandoId);
            return dettaglio;
        }

        return null;
    }

    private void filtraCodiciAtecoDettaglioImpresa(DettaglioImpresa dettaglio, long bandoId) {
        if (!Validator.isNotNull(dettaglio)) {
            return;
        }

        List<CodiceAteco> listaCodiciBando = getListaCodiciAteco(bandoId);
        List<CodiceAteco> listaCodiciIstante = new ArrayList<>();
        RegistroImpresaService registroImpresaService = registroImpresaServiceFactory.getService();
        List<String> listaCodiciRilevanza = getListaRilevanzaCodiciAteco(bandoId, registroImpresaService);
        List<CodiceAteco> listaCodiciRegistro = dettaglio.getCodiciAteco();

        if (listaCodiciBando != null && !listaCodiciBando.isEmpty() && listaCodiciRilevanza != null
                && !listaCodiciRilevanza.isEmpty()) {
            if (listaCodiciRegistro != null && !listaCodiciRegistro.isEmpty()) {
                for (CodiceAteco codiceRegistroImpresa : listaCodiciRegistro) {
                    if (Validator.isNotNull(codiceRegistroImpresa)) {
                        Optional<CodiceAteco> codiceTrovato = listaCodiciBando.stream()
                                .filter(x -> x.getCodice().equalsIgnoreCase(codiceRegistroImpresa.getCodice()))
                                .findFirst();

                        if (codiceTrovato.isPresent()
                                && listaCodiciRilevanza.contains(codiceRegistroImpresa.getRilevanza())) {
                            CodiceAteco codicePresent = codiceTrovato.get();
                            CodiceAtecoRilevanzaEnum codiceEnum = CodiceAtecoRilevanzaEnum
                                    .findByCodice(codiceRegistroImpresa.getRilevanza());

                            if (codiceEnum != null) {
                                CodiceAteco codiceAtecoPresent = new CodiceAteco();
                                codiceAtecoPresent.setCodice(codicePresent.getCodice());
                                codiceAtecoPresent.setRilevanza(codiceEnum.getDescription());
                                listaCodiciIstante.add(codiceAtecoPresent);
                            }
                        }
                    }
                }

                dettaglio.setCodiciAteco(listaCodiciIstante);
            }
        } else {
            if (listaCodiciRegistro != null && !listaCodiciRegistro.isEmpty()) {
                for (CodiceAteco codice : listaCodiciRegistro) {
                    if (Validator.isNotNull(codice)) {
                        CodiceAtecoRilevanzaEnum codiceEnum = CodiceAtecoRilevanzaEnum
                                .findByCodice(codice.getRilevanza());

                        if (codiceEnum != null) {
                            codice.setRilevanza(codiceEnum.getDescription());
                        }
                    }
                }
            }
        }
    }

    private DettaglioImpresa toDettaglioImpresaAnagraficaUnica(JsonObject data) {
        DettaglioImpresa dettaglioImpresa = new DettaglioImpresa();

        if (data.has("dati-identificativi") && !data.get("dati-identificativi").isJsonNull()) {
            JsonObject datiIdentificativi = data.get("dati-identificativi").getAsJsonObject();

            if (datiIdentificativi.has("denominazione") && !datiIdentificativi.get("denominazione").isJsonNull()) {
                dettaglioImpresa.setDenominazione(datiIdentificativi.get("denominazione").getAsString());
            }

            if (datiIdentificativi.has("c-fiscale") && !datiIdentificativi.get("c-fiscale").isJsonNull()) {
                dettaglioImpresa.setCodiceFiscale(datiIdentificativi.get("c-fiscale").getAsString());
            }

            if (datiIdentificativi.has("partita-iva") && !datiIdentificativi.get("partita-iva").isJsonNull()) {
                dettaglioImpresa.setPartitaIva(datiIdentificativi.get("partita-iva").getAsString());
            }

            if (datiIdentificativi.has("indirizzo-posta-certificata") && !datiIdentificativi.get("indirizzo-posta-certificata").isJsonNull()) {
                dettaglioImpresa.setPec(datiIdentificativi.get("indirizzo-posta-certificata").getAsString());
            }

            if (datiIdentificativi.has("cciaa") && !datiIdentificativi.get("cciaa").isJsonNull()) {
                dettaglioImpresa.setCciaa(datiIdentificativi.get("cciaa").getAsString());
            }

            if (datiIdentificativi.has("forma-giuridica") && !datiIdentificativi.get("forma-giuridica").isJsonNull()) {
                JsonObject formaGiuridicaObj = datiIdentificativi.get("forma-giuridica").getAsJsonObject();

                if (formaGiuridicaObj.has("value") && !formaGiuridicaObj.get("value").isJsonNull()) {
                    dettaglioImpresa.setFormaGiuridica(formaGiuridicaObj.get("value").getAsString());
                }

                if (formaGiuridicaObj.has("C") && !formaGiuridicaObj.get("C").isJsonNull()) {
                    dettaglioImpresa.setCodiceFormaGiuridica(formaGiuridicaObj.get("C").getAsString());
                }
            }

            if (datiIdentificativi.has("n-rea") && !datiIdentificativi.get("n-rea").isJsonNull()) {
                dettaglioImpresa.setNumeroRea(datiIdentificativi.get("n-rea").getAsString());
            }

            if (datiIdentificativi.has("indirizzo-localizzazione") && !datiIdentificativi.get("indirizzo-localizzazione").isJsonNull()) {
                JsonObject indirizzo = datiIdentificativi.get("indirizzo-localizzazione").getAsJsonObject();

                String toponimo = "";
                String via = "";

                if (indirizzo.has("toponimo") && !indirizzo.get("toponimo").isJsonNull()) {
                    toponimo = indirizzo.get("toponimo").getAsString();
                }

                if (indirizzo.has("via") && !indirizzo.get("via").isJsonNull()) {
                    via = indirizzo.get("via").getAsString();
                }

                if (!toponimo.isEmpty()) {
                    dettaglioImpresa.setVia(toponimo + " " + via);
                } else {
                    dettaglioImpresa.setVia(via);
                }

                if (indirizzo.has("n-civico") && !indirizzo.get("n-civico").isJsonNull()) {
                    dettaglioImpresa.setCivico(indirizzo.get("n-civico").getAsString());
                }

                if (indirizzo.has("cap") && !indirizzo.get("cap").isJsonNull()) {
                    dettaglioImpresa.setCap(indirizzo.get("cap").getAsString());
                }

                if (indirizzo.has("comune") && !indirizzo.get("comune").isJsonNull()) {
                    dettaglioImpresa.setComune(indirizzo.get("comune").getAsString());
                }

                if (indirizzo.has("provincia") && !indirizzo.get("provincia").isJsonNull()) {
                    dettaglioImpresa.setProvincia(indirizzo.get("provincia").getAsString());
                }

                if (indirizzo.has("c-comune") && !indirizzo.get("c-comune").isJsonNull()) {
                    dettaglioImpresa.setCodiceComune(indirizzo.get("c-comune").getAsString());
                }
            }

            applicaNormalizzazioneLocalitaAU(dettaglioImpresa);
        }

        List<CodiceAteco> listaCodiciAteco = new ArrayList<>();

        if (data.has("info-attivita") && !data.get("info-attivita").isJsonNull()) {
            JsonObject infoAttivita = data.get("info-attivita").getAsJsonObject();

            if (infoAttivita.has("classificazioni-ateco") && !infoAttivita.get("classificazioni-ateco").isJsonNull()) {
                JsonObject classificazioniAteco = infoAttivita.get("classificazioni-ateco").getAsJsonObject();

                if (classificazioniAteco.has("classificazione-ateco") && !classificazioniAteco.get("classificazione-ateco").isJsonNull()) {
                    JsonArray classificazioniArray = classificazioniAteco.get("classificazione-ateco").getAsJsonArray();

                    for (JsonElement element : classificazioniArray) {
                        if (element != null && !element.isJsonNull()) {
                            JsonObject elementObject = element.getAsJsonObject();

                            String codice = null;
                            String importanza = null;

                            if (elementObject.has("c-attivita") && !elementObject.get("c-attivita").isJsonNull()) {
                                codice = elementObject.get("c-attivita").getAsString();
                            }

                            if (elementObject.has("c-importanza") && !elementObject.get("c-importanza").isJsonNull()) {
                                importanza = elementObject.get("c-importanza").getAsString();
                            }

                            if (Validator.isNotNull(codice) && Validator.isNotNull(importanza)) {
                                CodiceAteco codiceDto = new CodiceAteco();
                                codiceDto.setCodice(codice);
                                codiceDto.setRilevanza(importanza);

                                if (!listaCodiciAteco.contains(codiceDto)) {
                                    listaCodiciAteco.add(codiceDto);
                                }
                            }
                        }
                    }
                }
            }
        }

        // Fallback: se info-attivita non ha fornito codici ATECO, cerca il primo "principale" nelle localizzazioni
        if (listaCodiciAteco.isEmpty() && data.has("localizzazioni") && !data.get("localizzazioni").isJsonNull()) {
            JsonElement localizzazioniElement = data.get("localizzazioni");
            JsonArray localizzazioniArray = null;
            if (localizzazioniElement.isJsonArray()) {
                localizzazioniArray = localizzazioniElement.getAsJsonArray();
            } else if (localizzazioniElement.isJsonObject()) {
                JsonObject wrapper = localizzazioniElement.getAsJsonObject();
                if (wrapper.has("localizzazione") && !wrapper.get("localizzazione").isJsonNull()) {
                    localizzazioniArray = wrapper.get("localizzazione").getAsJsonArray();
                }
            }

            if (localizzazioniArray != null) {
                Set<String> codiciImportanzaPrincipali = new HashSet<>();
                try {
                    RegistroImpresaConfiguration registroImpresaConfiguration = configurationProvider
                            .getSystemConfiguration(RegistroImpresaConfiguration.class);
                    String csv = registroImpresaConfiguration.codiciImportanzaAtecoPrincipali();
                    if (Validator.isNotNull(csv)) {
                        for (String s : csv.split(",")) {
                            String trimmed = s.trim().toUpperCase();
                            if (!trimmed.isEmpty()) {
                                codiciImportanzaPrincipali.add(trimmed);
                            }
                        }
                    }
                } catch (Exception e) {
                    _log.warn("Lettura RegistroImpresaConfiguration.codiciImportanzaAtecoPrincipali fallita, fallback ATECO disabilitato: " + e.getMessage());
                }

                if (!codiciImportanzaPrincipali.isEmpty()) {
                    boolean trovato = false;
                    for (int i = 0; i < localizzazioniArray.size() && !trovato; i++) {
                        JsonElement locEl = localizzazioniArray.get(i);
                        if (locEl == null || !locEl.isJsonObject()) {
                            continue;
                        }
                        JsonObject loc = locEl.getAsJsonObject();
                        if (!loc.has("classificazione-ateco") || loc.get("classificazione-ateco").isJsonNull()) {
                            continue;
                        }
                        JsonObject classObj = loc.get("classificazione-ateco").getAsJsonObject();
                        if (!classObj.has("classificazione-ateco")
                                || classObj.get("classificazione-ateco").isJsonNull()) {
                            continue;
                        }
                        JsonArray atecoArr = classObj.get("classificazione-ateco").getAsJsonArray();
                        for (JsonElement el : atecoArr) {
                            if (el == null || el.isJsonNull()) {
                                continue;
                            }
                            JsonObject elObj = el.getAsJsonObject();
                            String codice = elObj.has("c-attivita") && !elObj.get("c-attivita").isJsonNull()
                                    ? elObj.get("c-attivita").getAsString() : null;
                            String importanza = elObj.has("c-importanza") && !elObj.get("c-importanza").isJsonNull()
                                    ? elObj.get("c-importanza").getAsString() : null;
                            if (Validator.isNotNull(codice) && Validator.isNotNull(importanza)
                                    && codiciImportanzaPrincipali.contains(importanza.toUpperCase())) {
                                CodiceAteco codiceDto = new CodiceAteco();
                                codiceDto.setCodice(codice);
                                codiceDto.setRilevanza(importanza);
                                listaCodiciAteco.add(codiceDto);
                                trovato = true;
                                break;
                            }
                        }
                    }
                }
            }
        }

        dettaglioImpresa.setCodiciAteco(listaCodiciAteco);

        if (data.has("persone-sede") && !data.get("persone-sede").isJsonNull()) {
            JsonObject personaSede = data.get("persone-sede").getAsJsonObject();

            if (personaSede.has("persona") && !personaSede.get("persona").isJsonNull()) {
                JsonArray personaArray = personaSede.get("persona").getAsJsonArray();

                for (int i = 0; i < personaArray.size(); i++) {
                    JsonObject personaObj = personaArray.get(i).getAsJsonObject();

                    if (personaObj.has("persona-fisica") && !personaObj.get("persona-fisica").isJsonNull()) {
                        JsonObject personaFisica = personaObj.get("persona-fisica").getAsJsonObject();

                        if (personaFisica.has("c-fiscale") && !personaFisica.get("c-fiscale").isJsonNull()) {
                            dettaglioImpresa.getListaCfTitolari().add(personaFisica.get("c-fiscale").getAsString());
                        }
                    }
                }
            }
        }

        if (data.has("elenco-soci") && !data.get("elenco-soci").isJsonNull()) {
            JsonObject elencoSoci = data.get("elenco-soci").getAsJsonObject();

            if (elencoSoci.has("riquadri") && !elencoSoci.get("riquadri").isJsonNull()) {
                JsonObject riquadri = elencoSoci.get("riquadri").getAsJsonObject();

                if (riquadri.has("riquadro") && !riquadri.get("riquadro").isJsonNull()) {
                    JsonArray riquadroArray = riquadri.get("riquadro").getAsJsonArray();

                    for (int i = 0; i < riquadroArray.size(); i++) {
                        JsonObject riquadroObj = riquadroArray.get(i).getAsJsonObject();

                        if (riquadroObj.has("titolari") && !riquadroObj.get("titolari").isJsonNull()) {
                            JsonObject titolari = riquadroObj.get("titolari").getAsJsonObject();

                            if (titolari.has("titolare") && !titolari.get("titolare").isJsonNull()) {
                                JsonArray titolareArray = titolari.get("titolare").getAsJsonArray();

                                for (int j = 0; j < titolareArray.size(); j++) {
                                    JsonObject titolareObj = titolareArray.get(j).getAsJsonObject();

                                    if (titolareObj.has("anagrafica-titolare") && !titolareObj.get("anagrafica-titolare").isJsonNull()) {
                                        JsonObject anagraficaTitolare = titolareObj.get("anagrafica-titolare").getAsJsonObject();

                                        if (anagraficaTitolare.has("c-fiscale") && !anagraficaTitolare.get("c-fiscale").isJsonNull()) {
                                            dettaglioImpresa.getListaCfTitolari().add(anagraficaTitolare.get("c-fiscale").getAsString());
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        return dettaglioImpresa;
    }

    /**
     * Applica la normalizzazione di provincia/comune sul DettaglioImpresa appena
     * popolato dalla risposta di Anagrafica Unica, per correggere il
     * disallineamento della provincia BAT (e simili). In caso di match positivo
     * sovrascrive sigla provincia e codiceComune con i valori locali corretti;
     * in caso di nessun match lascia invariati i dati originali.
     */
    private void applicaNormalizzazioneLocalitaAU(DettaglioImpresa dettaglioImpresa) {
        try {
            NormalizedLocalita nl = comuneLocalService.normalizzaLocalita(
                    dettaglioImpresa.getProvincia(), dettaglioImpresa.getComune(), dettaglioImpresa.getCodiceComune());
            if (nl != null && nl.isCorretto()) {
                log.info("Normalizzazione localita' AU applicata: provincia " + dettaglioImpresa.getProvincia() + " -> " + nl.getSiglaProvincia()
                        + " per comune " + dettaglioImpresa.getComune() + " c-comune=" + dettaglioImpresa.getCodiceComune());
                dettaglioImpresa.setProvincia(nl.getSiglaProvincia());
            }
        }
        catch (Exception e) {
            log.warn("Errore durante la normalizzazione localita' AU, dati originali preservati", e);
        }
    }

    /**
     * Applica la normalizzazione di provincia/comune sul payload JSON raw (response.data)
     * di Anagrafica Unica per i tipi soggetto non-impresa (ente, comune, ente ecclesiastico, ecc.).
     * Legge provincia/comune dal JSON (dati-identificativi.indirizzo-localizzazione), invoca
     * il normalizer e, in caso di correzione, riscrive sigla provincia e c-comune nel JSON
     * prima che il consumer lo utilizzi.
     */
    private void applicaNormalizzazioneLocalitaAUResponse(RestResponse response) {
        if (response == null || response.getData() == null) {
            return;
        }
        try {
            Gson gson = new Gson();
            JsonObject data = gson.toJsonTree(response.getData()).getAsJsonObject();

            if (!data.has("dati-identificativi") || data.get("dati-identificativi").isJsonNull()) {
                return;
            }
            JsonObject datiIdentificativi = data.get("dati-identificativi").getAsJsonObject();
            if (!datiIdentificativi.has("indirizzo-localizzazione") || datiIdentificativi.get("indirizzo-localizzazione").isJsonNull()) {
                return;
            }
            JsonObject indirizzo = datiIdentificativi.get("indirizzo-localizzazione").getAsJsonObject();

            String provincia = indirizzo.has("provincia") && !indirizzo.get("provincia").isJsonNull() ? indirizzo.get("provincia").getAsString() : null;
            String comune = indirizzo.has("comune") && !indirizzo.get("comune").isJsonNull() ? indirizzo.get("comune").getAsString() : null;
            String cComune = indirizzo.has("c-comune") && !indirizzo.get("c-comune").isJsonNull() ? indirizzo.get("c-comune").getAsString() : null;

            if (provincia == null || comune == null || cComune == null) {
                return;
            }

            NormalizedLocalita nl = comuneLocalService.normalizzaLocalita(provincia, comune, cComune);
            if (nl != null && nl.isCorretto()) {
                log.info("Normalizzazione localita' AU (response) applicata: provincia " + provincia + " -> " + nl.getSiglaProvincia() + " per comune " + comune + " c-comune=" + cComune);
                indirizzo.addProperty("provincia", nl.getSiglaProvincia());
                response.setData(data);
            }
        }
        catch (Exception e) {
            log.warn("Errore durante la normalizzazione localita' AU (response), dati originali preservati", e);
        }
    }

    public InfoRegistroImpresa getInfoRegistroImpresaAnagraficaUnica(String codiceFiscale, long bandoId, long groupId) {
        InfoRegistroImpresa info = null;

        try {
            DettaglioImpresa dettaglio = getDatiAnagraficaUnicaImpresa(codiceFiscale, bandoId, groupId);

            if (Validator.isNotNull(dettaglio)) {
                info = new InfoRegistroImpresa();
                info.setpIva(dettaglio.getPartitaIva());
                info.setCfAzienda(dettaglio.getCodiceFiscale());
                info.setDenominazioneSoggettoOrganizzatore(dettaglio.getDenominazione());
                info.setNaturaGiuridica(dettaglio.getFormaGiuridica());
                info.setProvincia(dettaglio.getProvincia());
                info.setComune(dettaglio.getComune());
                info.setCap(dettaglio.getCap());
                info.setViaSedeLegale(dettaglio.getVia());
                info.setCivicoSedeLegale(dettaglio.getCivico());
                info.setPec(dettaglio.getPec());
                info.setNumeroRea(dettaglio.getNumeroRea());

                List<CodiceAteco> codiciAtecoList = dettaglio.getCodiciAteco();
                if (codiciAtecoList != null && !codiciAtecoList.isEmpty()) {
                    CodiceAteco primoAteco = codiciAtecoList.get(0);
                    if (primoAteco != null) {
                        info.setCodiciAteco(primoAteco.getCodice());
                        info.setRilevanza(primoAteco.getRilevanza());
                    }
                }
            }
        } catch (Exception e) {
            log.error(e.getMessage());
        }

        return info;
    }

    public List<DefinizioneStepAlpaca> retrieveAlpacaSteps(String dataForm) {
        List<DefinizioneStepAlpaca> stepFormAlpaca = new ArrayList<DefinizioneStepAlpaca>();

        Gson gson = new Gson();
        AlpacaJsonStructure alpacaStructure = gson.fromJson(dataForm, AlpacaJsonStructure.class);
        String view = gson.toJson(alpacaStructure.getView());
        JsonObject jsonView = gson.fromJson(view, JsonObject.class);
        if (Validator.isNotNull(jsonView) && jsonView.has("wizard")) {
            JsonObject wizard = jsonView.getAsJsonObject("wizard");
            if (Validator.isNotNull(wizard) && wizard.has("steps")) {
                JsonArray steps = wizard.get(AlpacaKey.STEPS.getName()).getAsJsonArray();
                if (Validator.isNotNull(steps) && !steps.isJsonNull() && steps.size() > 0) {
                    for (JsonElement step: steps) {
                        JsonObject stepObject = step.getAsJsonObject();
                        if (Validator.isNotNull(stepObject) && stepObject.has("description") && stepObject.has("title")) {
                            stepFormAlpaca.add(new DefinizioneStepAlpaca(stepObject.get("description").getAsString(), stepObject.get("title").getAsString()));
                        }
                    }
                }
            }
        }

        return stepFormAlpaca;
    }

    public void salvaImprontaIstanza(long domandaBandoId, long istanzaDomandaBandoId, byte[] pdf, long groupId, long companyId, long userId, String userName) {

        if (pdf == null) {
            return;
        }

        try {
            String hash = calcolaHashSHA256(pdf);
            String chiaveIstanza = String.valueOf(istanzaDomandaBandoId);

            List<DomandaBandoDatoAggiuntivo> existing = domandaBandoDatoAggiuntivoLocalService
                    .getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                            Collections.singletonList(domandaBandoId),
                            Collections.singletonList(DatoAggiuntivoChiave.IMPRONTA_ISTANZA.name()));

            DomandaBandoDatoAggiuntivo dato;
            JsonObject jsonImpronte;

            if (existing != null && !existing.isEmpty()) {
                dato = existing.get(0);
                String valoreAttuale = dato.getValore();
                if (Validator.isNotNull(valoreAttuale)) {
                    jsonImpronte = new JsonParser().parse(valoreAttuale).getAsJsonObject();
                } else {
                    jsonImpronte = new JsonObject();
                }
            } else {
                dato = domandaBandoDatoAggiuntivoLocalService
                        .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                dato.setDomandaBandoId(domandaBandoId);
                dato.setChiave(DatoAggiuntivoChiave.IMPRONTA_ISTANZA.name());
                dato.setGroupId(groupId);
                dato.setCompanyId(companyId);
                dato.setUserId(userId);
                dato.setUserName(userName);
                jsonImpronte = new JsonObject();
            }

            jsonImpronte.addProperty(chiaveIstanza, hash);
            dato.setValore(jsonImpronte.toString());
            domandaBandoDatoAggiuntivoLocalService.updateDomandaBandoDatoAggiuntivo(dato);

        } catch (Exception e) {
            log.error("Errore durante il salvataggio dell'impronta istanza per domandaBandoId " + domandaBandoId + " :: " + e.getMessage(), e);
        }
    }

    public String verificaImprontaIstanza(long domandaBandoId, long istanzaDomandaBandoId, byte[] allegatoBytes) {

        if (allegatoBytes == null) {
            return null;
        }

        try {
            List<DomandaBandoDatoAggiuntivo> existing = domandaBandoDatoAggiuntivoLocalService
                    .getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                            Collections.singletonList(domandaBandoId),
                            Collections.singletonList(DatoAggiuntivoChiave.IMPRONTA_ISTANZA.name()));

            if (existing == null || existing.isEmpty()) {
                return "errore-download-documento-richiesto";
            }

            String valoreAttuale = existing.get(0).getValore();

            if (Validator.isNull(valoreAttuale)) {
                return "errore-download-documento-richiesto";
            }

            JsonObject jsonImpronte = new JsonParser().parse(valoreAttuale).getAsJsonObject();
            String chiaveIstanza = String.valueOf(istanzaDomandaBandoId);

            if (!jsonImpronte.has(chiaveIstanza)) {
                return "errore-download-documento-richiesto";
            }

            String hashIstanzaGenerata = jsonImpronte.get(chiaveIstanza).getAsString();

            if (Validator.isNull(hashIstanzaGenerata)) {
                return null;
            }

            String hashFileCaricato = calcolaHashSHA256(allegatoBytes);

            if (hashIstanzaGenerata.equals(hashFileCaricato)) {
                return "errore-file-identico-a-generato";
            }

        } catch (Exception e) {
            log.error("Errore durante la verifica dell'impronta istanza per domandaBandoId " + domandaBandoId + " :: " + e.getMessage(), e);
        }

        return null;
    }

    private String calcolaHashSHA256(byte[] data) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(data);
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    // --- Calcolo punteggio autovalutazione ---

    public Map<String, String> calcolaPunteggioAutovalutazione(Map<String, String> dati) {
        BigDecimal puntiDimensioneInternazionale = _calcolaPuntiDimensioneInternazionale(dati);
        BigDecimal puntiNumeroDipendenti = _calcolaPuntiNumeroDipendenti(dati);
        BigDecimal puntiArticolazioneProgetto = _calcolaPuntiArticolazioneProgetto(dati);
        BigDecimal puntiSitoWeb = _calcolaPuntiSitoWeb(dati);
        BigDecimal puntiImpresaFemminile = _calcolaPuntiImpresaFemminile(dati);
        BigDecimal puntiImpresaGiovanile = _calcolaPuntiImpresaGiovanile(dati);
        BigDecimal puntiImpresaSostenibile = _calcolaPuntiImpresaSostenibile(dati);
        BigDecimal puntiCoerenza = _calcolaPuntiCoerenza(dati);

        BigDecimal totale = puntiDimensioneInternazionale.add(puntiNumeroDipendenti)
                .add(puntiArticolazioneProgetto).add(puntiSitoWeb)
                .add(puntiImpresaFemminile).add(puntiImpresaGiovanile)
                .add(puntiImpresaSostenibile).add(puntiCoerenza);

        Map<String, String> punteggi = new HashMap<>();
        punteggi.put("dimensioneInternazionale", _formattaPunteggio(puntiDimensioneInternazionale));
        punteggi.put("numeroDipendenti", _formattaPunteggio(puntiNumeroDipendenti));
        punteggi.put("articolazioneProgetto", _formattaPunteggio(puntiArticolazioneProgetto));
        punteggi.put("sitoWeb", _formattaPunteggio(puntiSitoWeb));
        punteggi.put("impresaFemminile", _formattaPunteggio(puntiImpresaFemminile));
        punteggi.put("impresaGiovanile", _formattaPunteggio(puntiImpresaGiovanile));
        punteggi.put("impresaSostenibile", _formattaPunteggio(puntiImpresaSostenibile));
        punteggi.put("coerenza", _formattaPunteggio(puntiCoerenza));
        punteggi.put("totale", _formattaPunteggio(totale));

        return punteggi;
    }

    /**
     * Calcola il punteggio per Dimensione Internazionalizzazione (max 35).
     *
     * Rapporto percentuale = (VE30 + VE34) / VE50 * 100
     *
     * Interpolazione lineare a tratti:
     *   - percentuale 0%   -> 30 punti
     *   - percentuale 10%  -> 35 punti (massimo)
     *   - percentuale 100% ->  0 punti
     *
     * Segmento 0%-10%:   punti = 30 + (percentuale / 10) * 5
     * Segmento 10%-100%: punti = 35 - ((percentuale - 10) / 90) * 35
     */
    private BigDecimal _calcolaPuntiDimensioneInternazionale(Map<String, String> dati) {
        BigDecimal ve30 = _parseImporto(dati.get("valoreCampoVE30Importo"));
        BigDecimal ve34 = _parseImporto(dati.get("valoreCampoVE34Importo"));
        BigDecimal ve50 = _parseImporto(dati.get("valoreCampoVE50Importo"));

        if (ve50.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.valueOf(30);
        }

        BigDecimal sommaExport = ve30.add(ve34);
        BigDecimal percentuale = sommaExport
                .multiply(BigDecimal.valueOf(100))
                .divide(ve50, 4, RoundingMode.HALF_UP);

        if (percentuale.compareTo(BigDecimal.ZERO) < 0) {
            percentuale = BigDecimal.ZERO;
        }

        if (percentuale.compareTo(BigDecimal.valueOf(100)) > 0) {
            percentuale = BigDecimal.valueOf(100);
        }

        BigDecimal punti;

        if (percentuale.compareTo(BigDecimal.TEN) <= 0) {
            punti = BigDecimal.valueOf(30).add(
                    percentuale.divide(BigDecimal.TEN, 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(5))
            );
        }
        else {
            punti = BigDecimal.valueOf(35).subtract(
                    percentuale.subtract(BigDecimal.TEN)
                            .divide(BigDecimal.valueOf(90), 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(35))
            );
        }

        punti = punti.setScale(2, RoundingMode.HALF_UP);

        return punti.compareTo(BigDecimal.ZERO) < 0 ? BigDecimal.ZERO
                : punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_DIMENSIONE_INTERNAZIONALE)) > 0
                        ? BigDecimal.valueOf(MAX_PUNTI_DIMENSIONE_INTERNAZIONALE) : punti;
    }

    /**
     * Calcola il punteggio per Numero Dipendenti (max 25).
     *
     * Start up innovativa: 25 punti indipendentemente dal numero di dipendenti.
     *
     * Altrimenti interpolazione lineare a tratti:
     *   - 0 dipendenti  ->  0 punti
     *   - 10 dipendenti -> 25 punti (inizio plateau)
     *   - 25 dipendenti -> 25 punti (fine plateau)
     *   - >= 50 dipendenti ->  0 punti
     *
     * Segmento 0-10:  punti = (n / 10) * 25
     * Segmento 10-25: punti = 25
     * Segmento 25-50: punti = 25 - ((n - 25) / 25) * 25
     */
    private BigDecimal _calcolaPuntiNumeroDipendenti(Map<String, String> dati) {
        String startUp = dati.get("startUpInput");

        if (SI.equalsIgnoreCase(startUp)) {
            return BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI);
        }

        String numDipStr = dati.get("numeroDipendentiInput");
        int numDipendenti = _parseIntero(numDipStr);

        if (numDipendenti <= 0) {
            return BigDecimal.ZERO;
        }

        if (numDipendenti >= 50) {
            return BigDecimal.ZERO;
        }

        BigDecimal punti;

        if (numDipendenti <= 10) {
            punti = BigDecimal.valueOf(numDipendenti)
                    .divide(BigDecimal.TEN, 4, RoundingMode.HALF_UP)
                    .multiply(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI));
        }
        else if (numDipendenti <= 25) {
            punti = BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI);
        }
        else {
            punti = BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI).subtract(
                    BigDecimal.valueOf(numDipendenti - 25)
                            .divide(BigDecimal.valueOf(25), 4, RoundingMode.HALF_UP)
                            .multiply(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI))
            );
        }

        punti = punti.setScale(2, RoundingMode.HALF_UP);

        return punti.compareTo(BigDecimal.ZERO) < 0 ? BigDecimal.ZERO
                : punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI)) > 0
                        ? BigDecimal.valueOf(MAX_PUNTI_NUMERO_DIPENDENTI) : punti;
    }

    /**
     * Calcola il punteggio per Articolazione Progetto (max 15).
     *
     * Basato sul numero di fiere internazionali all'estero:
     *   - 0 fiere internazionali (solo nazionali) ->  0 punti
     *   - 1 fiera internazionale all'estero       ->  5 punti
     *   - 2 fiere internazionali all'estero       -> 10 punti
     *   - 3 fiere internazionali all'estero       -> 15 punti (10 + 5 aggiuntivi)
     */
    private BigDecimal _calcolaPuntiArticolazioneProgetto(Map<String, String> dati) {
        String partecipazioneFiere = dati.get("articolazioneProgettoInput");

        if (!SI.equalsIgnoreCase(partecipazioneFiere)) {
            return BigDecimal.ZERO;
        }

        int numeroFiereInternazionali = _parseIntero(dati.get("numeroFiereInternazionali"));

        if (numeroFiereInternazionali <= 0) {
            return BigDecimal.ZERO;
        }

        BigDecimal punti;

        if (numeroFiereInternazionali == 1) {
            punti = BigDecimal.valueOf(5);
        }
        else if (numeroFiereInternazionali == 2) {
            punti = BigDecimal.valueOf(10);
        }
        else {
            punti = BigDecimal.valueOf(15);
        }

        return punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_ARTICOLAZIONE_PROGETTO)) > 0
                ? BigDecimal.valueOf(MAX_PUNTI_ARTICOLAZIONE_PROGETTO) : punti;
    }

    /**
     * Calcola il punteggio per Sito Web (max 10).
     * 2,5 punti per ogni lingua straniera, max 4 lingue rilevanti.
     * Oltre 4 lingue il punteggio resta 10.
     */
    private BigDecimal _calcolaPuntiSitoWeb(Map<String, String> dati) {
        String numLingueStr = dati.get("sitoWebNumLingueInput");
        int numLingue = _parseIntero(numLingueStr);

        if (numLingue <= 0) {
            return BigDecimal.ZERO;
        }

        int lingueRilevanti = Math.min(numLingue, 4);

        BigDecimal punti = BigDecimal.valueOf(lingueRilevanti)
                .multiply(new BigDecimal("2.5"));

        return punti.compareTo(BigDecimal.valueOf(MAX_PUNTI_SITO_WEB)) > 0
                ? BigDecimal.valueOf(MAX_PUNTI_SITO_WEB) : punti;
    }

    /**
     * Calcola il punteggio per Impresa Femminile (max 5).
     * Certificazione parità di genere: SI = 5, NO = 0.
     */
    private BigDecimal _calcolaPuntiImpresaFemminile(Map<String, String> dati) {
