        if (Validator.isNotNull(partitaIva) && Validator.isNotNull(ragioneSociale)) {
            domandaBando.setPartitaIva(partitaIva);
            domandaBando.setRagioneSociale(ragioneSociale);
        }
    }

    private Map<String, String> retrievePartivaIvaRagioneSociale(long formId, String portalURL, long bandoId,
                                                                 String jsonForm) {
        String partitaIva = null;
        String ragioneSociale = null;
        Map<String, String> response = new HashMap<String, String>();
        if (Validator.isNotNull(jsonForm)) {
            Set<Option> jsonPathOptions = new HashSet<Option>();
            jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
            jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

            Configuration jsonPathConfiguration = Configuration.builder()
                    .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
                    .options(jsonPathOptions).build();

            JsonNode fieldValues = null;

            List<String> listaCampiRegistroImpresa = getNomeCampoByType(jsonForm, portalURL, typesRegistroImpresa,
                    formId);
            List<String> listaCampiRegistroImpresaConfigurabile = getNomeCampoByType(jsonForm, portalURL,
                    typesCustomRegistroImpreseConfigurabile, formId);

            List<String> listaCampiSedeLegale = new ArrayList<String>();

            if (Validator.isNotNull(listaCampiRegistroImpresa) && !listaCampiRegistroImpresa.isEmpty()) {
                for (String campo : listaCampiRegistroImpresa) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }
            } else {
                listaCampiSedeLegale = getNomeCampoByType(jsonForm, portalURL, typesSedeLegale, formId);

                if (Validator.isNotNull(listaCampiSedeLegale) && !listaCampiSedeLegale.isEmpty()) {
                    for (String campo : listaCampiSedeLegale) {
                        String pathCampo = "['" + campo + "']";
                        fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                    }
                }
            }

            if (Validator.isNotNull(listaCampiRegistroImpresa) && !listaCampiRegistroImpresa.isEmpty()) {
                for (String campo : listaCampiRegistroImpresa) {
                    String pathCampo = "['" + campo + "']";
                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                }

                if (fieldValues != null) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = null;

                        if (nodeInfo.has("tipoSoggetto")) {
                            String tipoSoggetto = nodeInfo.get("tipoSoggetto").asText();

                            if (Validator.isNotNull(tipoSoggetto)) {

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.LR.name())) {
                                    nodeInterno = nodeInfo.get("privato");
                                }

                                if (tipoSoggetto.equalsIgnoreCase(TipoSoggettoEnum.SD.name())) {
                                    nodeInterno = nodeInfo.get("privatoDelegato");
                                }
                            }
                        }

                        if (nodeInterno != null) {

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                String pIva = nodeInterno.get("pIva").asText();
                                if (Validator.isNotNull(pIva)) {
                                    partitaIva = pIva;
                                }
                            }

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                    && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }

                        }
                    }
                }
            } else if (Validator.isNotNull(listaCampiRegistroImpresaConfigurabile) && !listaCampiRegistroImpresaConfigurabile.isEmpty()) {

                for (String campo : listaCampiRegistroImpresaConfigurabile) {
                    String pathCampo = "['" + campo + "']";
                    JsonNode fieldValuesOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                            .read(ALPACA_ALPACA_FIELD + ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + pathCampo);
                    boolean isInsegnestoriche = true;
                    try{
                        Bando bando = bandoLocalService.getBando(bandoId);
                        String codiBandiInsegneStoriche = null;
                        exportInserimentoElencoConfiguration = configurationProvider
                                .getGroupConfiguration(BandiInserimentoElencoConfiguration.class, bando.getGroupId());
                        codiBandiInsegneStoriche = exportInserimentoElencoConfiguration.codiciBandiInsegneStoriche();
                        List<String> listaCodiBandiInsegneStoriche = Arrays.asList(codiBandiInsegneStoriche.split(","));
                        if (Validator.isNotNull(bando.getCodice())) {
                            if (listaCodiBandiInsegneStoriche.contains(bando.getCodice())) {
                                isInsegnestoriche=true;
                            }
                        }
                    }catch (Exception e){
                        _log.error("Errore durante il recupero delle informazioni del bando con ID: " + bandoId, e);
                    }

                    if (Validator.isNotNull(fieldValuesOptions) && !fieldValuesOptions.isEmpty()) {
                        JsonNode options = fieldValuesOptions.get(0);
                        if (options.has("fieldClass")) {
                            String fieldClass = options.get("fieldClass").asText();
                            if (Validator.isNotNull(fieldClass)){
                                if (!isInsegnestoriche || (isInsegnestoriche && fieldClass.contains("soggettoDelegante"))) {
                                    fieldValues = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                            .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + pathCampo);
                                    break;
                                }
                            }
                        }
                    }

                }

                if (Validator.isNotNull(fieldValues)) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo != null && !nodeInfo.isEmpty()) {

                        JsonNode nodeInterno = nodeInfo.get("privato");

                        if (Validator.isNotNull(nodeInterno)) {

                            if (nodeInterno.has("pIva") && !nodeInterno.get("pIva").isNull()) {
                                String pIva = nodeInterno.get("pIva").asText();

                                if (Validator.isNotNull(pIva)) {
                                    partitaIva = pIva;
                                }
                            }

                            if (nodeInterno.has("denominazioneSoggettoOrganizzatore")
                                    && !nodeInterno.get("denominazioneSoggettoOrganizzatore").isNull()) {
                                ragioneSociale = nodeInterno.get("denominazioneSoggettoOrganizzatore").asText();
                            }

                        }
                    }
                }
            } else {
                if (Validator.isNotNull(listaCampiSedeLegale) && !listaCampiSedeLegale.isEmpty()) {
                    JsonNode nodeInfo = fieldValues.get(0);

                    if (nodeInfo.has("ragioneSociale")) {
                        if (Validator.isNotNull(nodeInfo.get("ragioneSociale").asText())) {
                            ragioneSociale = nodeInfo.get("ragioneSociale").asText();
                        }
                    } else {
                        JsonNode fieldValuesNome = JsonPath.using(jsonPathConfiguration).parse(jsonForm)
                                .read(ALPACA_ALPACA_FIELD + ALPACA_DATA_FIELD + "['NomeEnte']");
                        if (Validator.isNotNull(fieldValuesNome) && !fieldValuesNome.isEmpty()) {
                            if (Validator.isNotNull(fieldValuesNome.get(0).asText())) {
                                ragioneSociale = fieldValuesNome.get(0).asText();
                            }
                        }
                    }

                    if (nodeInfo.has("partitaIva") && Validator.isNotNull(nodeInfo.get("partitaIva").asText())) {
                        partitaIva = nodeInfo.get("partitaIva").asText();
                    } else if (nodeInfo.has("cf") && Validator.isNotNull(nodeInfo.get("cf").asText())) {
                        partitaIva = nodeInfo.get("cf").asText();
                    }

                }
            }

        }

        if (Validator.isNotNull(partitaIva) && Validator.isNotNull(ragioneSociale)) {
            response.put("PARTITA_IVA", partitaIva);
            response.put("RAGIONE_SOCIALE", ragioneSociale);
        }

        return response;
    }

    public void addDatiAggiuntiviDomandaBando(IstanzaDomandaBando istanzaDomandaBando, Long userId, Long companyId,
                                              String username, Long groupId) throws Exception {
        String istanzaJson = istanzaDomandaBando.getJson();
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
        List<DatoAggiuntivoChiave> chiavi = getDatiAggiuntiviChiaviDaForm(domandaBando.getBandoId());

        Configuration configuration = Configuration.defaultConfiguration().addOptions(Option.SUPPRESS_EXCEPTIONS);
        DocumentContext document = JsonPath.using(configuration).parse(istanzaJson);
        if (Validator.isNotNull(chiavi) && !chiavi.isEmpty()) {
            for (DatoAggiuntivoChiave chiave : chiavi) {

                if (Validator.isNotNull(chiave.getDataJsonPath())) {
                    if (chiave.equals(DatoAggiuntivoChiave.FORM_ESECUZIONE_NON_ABILITATO)) {
                        Object value = document.read(chiave.getDataJsonPath());
                        if (Validator.isNotNull(value)) {
                            List<String> values = List.of(value.toString().split("\\|"));
                            if (Validator.isNotNull(values) && !values.isEmpty()) {
                                for (String valore : values) {
                                    if (Validator.isNotNull(valore)) {
                                        DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                        domandaBandoDatoAggiuntivo.setChiave(chiave.name());
                                        domandaBandoDatoAggiuntivo.setValore(valore);
                                        domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                        domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                                        domandaBandoDatoAggiuntivo.setUserId(userId);
                                        domandaBandoDatoAggiuntivo.setUserName(username);
                                        domandaBandoDatoAggiuntivo.setGroupId(groupId);
                                        domandaBandoDatoAggiuntivoLocalService
                                                .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                                    }
                                }
                            }
                        }
                    } else {
                        Object value = document.read(chiave.getDataJsonPath());
                        if (Validator.isNotNull(value)) {
                            DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                                    .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                            domandaBandoDatoAggiuntivo.setChiave(chiave.name());
                            domandaBandoDatoAggiuntivo.setValore(String.valueOf(value));
                            domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                            domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                            domandaBandoDatoAggiuntivo.setUserId(userId);
                            domandaBandoDatoAggiuntivo.setUserName(username);
                            domandaBandoDatoAggiuntivo.setGroupId(groupId);
                            domandaBandoDatoAggiuntivoLocalService
                                    .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                        }
                    }
                }

            }
            if (!chiavi.contains(DatoAggiuntivoChiave.PROVINCIA_SEDE_LEGALE_ENTE)) {
                Object value = document.read(PROVINCIA_SEDE_LEGALE_ENTE_ALTERNATIVA);
                if (Validator.isNotNull(value)) {
                    DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService
                            .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                    domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.PROVINCIA_SEDE_LEGALE_ENTE.name());
                    domandaBandoDatoAggiuntivo.setValore(String.valueOf(value));
                    domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                    domandaBandoDatoAggiuntivo.setCompanyId(companyId);
                    domandaBandoDatoAggiuntivo.setUserId(userId);
                    domandaBandoDatoAggiuntivo.setUserName(username);
                    domandaBandoDatoAggiuntivo.setGroupId(groupId);
                    domandaBandoDatoAggiuntivoLocalService
                            .updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
                }
            }
        }

        // Recupero dinamico dati aggiuntivi dai campi con attributo "datoAggiuntivo" nelle options
        try {
            JsonObject jsonRoot = new JsonParser().parse(istanzaJson).getAsJsonObject();
            JsonObject alpacaObj = jsonRoot.getAsJsonObject("alpaca");

            if (alpacaObj != null && alpacaObj.has("options") && alpacaObj.has("data")) {
                JsonObject optionsObj = alpacaObj.getAsJsonObject("options");
                JsonObject dataObj = alpacaObj.getAsJsonObject("data");

                if (optionsObj.has("fields") && optionsObj.get("fields").isJsonObject()) {
                    JsonObject optionsFields = optionsObj.getAsJsonObject("fields");
                    Map<String, String> datiAggiuntiviDinamici = new LinkedHashMap<>();
                    Map<String, List<String>> datiAggiuntiviDinamiciArray = new LinkedHashMap<>();
                    _trovaDatiAggiuntiviDaOptions(optionsFields, dataObj, datiAggiuntiviDinamici, datiAggiuntiviDinamiciArray);

                    for (Map.Entry<String, String> entry : datiAggiuntiviDinamici.entrySet()) {
                        String chiaveDinamica = entry.getKey();
                        String valoreDinamico = entry.getValue();

                        if (Validator.isNotNull(chiaveDinamica) && Validator.isNotNull(valoreDinamico)) {
                            long count = domandaBandoDatoAggiuntivoLocalService
                                    .countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                                            domandaBando.getDomandaBandoId(), Collections.singletonList(chiaveDinamica));

                            if (count == 0) {
                                DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                        .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                dato.setChiave(chiaveDinamica);
                                dato.setValore(valoreDinamico);
                                dato.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                dato.setCompanyId(companyId);
                                dato.setUserId(userId);
                                dato.setUserName(username);
                                dato.setGroupId(groupId);
                                domandaBandoDatoAggiuntivoLocalService.updateDomandaBandoDatoAggiuntivo(dato);
                            }
                        }
                    }

                    // Gestione dati aggiuntivi di tipo array
                    for (Map.Entry<String, List<String>> entry : datiAggiuntiviDinamiciArray.entrySet()) {
                        String chiaveDinamica = entry.getKey();
                        List<String> valoriDinamici = entry.getValue();

                        if (Validator.isNotNull(chiaveDinamica) && valoriDinamici != null && !valoriDinamici.isEmpty()) {
                            long count = domandaBandoDatoAggiuntivoLocalService
                                    .countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                                            domandaBando.getDomandaBandoId(), Collections.singletonList(chiaveDinamica));

                            if (count == 0) {
                                for (String valoreDinamico : valoriDinamici) {
                                    if (Validator.isNotNull(valoreDinamico)) {
                                        DomandaBandoDatoAggiuntivo dato = domandaBandoDatoAggiuntivoLocalService
                                                .createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                                        dato.setChiave(chiaveDinamica);
                                        dato.setValore(valoreDinamico);
                                        dato.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                        dato.setCompanyId(companyId);
                                        dato.setUserId(userId);
                                        dato.setUserName(username);
                                        dato.setGroupId(groupId);
                                        domandaBandoDatoAggiuntivoLocalService.addDomandaBandoDatoAggiuntivo(dato);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        catch (Exception e) {
            log.error("Errore nel recupero dati aggiuntivi da attributo datoAggiuntivo nelle options: " + e.getMessage(), e);
        }
    }

    private List<DatoAggiuntivoChiave> getDatiAggiuntiviChiaviDaForm(long bandoId) throws Exception {
        List<BandoForm> bandoForms = bandoFormLocalService.getListaBandoFormBando(bandoId);
        BandoForm bandoForm = bandoForms.stream().filter(bf -> Validator.isNull(bf.getTipoForm())).findFirst()
                .orElseThrow();
        Form form = formLocalService.getForm(bandoForm.getFormId());
        String formJson = form.getJson();

        Configuration configuration = Configuration.defaultConfiguration().addOptions(Option.SUPPRESS_EXCEPTIONS);
        DocumentContext document = JsonPath.using(configuration).parse(formJson);

        List<DatoAggiuntivoChiave> chiaviPresenti = new ArrayList<>();
        for (DatoAggiuntivoChiave chiave : DatoAggiuntivoChiave.values()) {

            if (Validator.isNotNull(chiave.getSchemaJsonPath())) {
                Object value = document.read(chiave.getSchemaJsonPath());
                boolean found = Validator.isNotNull(value);

                if (found) {
                    chiaviPresenti.add(chiave);
                }
            }

        }
        chiaviPresenti.sort(NUMERO_ORDINE_COMP);
        return chiaviPresenti;
    }

    /**
     * Attraversa ricorsivamente la struttura options.fields del form Alpaca
     * per trovare tutti i campi con attributo "datoAggiuntivo" e recuperare
     * il corrispondente valore dai data.
     *
     * @param optionsFields nodo options.fields corrente
     * @param dataObj       nodo data corrente (parallelo alla struttura options)
     * @param risultato     mappa chiave datoAggiuntivo -> valore dal data
     */
    private void _trovaDatiAggiuntiviDaOptions(JsonObject optionsFields, JsonObject dataObj,
                                                Map<String, String> risultato,
                                                Map<String, List<String>> risultatoArray) {
        if (optionsFields == null || dataObj == null) {
            return;
        }

        for (Map.Entry<String, com.google.gson.JsonElement> entry : optionsFields.entrySet()) {
            String fieldName = entry.getKey();
            com.google.gson.JsonElement fieldElement = entry.getValue();

            if (fieldElement == null || !fieldElement.isJsonObject()) {
                continue;
            }

            JsonObject fieldObj = fieldElement.getAsJsonObject();

            // Verifica se questo campo ha l'attributo datoAggiuntivo
            if (fieldObj.has("datoAggiuntivo") && !fieldObj.get("datoAggiuntivo").isJsonNull()) {
                String chiave = fieldObj.get("datoAggiuntivo").getAsString();

                if (Validator.isNotNull(chiave) && dataObj.has(fieldName) && !dataObj.get(fieldName).isJsonNull()) {
                    com.google.gson.JsonElement dataElement = dataObj.get(fieldName);

                    if (dataElement.isJsonPrimitive()) {
                        risultato.put(chiave, dataElement.getAsString());
                    } else if (dataElement.isJsonArray()) {
                        com.google.gson.JsonArray jsonArray = dataElement.getAsJsonArray();
                        List<String> elementi = new ArrayList<>();
                        for (int i = 0; i < jsonArray.size(); i++) {
                            com.google.gson.JsonElement arrayElement = jsonArray.get(i);
                            if (arrayElement != null && !arrayElement.isJsonNull()) {
                                elementi.add(arrayElement.toString());
                            }
                        }
                        if (!elementi.isEmpty()) {
                            risultatoArray.put(chiave, elementi);
                        }
                    }
                }
            }

            // Ricorsione nei sotto-campi (fields annidati)
            if (fieldObj.has("fields") && fieldObj.get("fields").isJsonObject()) {
                JsonObject nestedOptionsFields = fieldObj.getAsJsonObject("fields");

                if (dataObj.has(fieldName) && dataObj.get(fieldName).isJsonObject()) {
                    JsonObject nestedDataObj = dataObj.getAsJsonObject(fieldName);
                    _trovaDatiAggiuntiviDaOptions(nestedOptionsFields, nestedDataObj, risultato, risultatoArray);
                }
            }
        }
    }

