	public void salvaListaFormIntegrativi(String[] listaFormIntegrativi, long bandoId, String userFullName, long userId,
										  long siteGroupId) {
		List<BandoForm> listaBandoFormRecuperatiDb = bandoFormLocalService.getListaBandoFormBando(bandoId);
		List<BandoForm> listaBandoFormRecuperatiForm = new ArrayList<BandoForm>();


		_log.debug("listaBandoFormRecuperatiDb0"+listaBandoFormRecuperatiDb);

		Form formPrincipale = getFormPrincipaleBando(bandoId);

		if (Validator.isNotNull(listaFormIntegrativi)) {
			for (String idForm : listaFormIntegrativi) {

				_log.debug("idForm"+idForm);

				if (Validator.isNotNull(idForm)) {

					BandoForm bandoFormItem=null;


					//	bandoFormPk.setTipoForm("");
					bandoFormItem = bandoFormLocalService.createBandoForm(CounterLocalServiceUtil.increment());
					bandoFormItem.setBandoId(bandoId);
					bandoFormItem.setFormId(Long.valueOf(idForm));
					bandoFormItem.setGroupId(siteGroupId);
					bandoFormItem.setUserId(userId);
					bandoFormItem.setUserName(userFullName);

					listaBandoFormRecuperatiForm.add(bandoFormItem);
				}
			}
		}

		if (Validator.isNotNull(listaBandoFormRecuperatiDb) && !listaBandoFormRecuperatiDb.isEmpty()) {

			_log.debug("sono dentro validator integr");

			if (Validator.isNotNull(listaBandoFormRecuperatiForm) && Validator.isNotNull(formPrincipale)) {
				List<BandoForm> elementiDaEliminare = listaBandoFormRecuperatiDb.stream()
						.filter(bandoForm -> !listaBandoFormRecuperatiForm.contains(bandoForm)
								&& bandoForm.getFormId() != formPrincipale.getFormId()
								&& !bandoForm.getTipoForm().equals(TipoFormEnum.ESECUZIONE.name())
								&& !bandoForm.getTipoForm().equals(TipoFormEnum.ESECUZIONE_CRONOPROGRAMMA.name()))
						.collect(Collectors.toList());
				List<BandoForm> elementiDaAggiungere = listaBandoFormRecuperatiForm.stream()
						.filter(bandoForm -> !listaBandoFormRecuperatiDb.contains(bandoForm)
								&& bandoForm.getFormId() != formPrincipale.getFormId())
						.collect(Collectors.toList());


				_log.debug("elementiDaEliminare:"+elementiDaEliminare);
				_log.debug("elementiDaAggiungere:"+elementiDaAggiungere);

				for (BandoForm bandoForm : elementiDaEliminare) {
					bandoFormLocalService.deleteBandoForm(bandoForm);
				}

				for (BandoForm bandoForm : elementiDaAggiungere) {
					bandoFormLocalService.updateBandoForm(bandoForm);
				}

			}
		} else {
			_log.debug("sono dentro else integr");

			for (BandoForm bandoForm : listaBandoFormRecuperatiForm) {
				bandoFormLocalService.updateBandoForm(bandoForm);
			}
		}

	}

