                bandoFormItem.setUserName(userFullName);
                bandoFormItem.setBandoId(bando.getBandoId());
                bandoFormItem.setFormId(Long.valueOf(idForm));

                Form formIntegrativoEsecuzione = formLocalService.getForm(Long.valueOf(idForm));
                List<FormField> listaField = null;
                List<FormField> listaFieldAnticipo = null;
                List<FormField> listaFieldSaldo = null;
                List<FormField> listaFieldRinuncia = null;

                if(Validator.isNotNull(formIntegrativoEsecuzione) && !formIntegrativoEsecuzione.getJson().isEmpty()) {
                    listaField = JsonPathUtil.getFormFields(formIntegrativoEsecuzione.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_CRONOPROGRAMMA);
                    listaFieldAnticipo = JsonPathUtil.getFormFields(formIntegrativoEsecuzione.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_ANTICIPO);
                    listaFieldSaldo = JsonPathUtil.getFormFields(formIntegrativoEsecuzione.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_SALDO);
                    listaFieldRinuncia = JsonPathUtil.getFormFields(formIntegrativoEsecuzione.getJson(), GestioneBandiFrontendPortletKeys.TIPO_CUSTOM_FIELD_RINUNCIA);
                }

                if(Validator.isNotNull(listaField) && !listaField.isEmpty()) {
                    bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_CRONOPROGRAMMA.name());
                }
                else if(Validator.isNotNull(listaFieldAnticipo) && !listaFieldAnticipo.isEmpty()) {
                    boolean isIntegrazione = checkFormIntegrazione(listaFieldAnticipo, formIntegrativoEsecuzione.getJson());
                    boolean isPrimoAnticipo = checkFormPrimoAnticipo(listaFieldAnticipo, formIntegrativoEsecuzione.getJson());
                    boolean isSecondoAnticipo = checkFormSecondoAnticipo(listaFieldAnticipo, formIntegrativoEsecuzione.getJson());
                    if (isIntegrazione) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name());
                    } else if (isPrimoAnticipo) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name());
                    } else if (isSecondoAnticipo) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name());
                    } else {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_ANTICIPO.name());
                    }
                }
                else if(Validator.isNotNull(listaFieldSaldo) && !listaFieldSaldo.isEmpty()) {
                    boolean isIntegrazione = checkFormIntegrazione(listaFieldSaldo, formIntegrativoEsecuzione.getJson());
                    if (isIntegrazione) {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name());
                    } else {
                        bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_SALDO.name());
                    }
                }
                else if(Validator.isNotNull(listaFieldRinuncia) && !listaFieldRinuncia.isEmpty()) {
                    bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE_RINUNCIA.name());
                }
                else{
                    bandoFormItem.setTipoForm(TipoFormEnum.ESECUZIONE.name());
                }

                listaBandoFormIntegrativiEsecuzione.add(bandoFormItem);
            }
        }
    }
}

