public List<IntegrazioneRichiestaDTO> getRichiesteIntegrazioni(long domandaBandoId, long bandoId, int start, int end) {
    List<String> tipiDaEscludere;
    Bando bando = bandoLocalService.fetchBando(bandoId);
    if(bando.getAbilitaEsecuzioneIntegrazione()){
        tipiDaEscludere = Arrays.asList(
                TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_SALDO.name(),
                TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_RINUNCIA.name(),
                TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE.name(),
                TipoFormEnum.ESECUZIONE_CRONOPROGRAMMA.name()
        );
    }else{
        tipiDaEscludere = Arrays.asList(
                TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_SALDO.name(),
                TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO.name()
        );
    }

    List<BandoForm> listaBandoFormDaEscludere = new ArrayList<>();
    for (String tipo : tipiDaEscludere) {
        List<BandoForm> forms = bandoFormLocalService.getListaBandoFormBandoAndType(bandoId, tipo);
        if (Validator.isNotNull(forms)) {
            listaBandoFormDaEscludere.addAll(forms);
        }
    }
    List<Long> formIdDaEscluderePerTipo = listaBandoFormDaEscludere.stream()
            .map(BandoForm::getFormId)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());

    List<BandoForm> listaBandoForm = bandoFormLocalService.getListaBandoFormBando(bandoId);
    List<Long> tuttiFormIdDelBando = listaBandoForm.stream()
            .map(BandoForm::getFormId)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());

    List<Form> formsPrincipali = formLocalService.getFormsByIdsAndPrincipale(tuttiFormIdDelBando);
    List<Long> formIdDaEscluderePerPrincipale = formsPrincipali.stream()
            .map(Form::getFormId)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());

    Set<Long> formIdDaEscludere = new HashSet<>();
    formIdDaEscludere.addAll(formIdDaEscluderePerTipo);
    formIdDaEscludere.addAll(formIdDaEscluderePerPrincipale);

    List<IstanzaDomandaBando> istanzeFiltrate =
            istanzaDomandaBandoLocalService.getListIstanzaDomandaBandoByDomandaBandoIdAndNotListaFormId(
                    domandaBandoId,
                    new ArrayList<>(formIdDaEscludere)
            );

    List<IstanzaDomandaBando> paginated = istanzeFiltrate.stream()
            .sorted(Comparator.comparing(IstanzaDomandaBando::getCreateDate))
            .skip(start)
            .limit(end - start)
            .collect(Collectors.toList());

    return paginated.stream()
            .map(this::mapRichiestaIntegrazioni)
            .collect(Collectors.toList());
}

