private void applyMockDatiConcessione(JsonObject alpacaJsonData, AlpacaJsonOptionsStructure optionsStr) {
    String mockCodiceFiscaleEnte = "RSSNTN81A05B519S";
    String mockPartitaIvaEnte = "12345678901";
    String mockRagioneSociale = "ENTE DI PROVA SRL";
    String mockTitoloProgetto = "Progetto di prova - Annualità 2025";
    String mockTitoloProgrammazioneTriennale = "Programmazione Triennale 2025/2027";
    BigDecimal mockImportoAssegnato = new BigDecimal("150000.00");
    String mockProvinciaSedeLegale = "BA";
    String mockCittaSedeLegale = "BARI";
    String mockIndirizzoSedeLegale = "Via Roma 1";
    String mockCapSedeLegale = "70121";

    // Container di tipo "datiDomandaBando"
    for (JsonObject container : getMockDataContainers(alpacaJsonData, optionsStr, typesCompilaDatiDomandaBando)) {
        container.addProperty("codiceFiscale", mockCodiceFiscaleEnte);
        container.addProperty("titoloProgetto", mockTitoloProgetto);
        container.addProperty("titoloProgrammazioneTriennale", mockTitoloProgrammazioneTriennale);
        container.addProperty("importoAssegnato", mockImportoAssegnato);
        container.addProperty("provinciaSedeLegaleEnte", mockProvinciaSedeLegale);
        container.addProperty("cittaSedeLegale", mockCittaSedeLegale);
        container.addProperty("indirizzoSedeLegaleEnte", mockIndirizzoSedeLegale);
        container.addProperty("capSedeLegale", mockCapSedeLegale);
    }

    // Container di tipo "datiDisciplinareCustom" e "datiDisciplinareEsecuzioneCustom" (stesse proprieta')
    List<JsonObject> containerDisciplinare = new ArrayList<>();
    containerDisciplinare.addAll(getMockDataContainers(alpacaJsonData, optionsStr, typesCompilaDisciplinareBandi));
    for (JsonObject container : containerDisciplinare) {
        container.addProperty("soggettoBeneficiario", mockRagioneSociale);
        container.addProperty("codiceFiscale", mockCodiceFiscaleEnte);
        container.addProperty("partitaIva", mockPartitaIvaEnte);
        container.addProperty("titoloProgetto", mockTitoloProgetto);
        container.addProperty("citta", mockCittaSedeLegale);
        container.addProperty("via", mockIndirizzoSedeLegale);
        container.addProperty("cap", mockCapSedeLegale);
    }
}

