public byte[] generaPDFDisciplinareForm(DomandaBando domandaBando, AlpacaJsonStructure alpacaStructure, String codice) throws PDFServiceException {

    byte[] pdfContent = null;

    try {

        SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

        Map<String, Object> data = new HashMap<String, Object>();

        String htmlContent = null;

        long bandoId = domandaBando.getBandoId();
        Bando bando = bandoLocalService.getBando(bandoId);
        long groupId = bando.getGroupId();
        Group group = groupLocalService.getGroup(groupId);

        freemarkerTemplateEnteConfiguration = configurationProvider.getGroupConfiguration(FreemarkerTemplateEnteConfiguration.class, groupId);

        long organizationId = groupLocalService.getGroup(groupId).getOrganizationId();

        Organization organization = organizationLocalService.getOrganization(organizationId);

        LayoutSet layout = layoutSetLocalService.getLayoutSet(groupId, false);

        String portalUrl = layoutUtility.getSitePath(groupId, group.getCompanyId());

        long logoId = layout.getLogoId();
        data.put("logoId", String.valueOf(logoId));

        data.put("comune", organization.getName());

        data.put("defaultThemeUrl", freemarkerTemplateEnteConfiguration.themeBasePath());
        data.put("url", freemarkerTemplateEnteConfiguration.presentatoreFormsBasePath());
        data.put("portalUrl", portalUrl);
        data.put("dataCorrente", sdf.format(new Date()));
        data.put("denominazioneRichiedente", domandaBando.getUserName());
        data.put("denominazioneBando", bando.getNome());
        //	data.put("partitaIva", domandaBando.getPartitaIva());
        //	data.put("titoloProgetto", domandaBando.getTitoloProgetto());
        JsonObject dataJsonObject = (JsonObject) alpacaStructure.getData();
        Map<String, String> mappaValori = convertiData(dataJsonObject);
        for (Map.Entry<String, String> entry : mappaValori.entrySet()) {
            data.put(entry.getKey(), entry.getValue());
        }
        data.put(GestioneBandiCommonConstants.ALPACA_STRUCTURE, alpacaStructure);

        addParametriAggiuntivi(data, portalUrl);

        ByteArrayOutputStream os = new ByteArrayOutputStream();
        Template template =  getTemplateByTipo(bandoId, codice, TipoTemplate.FREEMARKER.name());

        if(Validator.isNull(template)) {
            String templateString = freemarkerTemplateEnteConfiguration.defaultAlpacaTemplate();

            if (String.valueOf(CodiceTemplatePdf.REVOCA).equalsIgnoreCase(codice)) {
                templateString = freemarkerTemplateEnteConfiguration.revocaAlpacaTemplate();
            }

            Configuration config = new Configuration(Configuration.VERSION_2_3_29);
            template = new Template("templateName", new StringReader(templateString), config);
        }

        template.process(data, new OutputStreamWriter(os));

        htmlContent = os.toString(StandardCharsets.UTF_8);

        String headerHtml = null;
        String headerStartMarker = "<!-- DISCIPLINARE_HEADER_START -->";
        String headerEndMarker = "<!-- DISCIPLINARE_HEADER_END -->";
        int headerStart = htmlContent.indexOf(headerStartMarker);
        int headerEnd = htmlContent.indexOf(headerEndMarker);

        if (headerStart >= 0 && headerEnd >= 0) {
            headerHtml = htmlContent.substring(headerStart + headerStartMarker.length(), headerEnd).trim();
            htmlContent = htmlContent.substring(headerEnd + headerEndMarker.length()).trim();
        }

        pdfContent = pdfConverter.generatePDF(htmlContent, freemarkerTemplateEnteConfiguration.disciplinareWkhtmltopdfParams(), headerHtml);
    }
    catch (Exception e) {
        log.error("generaPDFDisciplinareForm :: " + e.getMessage(), e);
        throw new PDFServiceException("Errore durante il processo di generazione del PDF :: " + e.getMessage(), e);
    }

