package it.servizidigitali.gestionebandi.common.enumeration;

import java.util.ArrayList;
import java.util.List;

/**
 * Enumeration per la definizione dei possibili stati assegnabili ad una Domanda Bando.
 *
 * @author costabilee
 *
 */
public enum StatoDomandaBandoEnum {

	BOZZA("Bozza", true), //
	NUOVA("Nuova", false),
	INVIATA("Inviata", false),
	PROTOCOLLATA("Protocollata", false),
	IN_LAVORAZIONE("In lavorazione", false), //
	ATTESA_INTEGRAZIONI("Attesa integrazioni", false),
	INTEGRAZIONI_INSERITE("Integrazioni inserite", false),
	ATTESA_BROCHURE("Attesa compilazione brochure", false),
	BROCHURE_INSERITE("Brochure inserita", false),
	CHIUSA_POSITIVAMENTE("Chiusa con esito positivo", false),
	CHIUSA_NEGATIVAMENTE("Chiusa con esito negativo", true),
	ANNULLATA("Annullata", true),
	PARTECIPAZIONE_EFFETTUATA("Partecipazione all'evento effettuata", true),
	ASSENZA_GIUSTIFICATA("Partecipazione all'evento non effettuata (con preavviso)", true),
	ASSENZA_NON_GIUSTIFICATA("Partecipazione all'evento non effettuata (senza preavviso)", true);

    private String name;
	private boolean escludereBudget;

	private StatoDomandaBandoEnum(String name, boolean escludereBudget){
		this.name = name;
		this.escludereBudget = escludereBudget;
	}

	public String getName() {
		return name;
	}

	public void setName(String name) {
		this.name = name;
	}

	public boolean isEscludereBudget() {
		return escludereBudget;
	}

	public static StatoDomandaBandoEnum findByName(String name) {
		StatoDomandaBandoEnum result = null;
	    for (StatoDomandaBandoEnum statoDomandaBando : values()) {
	        if (statoDomandaBando.name().equalsIgnoreCase(name)) {
	            result = statoDomandaBando;
	            break;
	        }
	    }
	    return result;
	}

	public static List<String> getNamesByEscludereBudget(boolean escludereBudget) {
		List<String> result = new ArrayList<>();
		for (StatoDomandaBandoEnum stato : values()) {
			if (stato.escludereBudget == escludereBudget) {
				result.add(stato.name());
			}
		}
		return result;
	}
}

