public String getFormIntegrativoPathDomandaBandoEsecuzione(DomandaBando domandaBando) throws PortalException {

    String paginaServizio = getPathDomandaBando(domandaBando);

    Layout layout = getLayoutFromDomandaBando(domandaBando);
    LayoutTypePortlet layoutTypePortlet = (LayoutTypePortlet) layout.getLayoutType();
    List<Portlet> allPortlets = layoutTypePortlet.getAllPortlets();
    String instancePortleId = null;
    if (allPortlets != null) {
        for (Portlet portlet : allPortlets) {
            if (portlet.getPortletName().equals(PRESENTATORE_FORMS_BANDI_PORTLET_ID)) {
                instancePortleId = portlet.getPortletId();
                break;
            }
        }
    }
    String command = COMPILA_DOCUMENTO_ESECUZIONE_MVC_RENDER_COMMAND_NAME;

    paginaServizio += "?p_p_id=" + instancePortleId + "&_" + instancePortleId + "_mvcRenderCommandName=" + command + "&_" + instancePortleId + "_domandaBandoId="
            + domandaBando.getDomandaBandoId();

    return paginaServizio;

}

