package it.servizidigitali.gestionebandi.operatore.frontend.util;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import it.servizidigitali.gestionebandi.common.enumeration.FaseWorkflowBandoEnum;
import it.servizidigitali.gestionebandi.model.IstanzaDomandaBando;
import it.servizidigitali.gestionebandi.model.TermineBando;
import it.servizidigitali.gestionebandi.service.IstanzaDomandaBandoLocalService;
import it.servizidigitali.gestionebandi.service.TermineBandoLocalService;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import java.time.Duration;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Date;
import java.util.List;

@Component(immediate = true, service = IntegrationDeadlinePopulator.class)
public class IntegrationDeadlinePopulator {

    private static final Log log = LogFactoryUtil.getLog(IntegrationDeadlinePopulator.class);

    private static final String ANNULLA_INTEGRAZIONE_PREFIX = "ANNULLA_INTEGRAZIONE_";

    @Reference
    private TermineBandoLocalService termineBandoLocalService;

    @Reference
    private IstanzaDomandaBandoLocalService istanzaDomandaBandoLocalService;

    public void populateDeadlines(long domandaBandoId, long bandoId, FaseWorkflowBandoEnum fase, List<IstanzaDomandaBando> nuoveIstanze) {
        logPopulateStart(domandaBandoId, bandoId, nuoveIstanze);

        validateArguments(fase, domandaBandoId, bandoId, nuoveIstanze);

        TermineBando termine = findTermineAnnullaIntegrazione(bandoId, fase);
        if (isTermineMissing(termine, bandoId, fase)) {
            return;
        }

        DeadlineWindow window = computeDeadlineWindow(termine, bandoId);
        applyDeadlineWindow(nuoveIstanze, window);
    }

    private void logPopulateStart(long domandaBandoId, long bandoId, List<IstanzaDomandaBando> nuoveIstanze) {
        int istanzeSize = nuoveIstanze == null ? 0 : nuoveIstanze.size();
        log.info("populateDeadlines :: avvio popolamento deadline per domandaBandoId=" + domandaBandoId
                + ", bandoId=" + bandoId + ", istanze=" + istanzeSize);
    }

    private static void validateArguments(FaseWorkflowBandoEnum fase, long domandaBandoId, long bandoId, List<IstanzaDomandaBando> nuoveIstanze) {
        if (fase == null) {
            throw new IllegalArgumentException("fase is null");
        }

        if (nuoveIstanze == null) {
            throw new IllegalArgumentException("nuoveIstanze is null");
        }

        if (nuoveIstanze.isEmpty()) {
            throw new IllegalArgumentException("nuoveIstanze vuoto");
        }

        if (domandaBandoId <= 0) {
            log.info("populateDeadlines :: domandaBandoId non valido, deadline non popolate");
            throw new IllegalArgumentException("domandaBandoId non valido");
        }

        if (bandoId <= 0) {
            log.info("populateDeadlines :: bandoId non valido, deadline non popolate");
            throw new IllegalArgumentException("bandoId non valido");
        }
    }

    private TermineBando findTermineAnnullaIntegrazione(long bandoId, FaseWorkflowBandoEnum fase) {
        String codiceTermine = ANNULLA_INTEGRAZIONE_PREFIX + fase.name();
        log.info("populateDeadlines :: ricerca termine bando con codice=" + codiceTermine + " per bandoId=" + bandoId);
        return termineBandoLocalService.getTermineBandoByBandoIdAndCodice(bandoId, codiceTermine);
    }

    private boolean isTermineMissing(TermineBando termine, long bandoId, FaseWorkflowBandoEnum fase) {
        boolean missing = termine == null;
        if (missing) {
            log.info("populateDeadlines :: termine bando non trovato per bandoId=" + bandoId + ", fase=" + fase
                    + ", deadline non popolate");
        }
        return missing;
    }

    private DeadlineWindow computeDeadlineWindow(TermineBando termine, long bandoId) {
        long secondi = termine.getSecondi();
        boolean festivi = termine.isFestivi();

        Date dataScadenzaConfigurata = termine.getDataScadenza();

        log.info("populateDeadlines :: termine bando trovato: codice=" + termine.getCodice()
                + ", secondi=" + secondi + ", festivi=" + festivi + ", dataScadenza=" + dataScadenzaConfigurata);

        if (secondi <= 0) {
            throw new IllegalStateException("populateDeadlines :: il campo secondi del termine bando '"
                    + termine.getCodice() + "' (bandoId=" + bandoId + ") deve essere valorizzato e maggiore di zero");
        }

        LocalDateTime inizio = LocalDateTime.now();
        Duration durata = computeDurata(inizio, secondi, festivi);
        LocalDateTime fine = inizio.plus(durata);

        Date dataInizioInserimento = toDate(inizio);
        Date dataFineInserimento = toDate(fine);

        log.info("populateDeadlines :: deadline calcolate: dataInizioInserimento=" + dataInizioInserimento
                + ", dataFineInserimento=" + dataFineInserimento);

        return new DeadlineWindow(dataInizioInserimento, dataFineInserimento);
    }

    private void applyDeadlineWindow(List<IstanzaDomandaBando> nuoveIstanze, DeadlineWindow window) {
        for (IstanzaDomandaBando istanza : nuoveIstanze) {
            applyToIstanza(istanza, window);
        }
    }

    private void applyToIstanza(IstanzaDomandaBando istanza, DeadlineWindow window) {
        istanza.setDataInizioInserimento(window.getStart());
        istanza.setDataFineInserimento(window.getEnd());

        istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanza);

        log.info("populateDeadlines :: istanza aggiornata istanzaDomandaBandoId=" + istanza.getIstanzaDomandaBandoId()
                + ", dataInizioInserimento=" + window.getStart() + ", dataFineInserimento=" + window.getEnd());
    }

    private Duration computeDurata(LocalDateTime start, long secondi, boolean festivi) {
        if (festivi) {
            return DateUtils.getDuration(secondi);
        }
        return DateUtils.getDurationConFestivi(start, secondi);
    }

    private static Date toDate(LocalDateTime ldt) {
        return Date.from(ldt.atZone(ZoneId.systemDefault()).toInstant());
    }

    private static final class DeadlineWindow {
        private final Date start;
        private final Date end;

        private DeadlineWindow(Date start, Date end) {
            this.start = start;
            this.end = end;
        }

        private Date getStart() {
            return start;
        }

        private Date getEnd() {
            return end;
        }
    }
}

