    private String randomString(int length) {
        int leftLimit = 48; // numeral '0'
        int rightLimit = 122; // letter 'z'
        Random random = new Random();

        String generatedString = random.ints(leftLimit, rightLimit + 1).filter(i -> (i <= 57 || i >= 65) && (i <= 90 || i >= 97)).limit(length)
                .collect(StringBuilder::new, StringBuilder::appendCodePoint, StringBuilder::append).toString();

        return generatedString;
    }

    public boolean updateAndGeneratePagamentoAvviso(PagamentoDovuto pagamentoDovuto, Pagamento pagamento, ProceduraDovuto proceduraDovuto, long userId, long organizationId, long groupId, long companyId, boolean update)
            throws Exception {
        boolean generato = false;

        if (pagamentoDovuto != null && proceduraDovuto != null) {
            User user = userLocalService.getUser(userId);
            pagamento = pagamentoLocalService.getPagamento(pagamentoDovuto.getPagamentoId());
            Organization organization = organizationLocalService.getOrganization(organizationId);
            String codiceOrganizzazione = organization.getExpandoBridge().getAttribute(OrganizationCustomAttributes.CODICE_IPA.getNomeAttributo()).toString();

            String tipoPersona = TipoDebitore.PERSONA_FISICA.name();
            String codiceFiscaleDebitore = user.getScreenName();
            String nomeDebitore = user.getFirstName();
            String cognomeDebitore = user.getLastName();

            PagamentoDovutoModel dovuto = new PagamentoDovutoModel();
            dovuto.setPagamentoDovutoId(pagamentoDovuto.getPagamentoDovutoId());
            dovuto.setImporto(pagamentoDovuto.getImporto());
            dovuto.setIud(randomString(35));

            if (pagamentoDovuto.getTipologiaDovuto() != null) {
                TipologiaDovuto tipologiaDovuto = pagamentoDovuto.getTipologiaDovuto();

                if (tipologiaDovuto.getCodice() != null) {
                    dovuto.setCodiceDovuto(tipologiaDovuto.getCodice());
                }

                if (tipologiaDovuto.getDescrizione() != null) {
                    dovuto.setCausale(tipologiaDovuto.getDescrizione());
                }
            }

            dovuto.setIdFiscaleCliente(codiceFiscaleDebitore);
            dovuto.setDenominazioneCliente(nomeDebitore + " " + cognomeDebitore);
            dovuto.setNome(nomeDebitore);
            dovuto.setCognome(cognomeDebitore);
            dovuto.setEmailQuietanza(user.getEmailAddress());
            dovuto.setTipoPersona(tipoPersona);
            dovuto.setCodiceOrganizzazione(codiceOrganizzazione);

            generato = gestionePagamentiDovutiService.generaAvviso(dovuto, pagamentoDovuto.getPagamentoId(), pagamentoDovuto.getPagamentoDovutoId(), pagamentoDovuto.getTipologiaDovutoId(),
                    organizationId, userId, groupId, companyId, update);

            if (generato) {
                pagamento.setStato(StatoPagamento.IN_ATTESA.name());
                pagamentoLocalService.updatePagamento(pagamento);
            }
        }

        return generato;
    }

