    public void aggiornaStatoLetturaComunicazioniBandi(long domandaBandoId, long userId) {
        List<CommentoDomandaBando> commentiDomandaBando = commentoDomandaBandoLocalService.getCommentiDomandaBandoByDomandaBandoIdVisibile(domandaBandoId, true, QueryUtil.ALL_POS,
                QueryUtil.ALL_POS);
