// Per i disciplinari ogni compilazione deve produrre un PDF distinto: non si riusa l'allegato
// esistente, così ne viene creato uno nuovo (file e record) ad ogni generazione.
boolean generaPdfDistintoPerOgniCompilazione =
        tipoModulo.equalsIgnoreCase(PresentatoreFormsPortletKeys.DISCIPLINARE)
                || tipoModulo.equalsIgnoreCase(PresentatoreFormsPortletKeys.DISCIPLINARE_ESECUZIONE);

AllegatoDomandaBando allegatoDomandaBando = null;
if(!generaPdfDistintoPerOgniCompilazione && allegati!= null && allegati.size()>0){
    for (AllegatoDomandaBando allegato : allegati){
        if(allegato.getTitolo().equalsIgnoreCase(titoloDocumento)){
            allegatoDomandaBando = allegato;
            break;
        }
    }
}

