            if (CamundaActionsVariable.VAR_COMPILA_DISCIPLINARE.getValue().equalsIgnoreCase(variable.getName())) {
                String valRichiesta = (String) variable.getValue();
                if (valRichiesta.equalsIgnoreCase("true")) {
