    public boolean verificaValoreVariabileCamunda (DomandaBando domanda, String nomeVariabile, String valoreVariabile){
        List<VariableInstance> vars = camundaClient.getVariablesByProcessInstanceId(domanda.getProcessInstanceId());
        boolean variabileCorrispondenteAlValue = false;
        if(vars!=null){
