        if(tipoBando.getCodice().equalsIgnoreCase(TipologiaBandoEnum.AVVISO_SPORTELLO.name()) || tipoBando.getCodice().equalsIgnoreCase(TipologiaBandoEnum.AVVISO_SPORTELLO_VALUTAZIONE.name()) || tipoBando.getCodice().equalsIgnoreCase(TipologiaBandoEnum.PROCEDURA_NEGOZIALE.name()) || tipoBando.getCodice().equalsIgnoreCase(TipologiaBandoEnum.RICHIESTA_CONTRIBUTI.name()))
            checkAvvisoSportello = true;
        return checkAvvisoSportello;
    }

