            List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoSaldo = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(List.of(domandaBandoId), List.of(DatoAggiuntivoChiave.FORM_ESECUZIONE_NON_ABILITATO.name()));
            boolean domandaDiSecondoAnticipoTrovata = false;

            List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoTipologiaEnte = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(List.of(domandaBandoId), List.of(DatoAggiuntivoChiave.TIPOLOGIA_ENTE.name()));
            TipologiaEnteBando tipologiaEnteBando = null;

            if(ListUtil.isNotNull(domandaBandoDatoAggiuntivoTipologiaEnte) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivoTipologiaEnte) && domandaBandoDatoAggiuntivoTipologiaEnte.size()==1){
                if(Validator.isNotNull(domandaBandoDatoAggiuntivoTipologiaEnte.get(0))){
                    DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoTipologiaEnte.get(0);
                    if(Validator.isNotNull(domandaBandoDatoAggiuntivo.getValore())){
                        tipologiaEnteBando = TipologiaEnteBando.valueOf(domandaBandoDatoAggiuntivo.getValore());
                    }
                }
            }

            DomandaBando domandaBando = null;
            AttivitaDomandaBando attivitaDomandaBando = null;
            List<AttivitaDomandaBando> attivitaDomandaBandoList = new ArrayList<>();
            try {
                domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);
            } catch (PortalException e) {
                throw new RuntimeException(e);
            }
            Bando bando = bandoLocalService.fetchBando(domandaBando.getBandoId());

            CommentoDomandaBando commentoDomandaBando = null;
            long commentoDomandaBandoId = 0;
            if (Validator.isNotNull(note)) {
                commentoDomandaBando = commentoDomandaBandoLocalService.addCommento(ctx, domandaBandoId, true, note, null);
                commentoDomandaBandoId = commentoDomandaBando.getCommentoDomandaBandoId();
            }

            List<BandoForm> listaBandiForm = bandoFormLocalService.getListaBandoFormBandoAndType(domandaBando.getBandoId(), TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name());
            List<Long> listaBandiFormIds = listaBandiForm.stream().map(BandoFormModel::getFormId).collect(Collectors.toList());
            List<IstanzaDomandaBando> istanzeDomandeBando = istanzaDomandaBandoLocalService.getListIstanzaDomandaBandoByDomandaBandoIdAndListaFormId(domandaBandoId, listaBandiFormIds);
            if(ListUtil.isNotNull(istanzeDomandeBando) && ListUtil.isNotEmpty(istanzeDomandeBando)){
                for(IstanzaDomandaBando istanzaDomandaBando : istanzeDomandeBando){
                    if(Validator.isNotNull(istanzaDomandaBando)){
                        try{
                            Map<String, String> anticipazioneInfo = getAnticipazioneProtocolInfoEsecuzione(istanzaDomandaBando);
                            Contesto contesto = Contesto.valueOf(bando.getContesto());
                            getDocumentoProtocollo(domandaBando, istanzaDomandaBando.getIstanzaDomandaBandoId(), bando.getTipoGenerazionePDFPrimaDomandaAnticipo(), commentoDomandaBandoId, domandaBando.getGroupId(), ctx.getUserId(), ctx.getPortalURL(),
                                    bando.getCodice(), contesto, CodiceTemplatePdf.SECONDA_DOMANDA_ANTICIPO.name(), "approvazione-seconda-domanda-anticipo-", "Approvazione seconda domanda anticipo bando '", anticipazioneInfo);
                        }catch(Exception e){
                            commentoDomandaBandoLocalService.deleteCommentoDomandaBando(commentoDomandaBandoId);
                            throw new RuntimeException("Errore durante la generazione del documento della seconda domanda di anticipo, ID: " + domandaBandoId);
                        }
                    }
                }

            }

            if(ListUtil.isNotNull(domandaBandoDatoAggiuntivoSaldo) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivoSaldo)){
                Iterator<DomandaBandoDatoAggiuntivo> it = domandaBandoDatoAggiuntivoSaldo.iterator();

                while(it.hasNext() && !domandaDiSecondoAnticipoTrovata){
                    DomandaBandoDatoAggiuntivo datoAggiuntivo = it.next();

                    switch(tipologiaEnteBando){
                        case ENTE_ECCLESIASTICO:
                            if(Validator.isNotNull(datoAggiuntivo) && datoAggiuntivo.getValore().equalsIgnoreCase(FormEsecuzione.DOMANDA_DI_SALDO_PATRIMONIO_CULTURALE.name().toLowerCase())){
                                domandaDiSecondoAnticipoTrovata = true;
                                domandaBandoDatoAggiuntivoLocalService.deleteDomandaBandoDatoAggiuntivo(datoAggiuntivo);
                            }
                            break;
                        case COMUNE:
                        case IMPRESA:
                        case LIBERO_PROFESSIONISTA:
                            if(Validator.isNotNull(datoAggiuntivo) && datoAggiuntivo.getValore().equalsIgnoreCase(FormEsecuzione.DOMANDA_DI_SALDO_PATRIMONIO_CULTURALE_AC.name().toLowerCase())){
                                domandaDiSecondoAnticipoTrovata = true;
                                domandaBandoDatoAggiuntivoLocalService.deleteDomandaBandoDatoAggiuntivo(datoAggiuntivo);
                            }
                            break;
                    }

                }
            }

            if (Validator.isNotNull(domandaBando)) {
                DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivoLocalService.createDomandaBandoDatoAggiuntivo(counterLocalService.increment());
                domandaBandoDatoAggiuntivo.setChiave(DatoAggiuntivoChiave.FORM_ESECUZIONE_NON_ABILITATO.name());
                domandaBandoDatoAggiuntivo.setValore(ScrivaniaOperatoreBandiPortletKeys.DOCUMENTAZIONE_INTEGRATIVA_SECONDA_DOMANDA_DI_ANTICIPO);
                domandaBandoDatoAggiuntivo.setDomandaBandoId(domandaBando.getDomandaBandoId());
                domandaBandoDatoAggiuntivo.setCompanyId(domandaBando.getCompanyId());
                domandaBandoDatoAggiuntivo.setUserId(domandaBando.getUserId());
                domandaBandoDatoAggiuntivo.setUserName(domandaBando.getUserName());
                domandaBandoDatoAggiuntivo.setGroupId(domandaBando.getGroupId());
                domandaBandoDatoAggiuntivoLocalService.updateDomandaBandoDatoAggiuntivo(domandaBandoDatoAggiuntivo);
            }

            try{
                attivitaDomandaBandoList = attivitaDomandaBandoLocalService.getAttivitaDomandaBandoByDomandaBandoId(domandaBandoId);

            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            if (Validator.isNotNull(attivitaDomandaBandoList) && !attivitaDomandaBandoList.isEmpty() ){
                attivitaDomandaBando = attivitaDomandaBandoList.get(attivitaDomandaBandoList.size() -1);

                if(Validator.isNotNull(attivitaDomandaBando)) {
                    if (Validator.isNotNull(attivitaDomandaBando.getNote())) {
                        attivitaDomandaBando.setNote(attivitaDomandaBando.getNote() + '|' + APPROVAZIONE_SECONDA_DOMANDA_DI_ANTICIPO);
                    } else {
                        attivitaDomandaBando.setNote(APPROVAZIONE_SECONDA_DOMANDA_DI_ANTICIPO);
                    }
                    attivitaDomandaBandoLocalService.updateAttivitaDomandaBando(attivitaDomandaBando);
                }

            }

            try {
                sendNotificaApprovazione(domandaBandoId, TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO);
            }catch (Exception e) {
                log.error(e.getMessage(), e);
            }

        }
    }

