    private boolean checkPrendiInCaricaAbilitato(DomandaBando domandaBando) {
        boolean checkPrendiInCaricaAbilitato = true;
        List<BandoForm> bandoFormList = bandoFormLocalService.getListaBandoFormBandoAndType(domandaBando.getBandoId(), TipoFormEnum.INTEGRAZIONE_FRONTEND.name());
        if (ListUtil.isNotEmpty(bandoFormList) && bandoFormList.size() == 1) {
            Long formId = bandoFormList.get(0).getFormId();
            List<IstanzaDomandaBando> istanzaDomandaBandoList = istanzaDomandaBandoLocalService.getListIstanzaDomandaBandoByDomandaBandoIdAndListaFormId(domandaBando.getDomandaBandoId(), Collections.singletonList(formId));
            if (ListUtil.isNotEmpty(istanzaDomandaBandoList)) {
                for (IstanzaDomandaBando istanzaDomandaBando :istanzaDomandaBandoList) {
                    DomandaBandoIntegrazione domandaBandoIntegrazione = domandaBandoIntegrazioneLocalService.fetchDomandaBandoIntegrazione(istanzaDomandaBando.getIstanzaDomandaBandoId());
                    if (Validator.isNull(domandaBandoIntegrazione)) {
                        checkPrendiInCaricaAbilitato = false;
                        break;
                    }
                }
            }
        }

        return checkPrendiInCaricaAbilitato;
    }

    public boolean checkIstanzeSenzaProtocollazione(DomandaBando domandaBando) throws PortalException {

        long bandoId = domandaBando.getBandoId();
        Bando bando = bandoLocalService.getBando(bandoId);

        boolean protocollaIntegrazioni = bando.getProtocollaIntegrazioni();
        if (protocollaIntegrazioni) {
            //Verifica protocollazioni su istanze domanda bando
            List<IstanzaDomandaBando> istanzeDomandeBandoByDomandaBandoId = istanzaDomandaBandoLocalService.getIstanzeDomandeBandoByDomandaBandoId(domandaBando.getDomandaBandoId());
            if (ListUtil.isNotEmpty(istanzeDomandeBandoByDomandaBandoId)) {
                for (IstanzaDomandaBando istanzaDomandaBando : istanzeDomandeBandoByDomandaBandoId) {
                    //Verifica solo form integrativi
                    Form form = formLocalService.getForm(istanzaDomandaBando.getFormId());
                    if (form.isPrincipale()) {
                        continue;
                    }
                    try {
                        DomandaBandoIntegrazione domandaBandoIntegrazione = domandaBandoIntegrazioneLocalService.getDomandaBandoIntegrazione(istanzaDomandaBando.getIstanzaDomandaBandoId());
                        if (domandaBandoIntegrazione == null || (Validator.isNull(domandaBandoIntegrazione.getNumeroProtocollo()) && domandaBandoIntegrazione.getDataProtocollo() == null)) {
                            return true;
                        }
                    } catch (PortalException e) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    public Long getIdPrimaDomanda(List<DomandaBando> listaDomandeBando,long bandoId, boolean checkBandoIsAvvisoSportelloConValutazione, TipologiaBando tipologiaBando,ServiceContext serviceContext){
        Long idPrimaDomanda = null;

        if (listaDomandeBando != null && !listaDomandeBando.isEmpty()) {
            for (DomandaBando domandaBando : listaDomandeBando) {

                if (!domandaBando.getStato().equals(StatoDomandaBandoEnum.CHIUSA_NEGATIVAMENTE.name())
                        && !domandaBando.getStato().equals(StatoDomandaBandoEnum.ASSENZA_GIUSTIFICATA.name())
                        && !domandaBando.getStato().equals(StatoDomandaBandoEnum.ASSENZA_NON_GIUSTIFICATA.name())
                        && !domandaBando.getStato().equals(StatoDomandaBandoEnum.ANNULLATA.name())
                        && !domandaBando.getStato().equals(StatoDomandaBandoEnum.BOZZA.name())
                        && !domandaBando.getStato().equals(StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA.name())) {

                    List<ValutazioneAmmissibilita> listaValutazioniAmmissibilita =
                            valutazioneAmmissibilitaLocalService.getValutazioneAmissibilitaDomandaBando(domandaBando.getDomandaBandoId());

                    if (idPrimaDomanda == null &&
                            (listaValutazioniAmmissibilita == null || listaValutazioniAmmissibilita.isEmpty())) {
                        idPrimaDomanda = domandaBando.getDomandaBandoId();
                        break;
                    }

                    if (idPrimaDomanda == null
                            && Validator.isNotNull(listaValutazioniAmmissibilita)
                            && listaValutazioniAmmissibilita.size() == 1
                            && !listaValutazioniAmmissibilita.get(0).getEsito().equals(AmmissibilitaEnum.NON_AMMISSIBILE.name())
                            && !listaValutazioniAmmissibilita.get(0).getEsito().equals(AmmissibilitaEnum.AMMISSIBILE_CON_RISERVA.name())
                            && domandaBando.getImportoAssegnato() == null
                            && !domandaBando.getImportoConfermato()) {

                        if (checkBandoIsAvvisoSportelloConValutazione) {
                            List<Valutazione> listaValutazioni =
                                    valutazioneLocalService.getValutazioneByDomandaBandoId(domandaBando.getDomandaBandoId());

                            if (idPrimaDomanda == null
                                    && (listaValutazioni == null || listaValutazioni.isEmpty())) {
                                idPrimaDomanda = domandaBando.getDomandaBandoId();
                                break;
                            }

                            if (idPrimaDomanda == null
                                    && Validator.isNotNull(listaValutazioni)
                                    && listaValutazioni.size() == 1
                                    && !checkNonIdoneitaPunteggioAvvisoSportelloValutazione(domandaBando.getDomandaBandoId())) {
                                idPrimaDomanda = domandaBando.getDomandaBandoId();
                                break;
                            }

                            if (idPrimaDomanda == null
                                    && Validator.isNotNull(listaValutazioni)
                                    && listaValutazioni.size() == 1
                                    && checkNonIdoneitaPunteggioAvvisoSportelloValutazione(domandaBando.getDomandaBandoId())
                                    && !listaValutazioni.get(0).getConvalidata()) {
                                idPrimaDomanda = domandaBando.getDomandaBandoId();
                                break;
                            }
                        } else {
                            List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoList = domandaBandoDatoAggiuntivoLocalService.
                                    getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(Arrays.asList(domandaBando.getDomandaBandoId()), Arrays.asList(DatoAggiuntivoChiave.DATA_CONFERMA_EVENTO.name()));

                            if(ListUtil.isNull(domandaBandoDatoAggiuntivoList) || ListUtil.isEmpty(domandaBandoDatoAggiuntivoList)){
                                idPrimaDomanda = domandaBando.getDomandaBandoId();
                                break;
                            }
                        }
                    }
                }
            }
        }
        return idPrimaDomanda;
    }

    public AccountDto getEmailAccountByBandoId(long bandoId) {
        Bando bando = bandoLocalService.fetchBando(bandoId);
        return getEmailAccountByBando(bando);
    }

    public AccountDto getEmailAccountByBando(Bando bando) {
        try {
            AccountDto emailAccount = null;
            if (bando.isMailEnabled()) {
                emailAccount = new AccountDto();
                KeystoreCryptoUtilProps keystoreUtil = new KeystoreCryptoUtilProps();
                String passwordDec = keystoreUtil.decrypt(bando.getMailPassword());

                emailAccount = new AccountDto();
                emailAccount.setHost(bando.getMailHost());
                emailAccount.setPort(bando.getMailPort());
                emailAccount.setProtocol(bando.getMailProtocol());
                emailAccount.setUsername(bando.getMailUsername());
                emailAccount.setPassword(passwordDec);
                emailAccount.setSocketPort(bando.getMailSocketFactoryPort());
                emailAccount.setAuth(String.valueOf(bando.getMailAuth()));
                emailAccount.setStarttls(bando.getMailStartTlsEnabled());
                emailAccount.setDebug(bando.getMailDebug());
                emailAccount.setStarttlsRequired(bando.getMailStartTlsRequired());
                emailAccount.setSocketFactoryFallback(bando.getMailSocketFactoryPortFallback());
                emailAccount.setFrom(bando.getMailFrom());
                emailAccount.setSslProtocols(bando.getMailProtocols());
            }
            return emailAccount;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Retrieves protocol information for anticipazione forms (prima or seconda)
     * Returns a Map with keys: "testoAntipazione", "numeroProtocollo", "dataProtocollo"
     */
    public Map<String, String> getAnticipazioneProtocolInfo(long domandaBandoId, long bandoId, List<Long> integrazioni) {
        Map<String, String> result = new HashMap<>();
        result.put(TESTO_ANTICIPAZIONE, "");
        result.put("numeroProtocollo", "");
        result.put("dataProtocollo", "");

        try {
            String TIPO_FORM_INTEGRATIVA_PRIMA = "domanda-integrativa-prima-anticipazione-patrimonio-culturale";
            String TIPO_FORM_INTEGRATIVA_SECONDA = "domanda-integrativa-seconda-anticipazione-patrimonio-culturale";
            String TIPO_FORM_INTEGRATIVA_SALDO = "domanda-integrativa-di-saldo-patrimonio-culturale";


            String testoAntipazione = null;
            String[] codiciFormsToSearch = null;

            for (Long formId : integrazioni) {
                Form form = formLocalService.getForm(formId);

                if (form != null) {

                    if (TIPO_FORM_INTEGRATIVA_PRIMA.equals(form.getCodice())) {
                        testoAntipazione = "di prima anticipazione";
                        codiciFormsToSearch = new String[]{FormEsecuzione.DOMANDA_PRIMA_ANTICIPAZIONE_PATRIMONIO_CULTURALE_AC.name(), FormEsecuzione.DOMANDA_PRIMA_ANTICIPAZIONE_PATRIMONIO_CULTURALE.name()};
                        break;
                    } else if (TIPO_FORM_INTEGRATIVA_SECONDA.equals(form.getCodice())) {
                        testoAntipazione = "di seconda anticipazione";
                        codiciFormsToSearch = new String[]{FormEsecuzione.DOMANDA_SECONDA_ANTICIPAZIONE_PATRIMONIO_CULTURALE_AC.name(), FormEsecuzione.DOMANDA_SECONDA_ANTICIPAZIONE_PATRIMONIO_CULTURALE.name()};
                        break;
                    } else if (TIPO_FORM_INTEGRATIVA_SALDO.equals(form.getCodice())) {
                        testoAntipazione = "di saldo";
                        codiciFormsToSearch = new String[]{FormEsecuzione.DOMANDA_DI_SALDO_PATRIMONIO_CULTURALE_AC.name(), FormEsecuzione.DOMANDA_DI_SALDO_PATRIMONIO_CULTURALE.name()};
                        break;
                    }
                }
            }

            if (testoAntipazione != null && codiciFormsToSearch != null) {
                for (String codiceForm : codiciFormsToSearch) {
                    try {
                        Form form = formLocalService.getFormByCodice(codiceForm);

                        if (form != null) {
                            IstanzaDomandaBando istanza = istanzaDomandaBandoLocalService.getIstanzaDomandaBandoByDomandaBandoIdAndFormId(domandaBandoId, form.getFormId());

                            if (istanza != null) {
                                long istanzaDomandaBandoId = istanza.getIstanzaDomandaBandoId();

                                DomandaBandoIntegrazione integrazione = domandaBandoIntegrazioneLocalService.fetchDomandaBandoIntegrazione(istanzaDomandaBandoId);

                                if (integrazione != null) {
                                    String numeroProtocollo = integrazione.getNumeroProtocollo();
                                    Date dataProtocollo = integrazione.getDataProtocollo();

                                    if (Validator.isNotNull(numeroProtocollo)) {
                                        result.put("numeroProtocollo", numeroProtocollo);
                                    }

                                    if (dataProtocollo != null) {
                                        SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");
                                        result.put("dataProtocollo", sdf.format(dataProtocollo));
                                    }

                                    result.put(TESTO_ANTICIPAZIONE, testoAntipazione);
                                    return result;
                                }
                            }
                        }


                    } catch (Exception e) {
                        log.debug("Could not find istanza for form: " + codiceForm, e);
                    }
                }
            }
        } catch (Exception e) {
            log.error("Error retrieving anticipazione protocol info", e);
        }

        return result;
    }

