    /**
     * Verifica se per la domanda bando indicata è attivo il campo oggetto nelle modali operatore.
     * Il flag {@link CodiceDatoBandoEnum#DISABILITA_CAMPO_OGGETTO} funziona come attivatore: valore "true" => il
     * campo oggetto viene mostrato ed è obbligatorio.
     */
    public boolean isCampoOggettoAttivo(long domandaBandoId) {
        DomandaBando domandaBando = domandaBandoLocalService.fetchDomandaBando(domandaBandoId);
        if (domandaBando == null) {
            return false;
        }
        return isDatoBandoFlagAttivo(domandaBando.getBandoId(), CodiceDatoBandoEnum.DISABILITA_CAMPO_OGGETTO);
    }

    /**
     * Verifica generica sul valore di un flag booleano censito tra i {@link CodiceDatoBandoEnum} per il bando indicato.
     * I flag DISABILITA_* funzionano come attivatori: valore "true" => funzionalità attiva.
     */
    private boolean isDatoBandoFlagAttivo(long bandoId, CodiceDatoBandoEnum codice) {
        try {
            DatoBando datoBando = datoBandoLocalService.findByCodice(codice.name());
            if (datoBando != null) {
                List<ValoreDatoBando> valori = valoreDatoBandoLocalService.findByBandoIdAndDatoBandoId(bandoId, datoBando.getDatoBandoId());
                if (valori != null && !valori.isEmpty()) {
                    return "true".equals(valori.get(0).getValore());
                }
            }
        } catch (Exception e) {
            log.error("Errore nel recupero del flag " + codice.name() + " per bandoId=" + bandoId + ": " + e.getMessage(), e);
        }
        return false;
    }

    public List<CriterioValutazioneDTO> getListaCriteriValutazioneBando(long domandaBandoId) throws PortalException {
        List<CriterioValutazioneDTO> listaCriteri = new ArrayList<>();
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);
        Bando bando = bandoLocalService.getBando(domandaBando.getBandoId());
        if (Validator.isNotNull(bando)) {
            List<CriterioValutazione> listaCriteriModel = criterioValutazioneLocalService.getCriterioValutazioneByBandoIdAndNotCodice(bando.getBandoId(),bando.getCodice() + "_" + GestioneBandiCommonConstants.CODICE_CRIT_PUNTEGGIO_TOT);
            List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoList =
                    domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
                            List.of(domandaBandoId), List.of(DatoAggiuntivoChiave.PUNTEGGIO_AUTOVALUTAZIONE.name()));
            if (listaCriteriModel != null && !listaCriteriModel.isEmpty()) {
                for (CriterioValutazione criterio : listaCriteriModel) {
                    if (Validator.isNotNull(criterio)) {
                        CriterioValutazioneDTO criterioValutazione = new CriterioValutazioneDTO();
                        criterioValutazione.setCriterioValutazioneId(criterio.getCriterioValutazioneId());
                        criterioValutazione.setDescrizione(criterio.getDescrizione());
                        criterioValutazione.setPunteggioMassimo(criterio.getPunteggioMassimo());
                        criterioValutazione.setPunteggioMinimo(criterio.getPunteggioMinimo());
                        criterioValutazione.setSogliaMinima(criterio.getSogliaMinima());
                        criterioValutazione.setOrdine(criterio.getOrdine());
                        criterioValutazione.setCriterioParentId(criterio.getCriterioParentId());
                        if (domandaBandoDatoAggiuntivoList!=null && !domandaBandoDatoAggiuntivoList.isEmpty()) {
                            criterioValutazione.setPunteggioAutovalutazione(findPunteggioAutovalutazioneByOrdine(domandaBandoDatoAggiuntivoList, criterioValutazione.getOrdine()));
                        }
                        listaCriteri.add(criterioValutazione);
                    }
                }
            }
        }

        return listaCriteri;
    }

    private void aggiornaValutazioniDomandaBando(GraduatoriaBando graduatoriaBando) {

        if(Validator.isNotNull(graduatoriaBando)) {

            long bandoId = graduatoriaBando.getBandoId();

            if(graduatoriaBando.getDefinitiva()) {
                GraduatoriaBando graduatoriaProvvisoria = graduatoriaBandoLocalService.getGraduatoriaBandoByBandoIdAndDefinitivaAndConvalidata(bandoId, false, true);

                if(Validator.isNotNull(graduatoriaProvvisoria)) {
                    List<Valutazione> valutazioniProvvisorie = valutazioneLocalService.getValutazioneByGraduatoriaBandoId(graduatoriaProvvisoria.getGraduatoriaBandoId());
                    List<Valutazione> valutazioniDefinitive = valutazioneLocalService.getValutazioneByGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());
                    List<ValutazioneAmmissibilita> valutazioniAmmissibilitaProvvisorie = valutazioneAmmissibilitaLocalService.getValutazioneAmissibilitaByGraduatoriaBandoId(graduatoriaProvvisoria.getGraduatoriaBandoId());
                    List<ValutazioneAmmissibilita> valutazioniAmmissibilitaDefinitive = valutazioneAmmissibilitaLocalService.getValutazioneAmissibilitaByGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());

                    if(Validator.isNull(valutazioniDefinitive) || (Validator.isNotNull(valutazioniDefinitive) && valutazioniDefinitive.isEmpty())) {
                        if(valutazioniProvvisorie!=null && !valutazioniProvvisorie.isEmpty()) {
                            for(Valutazione valutazioneProvvisoria : valutazioniProvvisorie) {
                                if(Validator.isNotNull(valutazioneProvvisoria)) {
                                    Valutazione valutazioneDefinitiva = valutazioneLocalService.createValutazione(counterLocalService.increment());
                                    valutazioneDefinitiva.setDataValutazione(valutazioneProvvisoria.getDataValutazione());
                                    valutazioneDefinitiva.setDomandaBandoId(valutazioneProvvisoria.getDomandaBandoId());
                                    valutazioneDefinitiva.setGroupId(valutazioneProvvisoria.getGroupId());
                                    valutazioneDefinitiva.setUserId(valutazioneProvvisoria.getUserId());
                                    valutazioneDefinitiva.setUserName(valutazioneProvvisoria.getUserName());
                                    valutazioneDefinitiva.setGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());
                                    valutazioneDefinitiva.setConvalidata(true);
                                    valutazioneDefinitiva = valutazioneLocalService.updateValutazione(valutazioneDefinitiva);

                                    List<Punteggio> punteggiValutazioneProvvisoria = punteggioLocalService.getListaPunteggiByValutazioneId(valutazioneProvvisoria.getValutazioneId());

                                    if(punteggiValutazioneProvvisoria!=null && !punteggiValutazioneProvvisoria.isEmpty()) {
                                        for(Punteggio punteggioProvvisorio : punteggiValutazioneProvvisoria) {
                                            if(Validator.isNotNull(punteggioProvvisorio)) {
                                                Punteggio punteggioDefinitivo = punteggioLocalService.createPunteggio(counterLocalService.increment());

                                                punteggioDefinitivo.setValore(punteggioProvvisorio.getValore());

                                                if(Validator.isNotNull(punteggioProvvisorio.getNote())) {
                                                    punteggioDefinitivo.setNote(punteggioProvvisorio.getNote());
                                                }

                                                punteggioDefinitivo.setValutazioneId(valutazioneDefinitiva.getValutazioneId());
                                                punteggioDefinitivo.setCriterioValutazioneId(punteggioProvvisorio.getCriterioValutazioneId());
                                                punteggioDefinitivo.setGroupId(punteggioProvvisorio.getGroupId());
                                                punteggioDefinitivo.setUserId(punteggioProvvisorio.getUserId());
                                                punteggioDefinitivo.setUserName(punteggioProvvisorio.getUserName());

                                                punteggioLocalService.updatePunteggio(punteggioDefinitivo);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if(Validator.isNull(valutazioniAmmissibilitaDefinitive) || (Validator.isNotNull(valutazioniAmmissibilitaDefinitive) && valutazioniAmmissibilitaDefinitive.isEmpty())) {
                        if(valutazioniAmmissibilitaProvvisorie!=null && !valutazioniAmmissibilitaProvvisorie.isEmpty()) {

                            for(ValutazioneAmmissibilita valutazioneAmmissibilita : valutazioniAmmissibilitaProvvisorie) {
                                if(Validator.isNotNull(valutazioneAmmissibilita)) {
                                    ValutazioneAmmissibilita valutazioneAmmissibilitaDefinitiva = valutazioneAmmissibilitaLocalService.createValutazioneAmmissibilita(counterLocalService.increment());
                                    valutazioneAmmissibilitaDefinitiva.setGroupId(valutazioneAmmissibilita.getGroupId());
                                    valutazioneAmmissibilitaDefinitiva.setUserId(valutazioneAmmissibilita.getUserId());
                                    valutazioneAmmissibilitaDefinitiva.setUserName(valutazioneAmmissibilita.getUserName());
                                    valutazioneAmmissibilitaDefinitiva.setEsito(valutazioneAmmissibilita.getEsito());
                                    valutazioneAmmissibilitaDefinitiva.setDomandaBandoId(valutazioneAmmissibilita.getDomandaBandoId());
                                    valutazioneAmmissibilitaDefinitiva.setGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());
                                    valutazioneAmmissibilitaDefinitiva.setConvalidata(true);
                                    valutazioneAmmissibilitaLocalService.updateValutazioneAmmissibilita(valutazioneAmmissibilitaDefinitiva);
                                }
                            }
                        }
                    }

                }
            }else {

                List<Valutazione> listaValutazioni = valutazioneLocalService.findByBando(bandoId);
                List<ValutazioneAmmissibilita> valutazioniAmmissibilita = valutazioneAmmissibilitaLocalService.getValutazioneAmissibilitaByBandoId(bandoId);

                if(listaValutazioni!=null && !listaValutazioni.isEmpty()) {
                    for(Valutazione valutazione : listaValutazioni) {
                        if(Validator.isNotNull(valutazione)) {
                            valutazione.setGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());
                            valutazioneLocalService.updateValutazione(valutazione);
                        }
                    }
                }

                if(valutazioniAmmissibilita!=null && !valutazioniAmmissibilita.isEmpty()) {
                    for(ValutazioneAmmissibilita valutazioneAmmissibilita : valutazioniAmmissibilita) {
                        if(Validator.isNotNull(valutazioneAmmissibilita)) {
                            valutazioneAmmissibilita.setGraduatoriaBandoId(graduatoriaBando.getGraduatoriaBandoId());
                            valutazioneAmmissibilitaLocalService.updateValutazioneAmmissibilita(valutazioneAmmissibilita);
                        }
                    }
                }
            }
        }
    }

    public List<IstanzaDomandaBando> getIstanzeEsecuzione(long bandoId, long domandaBandoId, List<String> elencoTipoForm) throws PortalException {

        List<BandoForm> listaBandoForm = new ArrayList<>();
        List<IstanzaDomandaBando> istanze;

        for(String s: elencoTipoForm) {
            List<BandoForm> list = bandoFormLocalService.getListaBandoFormBandoAndType(bandoId, s);

            if(Validator.isNotNull(list)) {
                listaBandoForm.addAll(list);
            }
        }

        List<Long> listaFormId = listaBandoForm.stream()
                .map(BandoForm::getFormId)
                .collect(Collectors.toList());

        istanze = istanzaDomandaBandoLocalService.getListIstanzaDomandaBandoByDomandaBandoIdAndListaFormId(domandaBandoId, listaFormId);

        return istanze;
    }

    public List<IntegrazioneRichiestaDTO> getRichiesteIntegrazioni(long domandaBandoId, long bandoId, int start, int end) {
        List<String> tipiDaEscludere;
        Bando bando = bandoLocalService.fetchBando(bandoId);
        if(bando.getAbilitaEsecuzioneIntegrazione()){
            tipiDaEscludere = Arrays.asList(
                    TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name(),
                    TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name(),
                    TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name(),
                    TipoFormEnum.ESECUZIONE_SALDO.name(),
                    TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name(),
                    TipoFormEnum.ESECUZIONE_ANTICIPO.name(),
                    TipoFormEnum.ESECUZIONE_RINUNCIA.name(),
                    TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name(),
                    TipoFormEnum.ESECUZIONE.name(),
                    TipoFormEnum.ESECUZIONE_CRONOPROGRAMMA.name()
            );
        }else{
            tipiDaEscludere = Arrays.asList(
                    TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name(),
                    TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name(),
                    TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name(),
                    TipoFormEnum.ESECUZIONE_SALDO.name(),
                    TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name(),
                    TipoFormEnum.ESECUZIONE_ANTICIPO.name()
            );
        }

        List<BandoForm> listaBandoFormDaEscludere = new ArrayList<>();
        for (String tipo : tipiDaEscludere) {
            List<BandoForm> forms = bandoFormLocalService.getListaBandoFormBandoAndType(bandoId, tipo);
            if (Validator.isNotNull(forms)) {
                listaBandoFormDaEscludere.addAll(forms);
            }
        }
        List<Long> formIdDaEscluderePerTipo = listaBandoFormDaEscludere.stream()
                .map(BandoForm::getFormId)
                .filter(Objects::nonNull)
                .collect(Collectors.toList());

        List<BandoForm> listaBandoForm = bandoFormLocalService.getListaBandoFormBando(bandoId);
        List<Long> tuttiFormIdDelBando = listaBandoForm.stream()
                .map(BandoForm::getFormId)
                .filter(Objects::nonNull)
                .collect(Collectors.toList());

        List<Form> formsPrincipali = formLocalService.getFormsByIdsAndPrincipale(tuttiFormIdDelBando);
        List<Long> formIdDaEscluderePerPrincipale = formsPrincipali.stream()
                .map(Form::getFormId)
                .filter(Objects::nonNull)
                .collect(Collectors.toList());

        Set<Long> formIdDaEscludere = new HashSet<>();
        formIdDaEscludere.addAll(formIdDaEscluderePerTipo);
        formIdDaEscludere.addAll(formIdDaEscluderePerPrincipale);

        List<IstanzaDomandaBando> istanzeFiltrate =
                istanzaDomandaBandoLocalService.getListIstanzaDomandaBandoByDomandaBandoIdAndNotListaFormId(
                        domandaBandoId,
                        new ArrayList<>(formIdDaEscludere)
                );

        List<IstanzaDomandaBando> paginated = istanzeFiltrate.stream()
                .sorted(Comparator.comparing(IstanzaDomandaBando::getCreateDate))
                .skip(start)
                .limit(end - start)
                .collect(Collectors.toList());

        return paginated.stream()
                .map(this::mapRichiestaIntegrazioni)
                .collect(Collectors.toList());
    }

