    public int countRichiesteServizioEsecuzione(long domandaBandoId, long bandoId) {
        List<String> tipiDaEscludere = Arrays.asList(
                TipoFormEnum.INTEGRAZIONE.name(),
                TipoFormEnum.INTEGRAZIONE_FRONTEND.name(),
                TipoFormEnum.INTEGRAZIONE_OPERATORE.name(),
                TipoFormEnum.INTEGRAZIONE_OPERATORE_ESECUZIONE.name(),
                TipoFormEnum.ANNULLAMENTO.name(),
                TipoFormEnum.QUESTIONARIO.name(),
                TipoFormEnum.ESECUZIONE_PRIMO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_SECONDO_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_SALDO.name(),
                TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name(),
                TipoFormEnum.ESECUZIONE_ANTICIPO.name(),
                TipoFormEnum.ESECUZIONE_RINUNCIA.name()
        );

        //Recupero i formId dei tipi da escludere
        List<Long> formIdDaEscludere = new ArrayList<>();
        for (String tipo : tipiDaEscludere) {
            List<BandoForm> forms = bandoFormLocalService.getListaBandoFormBandoAndType(bandoId, tipo);
            if (Validator.isNotNull(forms)) {
                formIdDaEscludere.addAll(forms.stream()
                        .map(BandoForm::getFormId)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList()));
            }
        }

        //Aggiungo i form principali
        List<Form> formsPrincipali = formLocalService.getFormsByIdsAndPrincipale(
                bandoFormLocalService.getListaBandoFormBando(bandoId)
                        .stream()
                        .map(BandoForm::getFormId)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList()));

        formIdDaEscludere.addAll(formsPrincipali.stream()
                .map(Form::getFormId)
                .filter(Objects::nonNull)
                .collect(Collectors.toList()));

        return (int) istanzaDomandaBandoLocalService.countIstanzeDomandaBandoExcludingStatesAndForms(
                domandaBandoId,
                Collections.singletonList(StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA.name()),
                formIdDaEscludere
        );
    }

    public String getFormIntegrativoPathDomandaBando(DomandaBando domandaBando, String renderUrl, String friendlyURL, String tipoModulo) throws PortalException {

        String paginaServizio = getPathDomandaBando(domandaBando);

        Layout layout = getLayoutFromDomandaBando(domandaBando);
        LayoutTypePortlet layoutTypePortlet = (LayoutTypePortlet) layout.getLayoutType();
        List<Portlet> allPortlets = layoutTypePortlet.getAllPortlets();
        String instancePortleId = null;
        if (allPortlets != null) {
            for (Portlet portlet : allPortlets) {
                if (portlet.getPortletName().equals(PRESENTATORE_FORMS_BANDI_PORTLET_ID)) {
                    instancePortleId = portlet.getPortletId();
                    break;
                }
            }
        }

        int startIndex = renderUrl.indexOf("p_p_id=") + 7;
        int endIndex = renderUrl.indexOf("&", startIndex);
        String portletId;
        if (endIndex != -1) {
            portletId = renderUrl.substring(startIndex, endIndex);
        }
        else {
            portletId = renderUrl.substring(startIndex);
        }
        paginaServizio += "?p_p_id=" + instancePortleId + "&_" + instancePortleId + "_mvcRenderCommandName=" + COMPILA_ISTANZA_FORM_INTEGRATIVO_MVC_RENDER_COMMAND_NAME + "&_" + instancePortleId
                + "_domandaBandoId=" + domandaBando.getDomandaBandoId() + "&_" + instancePortleId + "_iPId=" + portletId + "&_" + instancePortleId + "_frUrl=" + friendlyURL + "&_" + instancePortleId
                + "_tipoModulo=" + tipoModulo + "&_" + instancePortleId;

        return paginaServizio;

    }

