    public Form getFormBando(long bandoId) {
        try {
            List<BandoForm> listaBandoForm = bandoFormLocalService.getListaBandoFormBando(bandoId);
            boolean isPrincipale = false;
            int i = 0;
            Form form = null;
            if (Validator.isNotNull(listaBandoForm) && !listaBandoForm.isEmpty()) {
                while (isPrincipale == false && i < listaBandoForm.size()) {
                    BandoForm bandoForm = listaBandoForm.get(i);

                    if (Validator.isNotNull(bandoForm)) {
                        form = formLocalService.getForm(bandoForm.getFormId());

                        if (Validator.isNotNull(form)) {
                            if (form.isPrincipale()) {
                                form.setListaDefinizioneAllegato(definizioneAllegatoLocalService.getListaDefinizioneAllegatoByFormId(form.getFormId()));
                                isPrincipale = true;
                            }
                        }
                    }
                    i++;
                }
            }
            return form;

        }
        catch (PortalException e) {
            log.warn("getFormPrincipaleProcedura :: " + e.getMessage());
        }
        return null;
    }

    public String getTabsByUser(long userId, boolean visualizzazioneEventi) {
        User user;
        try {
            user = userLocalService.getUser(userId);
        } catch (PortalException e) {
            throw new RuntimeException(e);
        }

        boolean isAdmin = isAdmin(userId);
        boolean isGestoreCambioReferente = gestioneReferenteMiddlewareService.isGestoreCambioReferente(userId);

        List<String> tabs = new ArrayList<>();
        if (visualizzazioneEventi) {
            tabs.add("eventi.aperti");
            tabs.add("eventi.chiusi");
        } else {
            tabs.add("bandi.aperti");
            tabs.add("bandi.chiusi");
        }
        if (isGestoreCambioReferente && !visualizzazioneEventi) {
