    public List<GraduatoriaSoggettoDTO> recuperaDatiGraduatoria(long bandoId, boolean definitiva){
        List<GraduatoriaSoggettoDTO> listaGraduatoriaSoggettoDTO = new ArrayList<GraduatoriaSoggettoDTO>();
        GraduatoriaBando graduatoriaBando = graduatoriaBandoLocalService.getGraduatoriaBandoByBandoIdAndDefinitiva(bandoId, definitiva);

        if(Validator.isNotNull(graduatoriaBando)) {
            List<GraduatoriaSoggetto> listaGraduatoriaSoggetto = graduatoriaSoggettoLocalService.getListaGraduatoriaSoggettoPunteggioByGraduatoriaBando(graduatoriaBando.getGraduatoriaBandoId());

            if(listaGraduatoriaSoggetto!=null && !listaGraduatoriaSoggetto.isEmpty()) {
                List<GraduatoriaSoggetto> listaGraduatoriaSoggettoOrdinata = new ArrayList<GraduatoriaSoggetto>(listaGraduatoriaSoggetto);
                Collections.sort(listaGraduatoriaSoggettoOrdinata, Comparator.comparing(GraduatoriaSoggetto::getPosizione));

                for(GraduatoriaSoggetto graduatoriaSoggetto : listaGraduatoriaSoggettoOrdinata) {

                    if(Validator.isNotNull(graduatoriaSoggetto)) {
                        GraduatoriaSoggettoDTO graduatoriaSoggettoDTO = new GraduatoriaSoggettoDTO();
                        graduatoriaSoggettoDTO.setBandoId(bandoId);

                        if(Validator.isNotNull(graduatoriaSoggetto.getDomandaBando())) {
                            DomandaBando domandaBando = graduatoriaSoggetto.getDomandaBando();
                            ValutazioneAmmissibilita valutazione = valutazioneAmmissibilitaLocalService.getValutazioneAmmissibilitaByDomandaBandoAndGraduatoriaBando(domandaBando.getDomandaBandoId(), graduatoriaBando.getGraduatoriaBandoId());

                            if(Validator.isNotNull(domandaBando)) {
                                if(Validator.isNotNull(domandaBando.getDomandaBandoId())) {
                                    graduatoriaSoggettoDTO.setDomandaBandoId(domandaBando.getDomandaBandoId());
                                }

                                if(Validator.isNotNull(domandaBando.getTitoloProgetto())) {
                                    graduatoriaSoggettoDTO.setTitoloProgetto(domandaBando.getTitoloProgetto());
                                }

                                if(Validator.isNotNull(domandaBando.getRagioneSociale())) {
                                    graduatoriaSoggettoDTO.setRagioneSociale(domandaBando.getRagioneSociale());
                                }

                                if(Validator.isNotNull(domandaBando.getImportoAssegnato())) {
                                    graduatoriaSoggettoDTO.setImportoAssegnato(domandaBando.getImportoAssegnato());
                                }

                                if(Validator.isNotNull(domandaBando.getCostiAmmissibili())) {
                                    graduatoriaSoggettoDTO.setCostiAmmissibili(domandaBando.getCostiAmmissibili());
                                }

                                if(Validator.isNotNull(domandaBando.getStato())) {
                                    graduatoriaSoggettoDTO.setStatoDomandaBando(domandaBando.getStato());
                                }

                                if(Validator.isNotNull(graduatoriaSoggetto.getEsito())) {
                                    StatoGraduatoriaSoggettoEnum esito = StatoGraduatoriaSoggettoEnum.valueOf(graduatoriaSoggetto.getEsito());
                                    graduatoriaSoggettoDTO.setEsito(esito);
                                }

                                if(Validator.isNotNull(valutazione)) {

                                    if(Validator.isNotNull(valutazione.getEsito())) {

                                        AmmissibilitaEnum ammissibilita = AmmissibilitaEnum.valueOf(valutazione.getEsito());
                                        graduatoriaSoggettoDTO.setEsitoAmmissibilita(ammissibilita);

                                        graduatoriaSoggettoDTO.setConvalidaAmmissibilita(valutazione.getConvalidata());
                                        Valutazione valutazioneMerito = valutazioneLocalService.getValutazioneByGraduatoriaBandoAndDomandaBando(graduatoriaBando.getGraduatoriaBandoId(), domandaBando.getDomandaBandoId());

                                        if(Validator.isNotNull(valutazioneMerito)) {
                                            graduatoriaSoggettoDTO.setConvalidaValutazioneMerito(valutazioneMerito.getConvalidata());
                                            if(!valutazione.getConvalidata() && !StatoGraduatoriaSoggettoEnum.CHIUSA_CON_ESITO_NEGATIVO.equals(graduatoriaSoggettoDTO.getEsito())) {
                                                graduatoriaSoggettoDTO.setEsito(StatoGraduatoriaSoggettoEnum.RICHIESTA_NUOVA_VALUTAZIONE_AMMISSIBILITA);
                                            }else if(!valutazioneMerito.getConvalidata() && !StatoGraduatoriaSoggettoEnum.CHIUSA_CON_ESITO_NEGATIVO.equals(graduatoriaSoggettoDTO.getEsito())) {
                                                graduatoriaSoggettoDTO.setEsito(StatoGraduatoriaSoggettoEnum.RICHIESTA_NUOVA_VALUTAZIONE_MERITO);
                                            }
                                        }else {
                                            if(!valutazione.getConvalidata() && !StatoGraduatoriaSoggettoEnum.CHIUSA_CON_ESITO_NEGATIVO.equals(graduatoriaSoggettoDTO.getEsito())) {
                                                graduatoriaSoggettoDTO.setEsito(StatoGraduatoriaSoggettoEnum.RICHIESTA_NUOVA_VALUTAZIONE_AMMISSIBILITA);
                                            }
                                        }
                                    }
                                }
                            }
                        }


                        graduatoriaSoggettoDTO.setPunteggioTotale(graduatoriaSoggetto.getPunteggioTotale());


                        if(Validator.isNotNull(graduatoriaSoggetto.getNote())) {
                            graduatoriaSoggettoDTO.setNote(graduatoriaSoggetto.getNote());
                        }
                        if(Validator.isNotNull(graduatoriaSoggetto.getGraduatoriaBandoId())) {
                            graduatoriaSoggettoDTO.setGraduatoriaBandoId(graduatoriaSoggetto.getGraduatoriaBandoId());
                        }


                        listaGraduatoriaSoggettoDTO.add(graduatoriaSoggettoDTO);

                    }

                }
            }
        }

        return listaGraduatoriaSoggettoDTO;
    }

