    }

    public List<AllegatoDTO> getListaAllegati(long domandaBandoId, boolean interno, int start, int end) {
        List<AllegatoDomandaBando> listaAllegati = new ArrayList<AllegatoDomandaBando>();

        if (interno) {
            listaAllegati = allegatoDomandaBandoLocalService.getAllegatiByDomandaBandoIdAndInternoAndPrincipale(domandaBandoId, interno, false, start, end);
        } else {
            if (allegatiRichiedenteVisualizzabili(domandaBandoId)) {
                listaAllegati = allegatoDomandaBandoLocalService.getAllegatiByDomandaBandoIdAndFormCompilati(domandaBandoId, start, end);
            }
        }

        Set<Long> idsUsati = caricaIdsAllegatiUsati(domandaBandoId);
        return listaAllegati.stream()
                .map(allegato -> mapAllegato(allegato, idsUsati))
                .collect(Collectors.toList());
    }

    private Set<Long> caricaIdsAllegatiUsatiPerListaAllegati(List<AllegatoDomandaBando> allegati) {
        if (allegati == null || allegati.isEmpty()) {
            return Collections.emptySet();
        }
        long domandaBandoId = allegati.get(0).getDomandaBandoId();
        return caricaIdsAllegatiUsati(domandaBandoId);
    }

    private Set<Long> caricaIdsAllegatiUsati(long domandaBandoId) {
        List<Long> idsUsati = provvedimentoDomandaBandoAllegatoLocalService.getAllegatoDomandaBandoIdsUsati(domandaBandoId);
        if (idsUsati == null || idsUsati.isEmpty()) {
            return Collections.emptySet();
        }
        return new HashSet<>(idsUsati);
    }

    public int countAllegati(long domandaBandoId, boolean interno) {
        if (interno) {
            return allegatoDomandaBandoLocalService.countAllegati(domandaBandoId, interno);
        } else {
            // se è esterno verifico che il bando sia chiuso
            if (allegatiRichiedenteVisualizzabili(domandaBandoId)) {
                return allegatoDomandaBandoLocalService.countAllegati(domandaBandoId, interno);
            } else {
                return 0;
            }
        }
    }

    public Boolean allegatiRichiedenteVisualizzabili(long domandaBandoId) {
        Date today = new Date();
        DomandaBando domandaBando = domandaBandoLocalService.fetchDomandaBando(domandaBandoId);
        Bando bando = bandoLocalService.fetchBando(domandaBando.getBandoId());
        if (bando.isAbilitazioneVisibilitaAllegati()) {
            //Visibilita' allegati dopo chiusura bando
            if (today.before(bando.getDataFine())) {
                return false;
            } else {
                return true;
            }
        } else return true;
    }

    private AllegatoDTO mapAllegato(AllegatoDomandaBando allegatoDomandaBando, Set<Long> idsAllegatiUsati) {
        AllegatoDTO dto = new AllegatoDTO();

        // ID documentale e nome file dal DB: sempre disponibili.
        // Garantisce che il bottone download sia sempre attivo se il file e' registrato in DB,
        // anche quando Alfresco e' temporaneamente lento al render.
        dto.setIdDocumentale(allegatoDomandaBando.getIdDocumentale());
        dto.setNomeFile(allegatoDomandaBando.getNome());

        try {
            FileService fileService = fileServiceFactory.getActiveFileService();
            File requestFile = fileService.getRequestFile(
                    allegatoDomandaBando.getIdDocumentale(),
                    allegatoDomandaBando.getGroupId());

            if (Validator.isNotNull(requestFile)) {
                // Lo stream e' aperto eagerly da AlfrescoFileServiceImpl.getFile().
                // Lo chiudiamo subito senza consumarlo: il binario non serve al render
                // (download avviene fresh in DownloadFileResourceCommand al click).
                InputStream is = requestFile.getInputStream();
                if (is != null) {
                    try (InputStream toClose = is) {
                        // intenzionalmente vuoto: il binario non viene consumato qui
                    } catch (IOException ioe) {
                        log.warn("mapAllegato: errore chiusura stream allegato "
                                + allegatoDomandaBando.getIdDocumentale(), ioe);
                    }
                }
                dto.setDimensione(fileUtility.getHumanReadableSize(requestFile.getSize()));
            }
        } catch (Exception e) {
            // Alfresco non risponde: il file resta scaricabile via DownloadFileResourceCommand
            // (fresh fetch al click). Solo la dimensione non sara' mostrata in UI.
            log.warn("mapAllegato: impossibile recuperare metadata Alfresco per "
                    + allegatoDomandaBando.getIdDocumentale(), e);
        }

        dto.setDescrizione(allegatoDomandaBando.getTitolo());
        dto.setTitolo(allegatoDomandaBando.getTitolo());
        dto.setVisibileAlCittadino(allegatoDomandaBando.getVisibile());
        dto.setNomeOperatore(allegatoDomandaBando.getUserName());
        dto.setAllegatoDomandaBandoId(allegatoDomandaBando.getAllegatoDomandaBandoId());
        dto.setDataScadenza(allegatoDomandaBando.getDataScadenza());
        dto.setUsato(idsAllegatiUsati != null && idsAllegatiUsati.contains(allegatoDomandaBando.getAllegatoDomandaBandoId()));

        return dto;
    }

    public void annullaDomandaBando(ServiceContext serviceContext, long domandaBandoId, String variableVal, long allegatoAnnullamentoId) {

        try {
            DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

            String taskId = getTaskId(domandaBando);

            String tenantId = String.valueOf(serviceContext.getScopeGroup().getOrganizationId());
            User currentUser = userLocalService.getUser(serviceContext.getUserId());
            List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId, String.valueOf(domandaBandoId));

            if (tasksByBusinessKey != null) {

                for (Task task : tasksByBusinessKey) {
                    if (taskId.equalsIgnoreCase(task.getId()) && String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
                        List<Entry<String, Object>> variables = new ArrayList<>();

                        if (Validator.isNotNull(variableVal)) {
                            variables.add(new AbstractMap.SimpleEntry<>(CamundaCodiciOperazioniUtente.ESITO_PROCEDIMENTO.getValue(), variableVal));
                            variables.add(new AbstractMap.SimpleEntry<>(CamundaCodiciOperazioniUtente.COMUNICAZIONE_ESITO.getValue(), "SI"));
                            variables.add(new AbstractMap.SimpleEntry<>(CustomProcessVariablesBandi.ID_ALLEGATO_ANNULLAMENTO.name(), String.valueOf(allegatoAnnullamentoId)));
                        }
                        camundaClient.completeTaskMultiType(taskId, variables);
                        azioneOperatoreLocalService.addAzioneOperatore(serviceContext, domandaBandoId, serviceContext.getUserId(), new Date(),
                                AzioniOperatoreCodes.TIPO_OPERAZIONE_ANNULLAMENTO_DOMANDA.name());
                    }
                }
            }

        }
        catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public ValutazioneDTO createValutazioneDomandaBando(DomandaBando domandaBando) {

        ValutazioneDTO valutazioneDTO = new ValutazioneDTO();
        valutazioneDTO.setValutazioneAmmissibilita(AmmissibilitaEnum.NON_AMMISSIBILE.name());
        valutazioneDTO.setValutazioneMerito(false);

        try {
            MessageUtility messageUtility = new MessageUtility(ScrivaniaOperatoreBandiPortletKeys.BUNDLE_SYMBOLIC_NAME, Locale.ITALY);

            GraduatoriaBando graduatoriaProvvisoria = graduatoriaBandoLocalService.getGraduatoriaBandoByBandoIdAndDefinitiva(domandaBando.getBandoId(), false);
            GraduatoriaBando graduatoriaDefinitiva = graduatoriaBandoLocalService.getGraduatoriaBandoByBandoIdAndDefinitiva(domandaBando.getBandoId(), true);
            long graduatoriaBandoId = 0;

            if(Validator.isNotNull(graduatoriaProvvisoria)) {
                graduatoriaBandoId = graduatoriaProvvisoria.getGraduatoriaBandoId();
            }

            if(Validator.isNotNull(graduatoriaDefinitiva)) {
                graduatoriaBandoId = graduatoriaDefinitiva.getGraduatoriaBandoId();
            }

            ValutazioneAmmissibilita valutazioneAmmissibilita = valutazioneAmmissibilitaLocalService.getValutazioneAmmissibilitaByDomandaBandoAndGraduatoriaBando(domandaBando.getDomandaBandoId(), graduatoriaBandoId);



            if (Validator.isNotNull(valutazioneAmmissibilita) && Validator.isNotNull(valutazioneAmmissibilita.getEsito())) {

                if(valutazioneAmmissibilita.getEsito().equalsIgnoreCase(AmmissibilitaEnum.AMMISSIBILE.name())) {
                    valutazioneDTO.setValutazioneAmmissibilita(AmmissibilitaEnum.AMMISSIBILE.name());
                }

                if(valutazioneAmmissibilita.getEsito().equalsIgnoreCase(AmmissibilitaEnum.AMMISSIBILE_CON_RISERVA.name())) {
                    valutazioneDTO.setValutazioneAmmissibilita(AmmissibilitaEnum.AMMISSIBILE_CON_RISERVA.name());
                }

                String[] dettagliAmmissibilita = new String[]{valutazioneAmmissibilita.getUserName(), null, null};

                SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");
                dettagliAmmissibilita[1] = sdf.format(valutazioneAmmissibilita.getModifiedDate());
                sdf = new SimpleDateFormat("HH:mm");
                dettagliAmmissibilita[2] = sdf.format(valutazioneAmmissibilita.getModifiedDate());
                valutazioneDTO.setDettagliAmmissibilita(dettagliAmmissibilita);

                Valutazione valutazione = valutazioneLocalService.getValutazioneByGraduatoriaBandoAndDomandaBando(graduatoriaBandoId, domandaBando.getDomandaBandoId());
                if (Validator.isNotNull(valutazione)) {
                    valutazioneDTO.setValutazioneMerito(true);

                    List<Punteggio> punteggi = punteggioLocalService.getListaPunteggiByValutazioneId(valutazione.getValutazioneId());
                    if (Validator.isNotNull(punteggi) && !punteggi.isEmpty()) {
                        List<PunteggioDTO> punteggiList = new ArrayList<PunteggioDTO>();
                        BigDecimal punteggioTotale = BigDecimal.ZERO;

                        for(Punteggio p : punteggi){
                            CriterioValutazione criteriovalutazione = criterioValutazioneLocalService.fetchCriterioValutazione(p.getCriterioValutazioneId());
                            if (Validator.isNull(criteriovalutazione)) {
                                continue;
                            }
                            PunteggioDTO punteggioDTO = new PunteggioDTO();
                            punteggioDTO.setDescrizionePunteggio(criteriovalutazione.getDescrizione());
                            punteggioDTO.setValorePunteggio(p.getValore());
                            punteggioDTO.setNote(p.getNote());
                            punteggioDTO.setCriterioPunteggioTotale(false);

                            punteggioTotale = punteggioTotale.add(p.getValore());
                            punteggiList.add(punteggioDTO);
                        }

                        String[] dettagliPunteggiMerito = new String[]{valutazione.getUserName(), null, null};
                        sdf = new SimpleDateFormat("dd/MM/yyyy");
                        dettagliPunteggiMerito[1] = sdf.format(valutazione.getModifiedDate());
                        sdf = new SimpleDateFormat("HH:mm");
                        dettagliPunteggiMerito[2] = sdf.format(valutazione.getModifiedDate());

                        PunteggioDTO punteggioTotaleDto = new PunteggioDTO();
                        punteggioTotaleDto.setDescrizionePunteggio(messageUtility.getMessage("punteggio-totale"));
                        punteggioTotaleDto.setValorePunteggio(punteggioTotale);
                        punteggioTotaleDto.setCriterioPunteggioTotale(true);
                        punteggiList.add(punteggioTotaleDto);

                        valutazioneDTO.setDettagliPunteggiMerito(dettagliPunteggiMerito);
                        valutazioneDTO.setPunteggi(punteggiList);
                        valutazioneDTO.setPunteggioTotale(punteggioTotale);
                    }
                }

            }
        }catch(Exception e) {
            log.error("createValutazioneDomandaBando :: " + e.getMessage(), e);
        }

        return valutazioneDTO;

    }

    public boolean checkConvalide(long domandaBandoId, long graduatoriaBandoId) {
