    }

}
if (CamundaActionsVariable.VAR_COMPILA_REVOCA.getValue().equalsIgnoreCase(variable.getName())) {
    String valRichiesta = (String) variable.getValue();
    if (valRichiesta.equalsIgnoreCase("true")) {
        AzioneUtenteDTO e = new AzioneUtenteDTO();
        e.setCodiceAzioneUtente(variable.getName());
        e.setDescrizione("Richiedi Modifiche\\Compila revoca");
        retVal.add(e);
    }
}
